matmul_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32

__global__ void matmul_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int N) {
    // Thread index
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Block index
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Global Row and Column indices
    int Row = by * TILE_SIZE + ty;
    int Col = bx * TILE_SIZE + tx;

    float Cvalue = 0.0f;

    // Shared memory for tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Loop over all tiles required to compute C[Row, Col]
    int numTiles = (N + TILE_SIZE - 1) / TILE_SIZE;

    for (int t = 0; t < numTiles; ++t) {

        // Load tile from A into shared memory
        // Row is fixed for the thread, iterate columns by block
        int A_col = t * TILE_SIZE + tx;
        if (Row < N && A_col < N) {
            As[ty][tx] = A[Row * N + A_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile from B into shared memory
        // Col is fixed for the thread, iterate rows by block
        int B_row = t * TILE_SIZE + ty;
        if (B_row < N && Col < N) {
            Bs[ty][tx] = B[B_row * N + Col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        // Synchronize to ensure entire tile is loaded
        __syncthreads();

        // Compute partial dot product for this tile
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            Cvalue += As[ty][k] * Bs[k][tx];
        }

        // Synchronize to ensure calculation is done before loading next tile
        __syncthreads();
    }

    // Write result to global memory
    if (Row < N && Col < N) {
        C[Row * N + Col] = Cvalue;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D");

    int N = A.size(0);
    TORCH_CHECK(A.size(1) == N, "A must be square");
    TORCH_CHECK(B.size(0) == N && B.size(1) == N, "B must be square and dimensions must match");

    auto C = torch::empty({N, N}, A.options());

    dim3 threadsPerBlock(TILE_SIZE, TILE_SIZE);
    dim3 numBlocks((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<numBlocks, threadsPerBlock>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

