# This approach efficiently handles the large K dimension (reduction dimension) using block-level reduction.
gemv_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Warp Reduction Helper
// Sums values within a warp (32 threads) using shuffle instructions
__inline__ __device__ float warpReduceSum(float val) {
    for (int offset = 32 / 2; offset > 0; offset /= 2) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}

// Block Reduction Helper
// Sums values across the entire thread block
__inline__ __device__ float blockReduceSum(float val) {
    // Shared memory to store partial sums from each warp
    // Max threads per block is usually 1024, so we need at most 32 entries (1024/32)
    static __shared__ float shared[32];

    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    // 1. Perform reduction within each warp
    val = warpReduceSum(val);

    // 2. The first thread of each warp writes the result to shared memory
    if (lane == 0) {
        shared[wid] = val;
    }
    __syncthreads();

    // 3. The first warp loads the partial sums from shared memory
    // Only threads 0 to (num_warps - 1) need to participate
    val = (threadIdx.x < blockDim.x / 32) ? shared[threadIdx.x] : 0.0f;

    // 4. Perform final reduction within the first warp
    if (wid == 0) {
        val = warpReduceSum(val);
    }

    return val;
}

__global__ void gemv_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int K) {
    // Each block computes one row of the output (one element of C)
    int row = blockIdx.x;

    if (row < M) {
        float sum = 0.0f;

        // Grid Stride Loop over K dimension
        // Threads in the block process the row in parallel
        // Access pattern is coalesced: Thread i reads A[row, i], A[row, i + blockDim], etc.
        for (int k = threadIdx.x; k < K; k += blockDim.x) {
            // A is row-major (M, K), B is (K, 1)
            sum += A[row * K + k] * B[k];
        }

        // Reduce partial sums from all threads in the block to a single value
        sum = blockReduceSum(sum);

        // The first thread writes the final result for this row to global memory
        if (threadIdx.x == 0) {
            C[row] = sum;
        }
    }
}

