    dim3 block_size(32, 8);
    dim3 grid_size(((N / 4) + block_size.x - 1) / block_size.x, 
                   (M + block_size.y - 1) / block_size.y);

    skinny_matmul_kernel<<<grid_size, block_size>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
