# This kernel performs A (N, M, K) x B (K, L) -> C (N, M, L)
# It treats A as a (N*M, K) matrix to simplify the 3D tensor multiplication.
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16

__global__ void tiled_matmul_kernel(const float* __restrict__ A, 
                                   const float* __restrict__ B, 
                                   float* __restrict__ C, 
                                   int H, int K, int W) {
    // Shared memory for tiles of A and B
    __shared__ float tileA[TILE_SIZE][TILE_SIZE];
    __shared__ float tileB[TILE_SIZE][TILE_SIZE];

    int ty = threadIdx.y;
    int tx = threadIdx.x;
    int row = blockIdx.y * TILE_SIZE + ty;
    int col = blockIdx.x * TILE_SIZE + tx;

    float val = 0.0f;

    // Loop over the inner dimension K in tiles
    for (int m = 0; m < (K + TILE_SIZE - 1) / TILE_SIZE; ++m) {
        // Load tile from matrix A (H x K)
        if (row < H && (m * TILE_SIZE + tx) < K) {
            tileA[ty][tx] = A[row * K + m * TILE_SIZE + tx];
        } else {
            tileA[ty][tx] = 0.0f;
        }

        // Load tile from matrix B (K x W)
        if (col < W && (m * TILE_SIZE + ty) < K) {
            tileB[ty][tx] = B[(m * TILE_SIZE + ty) * W + col];
        } else {
            tileB[ty][tx] = 0.0f;
        }

        // Wait for all threads to load the tiles
        __syncthreads();

        // Compute partial dot product for this tile
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            val += tileA[ty][k] * tileB[k][tx];
        }

        // Wait for all threads to finish before loading next tile
        __syncthreads();
    }

    // Write final result to global memory
    if (row < H && col < W) {
        C[row * W + col] = val;
    }
