from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Matrix Multiplication (C = A^T * B)
# This kernel is optimized for the specific memory layout of the inputs:
# A is (K, M) row-major, B is (K, N) row-major.
# We compute C (M, N) where C_ij = sum_k (A_ki * B_kj).
# Since A and B are both row-major and we iterate along K (rows), this allows for
# coalesced memory accesses when loading tiles from both A and B.

matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32

__global__ void matmul_at_b_kernel(
    const float* __restrict__ A, 
    const float* __restrict__ B, 
    float* __restrict__ C, 
    int M, int N, int K) {

    // A: K x M
    // B: K x N
    // C: M x N

    // Block index mapping
    // bx (blockIdx.x) corresponds to N dimension (columns of C)
    // by (blockIdx.y) corresponds to M dimension (rows of C)
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread index mapping
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global row and column indices for C
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    // Shared memory for tiles of A and B
    __shared__ float s_A[TILE_SIZE][TILE_SIZE];
    __shared__ float s_B[TILE_SIZE][TILE_SIZE];

    float val = 0.0f;

    // Loop over the K dimension (reduction dimension) in steps of TILE_SIZE
    for (int t = 0; t < K; t += TILE_SIZE) {
        // Load tile of A into shared memory
        // We need the block of A starting at row 't' and column 'by * TILE_SIZE'.
        // Thread (ty, tx) loads A[(t + ty)][(by * TILE_SIZE + tx)].
        // This corresponds to a coalesced load because 'tx' varies fastest.
        if (t + ty < K && (by * TILE_SIZE + tx) < M) {
            s_A[ty][tx] = A[(t + ty) * M + (by * TILE_SIZE + tx)];
        } else {
            s_A[ty][tx] = 0.0f;
        }

        // Load tile of B into shared memory
        // We need the block of B starting at row 't' and column 'bx * TILE_SIZE'.
        // Thread (ty, tx) loads B[(t + ty)][(bx * TILE_SIZE + tx)].
        // This is also a coalesced load.
        if (t + ty < K && (bx * TILE_SIZE + tx) < N) {
            s_B[ty][tx] = B[(t + ty) * N + (bx * TILE_SIZE + tx)];
        } else {
            s_B[ty][tx] = 0.0f;
        }

        // Synchronize to ensure tiles are fully loaded
        __syncthreads();

        // Compute partial dot product for this tile
        // We need to calculate sum_{k=0}^{TILE_SIZE-1} (A[t+k][row] * B[t+k][col])
        // In our loaded shared memory:
        // A[t+k][row] corresponds to s_A[k][ty] 
        //   (because we loaded s_A[y][x] = A[t+y][by*32+x], so s_A[k][ty] is A[t+k][by*32+ty] which is A[t+k][row])
        // B[t+k][col] corresponds to s_B[k][tx]
        //   (because we loaded s_B[y][x] = B[t+y][bx*32+x], so s_B[k][tx] is B[t+k][bx*32+tx] which is B[t+k][col])

        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            val += s_A[k][ty] * s_B[k][tx];
        }

        // Synchronize before loading the next tile to avoid overwriting shared memory
        __syncthreads();
    }

    // Write result to global memory
    if (row < M && col < N) {
        C[row * N + col] = val;
    }
}

torch::Tensor matmul_at_b_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D");
    TORCH_CHECK(A.size(0) == B.size(0), "A and B must have same K dimension (dim 0)");

    int K = A.size(0);
    int M = A.size(1);
    int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 block(TILE_SIZE, TILE_SIZE);
    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (M + TILE_SIZE - 1) / TILE_SIZE);

    matmul_at_b_kernel<<<grid, block>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        M, N, K);

    return C;
}
"""

matmul_cpp_source = (
    "torch::Tensor matmul_at_b_cuda(torch::Tensor A, torch::Tensor B);"
)

# Compile the inline CUDA code
matmul_op = load_inline(
    name="matmul_at_b",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_kernel_source,
    functions=["matmul_at_b_cuda"],
    verbose=False,
    extra_cflags=["-O3"],
)

class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication C = A^T * B using custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_op = matmul_op

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs matrix multiplication A^T * B.

        Args:
            A: Input tensor of shape (K, M).
            B: Input tensor of shape (K, N).

        Returns:
            Output tensor of shape (M, N).
        """
        return self.matmul_op.matmul_at_b_cuda(A, B)

