# This implementation uses shared memory tiling and avoids bank conflicts.
matmul_transpose_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_transpose_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int N, int K) {
    // Shared memory tiles for A and B. 33 columns to avoid bank conflicts.
    __shared__ float sA[32][33]; 
    __shared__ float sB[32][33];

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Output matrix indices: row in [0, M), col in [0, N)
    int row = blockIdx.y * 32 + ty;
    int col = blockIdx.x * 32 + tx;

    float res = 0.0f;

    // Loop over the inner dimension K in chunks of 32
    for (int k_base = 0; k_base < K; k_base += 32) {
        // Load tile from A into shared memory. 
        // We need elements A[k_base...k_base+31, row] for the dot product.
        // Each thread (ty, tx) loads A[k_base + ty, blockIdx.y * 32 + tx].
        if (k_base + ty < K && (blockIdx.y * 32 + tx) < M)
            sA[ty][tx] = A[(k_base + ty) * M + (blockIdx.y * 32 + tx)];
        else
            sA[ty][tx] = 0.0f;

        // Load tile from B into shared memory.
        // Each thread (ty, tx) loads B[k_base + ty, blockIdx.x * 32 + tx].
        if (k_base + ty < K && col < N)
            sB[ty][tx] = B[(k_base + ty) * N + col];
        else
            sB[ty][tx] = 0.0f;

        __syncthreads();

        // Perform dot product for this tile
        // For C[row, col], we iterate over the loaded k-dimension p = 0...31.
        // The value A[k_base + p, row] is stored at sA[p][ty].
        // The value B[k_base + p, col] is stored at sB[p][tx].
        #pragma unroll
        for (int p = 0; p < 32; ++p) {
            res += sA[p][ty] * sB[p][tx];
        }
        __syncthreads();
    }

    // Write final result to C
    if (row < M && col < N) {
        C[row * N + col] = res;
    }
}

