import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Matrix Multiplication (A * B^T)
# This kernel optimizes the specific case where B is stored as (N, K)
# but we need to compute A (M, K) x B^T (K, N).
# This layout allows contiguous memory access for both A and B along the K dimension.
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 32

// Kernel computes C = A * B^T
// A: (M, K)
// B: (N, K) -> We treat B as B^T implicitly during computation
// C: (M, N)
__global__ void matmul_transposed_kernel(
    const float* __restrict__ A, 
    const float* __restrict__ B, 
    float* __restrict__ C, 
    int M, int N, int K) {

    // Block indices
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global row (A) and col (B) indices
    int row = by * BLOCK_SIZE + ty;
    int col = bx * BLOCK_SIZE + tx;

    // Shared memory buffers
    // Padding of +1 is used to avoid bank conflicts when accessing columns
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE + 1];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE + 1];

    float val = 0.0f;

    // Loop over tiles along the K dimension
    for (int m = 0; m < (K + BLOCK_SIZE - 1) / BLOCK_SIZE; ++m) {

        // Load tile from A
        // A is row-major. We need A[row, k].
        // Collaborative loading: each thread loads one element.
        int a_col = m * BLOCK_SIZE + tx;
        if (row < M && a_col < K) {
            As[ty][tx] = A[row * K + a_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile from B
        // We want to compute A * B^T.
        // C[row, col] involves dot product of A[row, :] and B[col, :].
        // Note: B is (N, K). "B[col, :]" refers to the row 'col' in B.
        // We load the tile of B corresponding to rows 'col_start' to 'col_end'
        // and columns 'k_start' to 'k_end'.
        // Mapping: Thread (ty, tx) loads B[b_row, b_col]
        // b_row corresponds to the global row index of B (which maps to output column index)
        int b_row = bx * BLOCK_SIZE + ty;
        int b_col = m * BLOCK_SIZE + tx;

        if (b_row < N && b_col < K) {
            Bs[ty][tx] = B[b_row * K + b_col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute dot product for this tile
        // We compute dot(row of A, row of B).
        // As[ty][k] accesses the row of A kept in shared memory.
        // Bs[tx][k] accesses the row of B kept in shared memory.
        // Notice we use 'tx' for Bs index. 
        //   - We loaded Bs such that Bs[ty][tx] holds B[bx*32 + ty][...].
        //   - The thread (ty, tx) is responsible for output C[row][col], where col = bx*32 + tx.
        //   - So this thread needs the vector B[bx*32 + tx][...].
        //   - In our shared memory mapping, this vector is stored at row 'tx' of Bs.
        #pragma unroll
        for (int k = 0; k < BLOCK_SIZE; ++k) {
            val += As[ty][k] * Bs[tx][k];
        }

        __syncthreads();
    }

    // Write result
    if (row < M && col < N) {
        C[row * N + col] = val;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // A is (M, K)
    // B is (N, K)
    // We compute A * B.T -> Output (M, N)

    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(0);

    TORCH_CHECK(B.size(1) == K, "Inner dimension K must match.");

    auto C = torch::empty({M, N}, A.options());

    dim3 block(BLOCK_SIZE, BLOCK_SIZE);
    dim3 grid((N + BLOCK_SIZE - 1) / BLOCK_SIZE, (M + BLOCK_SIZE - 1) / BLOCK_SIZE);

    matmul_transposed_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K
    );

    return C;
}
"""

matmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

