        # Ensure inputs are contiguous in memory for correct pointer arithmetic in CUDA
        if not A.is_contiguous():
            A = A.contiguous()
        if not B.is_contiguous():
            B = B.contiguous()

        return self.matmul_op.matmul_cuda(A, B)

