from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for MatMul (C = A^T * B^T)
# A: (K, M), B: (N, K), C: (M, N)
# This computes the matrix multiplication of the transposes of inputs A and B.
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int M, int N, int K) {
    // A shape: (K, M)
    // B shape: (N, K)
    // C shape: (M, N) output
    // Computes C[i, j] = sum_k (A^T)[i, k] * (B^T)[k, j] = sum_k A[k, i] * B[j, k]

    // Block Tile Size
    const int TS = 32;

    // Grid indices
    int bx = blockIdx.x; // Corresponds to N dimension (columns of C)
    int by = blockIdx.y; // Corresponds to M dimension (rows of C)

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global indices for C
    int row = by * TS + ty;
    int col = bx * TS + tx;

    // Shared memory buffers
    // As: Tile of A. We need to access columns of A (rows of A^T).
    // Bs: Tile of B. We need to access rows of B (columns of B^T).
    // Padding added to Bs to avoid bank conflicts during access.
    __shared__ float As[32][32];
    __shared__ float Bs[32][33];

    float val = 0.0f;

    // Loop over the K dimension (accumulation dimension)
    for (int k = 0; k < K; k += TS) {
        // Load tile from A into As
        // We need A[k..k+TS][row_start..row_start+TS]
        // Mapping: As[ty][tx] stores A[k + ty][by * TS + tx]
        // This memory access is coalesced (adjacent tx access adjacent columns of A)
        As[ty][tx] = A[(k + ty) * M + (by * TS + tx)];

        // Load tile from B into Bs
        // We need B[col_start..col_start+TS][k..k+TS]
        // Mapping: Bs[ty][tx] stores B[bx * TS + ty][k + tx]
        // This memory access is coalesced (adjacent tx access adjacent columns of B)
        Bs[ty][tx] = B[((bx * TS) + ty) * K + (k + tx)];

        __syncthreads();

        // Compute partial dot product for this tile
        #pragma unroll
        for (int l = 0; l < TS; ++l) {
            // We compute C[row][col] += A[k+l][row] * B[col][k+l]
            // From As: We need A[k+l][row]. 
            //    As[y][x] stores A[k+y][by*TS + x].
            //    We want k-offset = l, row-offset (from by*TS) = ty. 
            //    So we access As[l][ty].
            // From Bs: We need B[col][k+l]. 
            //    Bs[y][x] stores B[bx*TS + y][k+x].
            //    We want col-offset (from bx*TS) = tx, k-offset = l. 
            //    So we access Bs[tx][l].
            val += As[l][ty] * Bs[tx][l];
        }

        __syncthreads();
    }

    // Write result
    if (row < M && col < N) {
        C[row * N + col] = val;
    }
}

torch::Tensor custom_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Inputs are A (K, M) and B (N, K)
    // We want to compute A.T @ B.T -> (M, K) @ (K, N) -> (M, N)

    int K = A.size(0);
    int M = A.size(1);
    int N = B.size(0);

    auto C = torch::zeros({M, N}, A.options());

    const int TS = 32;
    dim3 threads(TS, TS);
    dim3 blocks((N + TS - 1) / TS, (M + TS - 1) / TS);

    matmul_kernel<<<blocks, threads>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), M, N, K);

    return C;
}
"""

