# CUDA source code for a high-performance tiled GEMM kernel
# This kernel calculates C = A.T @ B.T where A is (K, M) and B is (N, K).
# The resulting C is (M, N).
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    // Shared memory for tiles from A.T and B.T
    __shared__ float tileA[TILE_SIZE][TILE_SIZE];
    __shared__ float tileB[TILE_SIZE][TILE_SIZE];

    int ty = threadIdx.y;
    int tx = threadIdx.x;
    int tid = ty * TILE_SIZE + tx;

    // Block row and column
    int row_block = blockIdx.y * TILE_SIZE;
    int col_block = blockIdx.x * TILE_SIZE;

    float sum = 0.0f;

    // Iterate over the shared dimension K in tiles
    for (int t = 0; t < (K + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        int k_block = t * TILE_SIZE;

        // Load A[k][row] into tileA[row][k] for coalesced access
        // A is (K, M), so index is k * M + row
        int a_k = tid / TILE_SIZE;
        int a_row = tid % TILE_SIZE;
        if ((row_block + a_row) < M && (k_block + a_k) < K) {
            tileA[a_row][a_k] = A[(k_block + a_k) * M + (row_block + a_row)];
        } else {
            tileA[a_row][a_k] = 0.0f;
        }

        // Load B[col][k] into tileB[k][col] for coalesced access
        // B is (N, K), so index is col * K + k
        int b_col = tid / TILE_SIZE;
        int b_k = tid % TILE_SIZE;
        if ((col_block + b_col) < N && (k_block + b_k) < K) {
            tileB[b_k][b_col] = B[(col_block + b_col) * K + (k_block + b_k)];
        } else {
            tileB[b_k][b_col] = 0.0f;
        }

        __syncthreads();

        // Compute the dot product for the current tile
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            sum += tileA[ty][k] * tileB[k][tx];
        }
        __syncthreads();
    }

    // Write the final result to global memory
    int row = row_block + ty;
    int col = col_block + tx;
    if (row < M && col < N) {
