# This implementation uses an "Online LogSoftmax" approach (Welford-style).
# It computes the max and the sum of exponentials in a single pass over the data,
# followed by a second pass to write the output. This reduces global memory reads
# from 3 passes (Max, Sum, Write) to 2 passes (Reduce, Write), improving performance
# on memory-bound workloads like large Softmax/LogSoftmax.

log_softmax_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>
#include <limits>

// Struct to hold max and sum for reduction
template <typename T>
struct MaxSum {
    T max_val;
    T sum_val;
};

// Helper device function to combine two (max, sum) pairs
// Formula: 
// new_max = max(m1, m2)
// new_sum = s1 * exp(m1 - new_max) + s2 * exp(m2 - new_max)
__device__ __forceinline__ MaxSum<float> combine_max_sum(MaxSum<float> a, MaxSum<float> b) {
    float max_v = fmaxf(a.max_val, b.max_val);

    // Handle initialization case
    if (max_v == -INFINITY) return {-INFINITY, 0.0f};

    float diff_a = a.max_val - max_v;
    float diff_b = b.max_val - max_v;

    // Calculate combined sum relative to the new max
    float sum_v = a.sum_val * expf(diff_a) + b.sum_val * expf(diff_b);

    return {max_v, sum_v};
