#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void bn_apply_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int M, // Spatial size H * W
    float epsilon) {

    // Grid Mapping: BlockIdx.x = Channel (C), BlockIdx.y = Batch (N)
    int c = blockIdx.x;
    int n = blockIdx.y;

    // Load channel-specific parameters into registers once per block
    float mu = mean[c];
    float v = var[c];
    float gam = weight[c];
    float bet = bias[c];

    // Precompute inverse standard deviation
    float inv_std = rsqrtf(v + epsilon);

    // Calculate the global memory offset for this specific (n, c) feature map
    // Layout is (N, C, H, W), so stride for N is C*M, stride for C is M.
    long long offset = (long long)n * gridDim.x * M + (long long)c * M;

    const float* img_in = input + offset;
    float* img_out = output + offset;

    // Vectorized loop using float4 to process 4 elements per thread
    int vec_M = M / 4;
    const float4* in_ptr = reinterpret_cast<const float4*>(img_in);
    float4* out_ptr = reinterpret_cast<float4*>(img_out);

    for (int i = threadIdx.x; i < vec_M; i += blockDim.x) {
        float4 data = in_ptr[i];
        float4 res;

        // Fused Normalization + Scale + Shift
        res.x = (data.x - mu) * inv_std * gam + bet;
        res.y = (data.y - mu) * inv_std * gam + bet;
        res.z = (data.z - mu) * inv_std * gam + bet;
        res.w = (data.w - mu) * inv_std * gam + bet;

        out_ptr[i] = res;
    }

    // Handle remaining elements if M is not divisible by 4
    for (int i = vec_M * 4 + threadIdx.x; i < M; i += blockDim.x) {
         float val = img_in[i];
         img_out[i] = (val - mu) * inv_std * gam + bet;
    }
}

