torch::Tensor batch_norm_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    bool training,
    double momentum,
    double eps) {

    auto N = input.size(0);
    auto C = input.size(1);
    auto H = input.size(2);
    auto W = input.size(3);
    int M = H * W;

    auto output = torch::empty_like(input);

    at::Tensor current_mean, current_var;

    if (training) {
        // In training mode, compute batch statistics using ATen's optimized reduction
        // dimensions {0, 2, 3} correspond to (N, H, W)
