        // Note: For running_var, we use the biased batch variance as an approximation for speed 
        // given the large sample size (N*H*W), otherwise we would apply n/(n-1) correction.
        running_mean.mul_(1.0 - momentum).add_(current_mean.detach(), momentum);
        running_var.mul_(1.0 - momentum).add_(current_var.detach(), momentum);

