    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        // NCHW layout: idx = n * (C * H * W) + c * (H * W) + spatial_idx
        // Extract channel index c to fetch corresponding scale and shift
        int c = (idx / spatial_size) % C;

        // Fused multiply-add operation: y = x * scale + shift
        output[idx] = input[idx] * scale[c] + shift[c];
    }
}

torch::Tensor bn_inference_cuda(
    torch::Tensor input, 
    torch::Tensor mean, 
    torch::Tensor var, 
    torch::Tensor weight, 
    torch::Tensor bias, 
