#include <torch/extension.h>
#include <cuda_runtime.h>

// Helper for warp-level reduction
__inline__ __device__ float warpReduceSum(float val) {
    for (int offset = 32 / 2; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

// Helper for block-level reduction
__inline__ __device__ float blockReduceSum(float val) {
    static __shared__ float shared[32]; // Max 32 warps in a block
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceSum(val);

    // First thread of each warp writes to shared memory
    if (lane == 0) shared[wid] = val;
    __syncthreads();

    // First warp sums the partial sums
    val = (threadIdx.x < blockDim.x / 32) ? shared[threadIdx.x] : 0.0f;

    if (wid == 0) val = warpReduceSum(val);

    return val;
}

__global__ void group_norm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ output,
    int N, int C, int HW, int G, float epsilon)
{
    // Grid configuration:
    // x dimension = Group Index (0 to G-1)
    // y dimension = Batch Index (0 to N-1)
    int g = blockIdx.x;
    int n = blockIdx.y;

    int channels_per_group = C / G;
    int num_elements = channels_per_group * HW;

    // Calculate offsets into the linear memory
    // Input shape (N, C, H, W) is contiguous.
    // The data for a specific group 'g' in sample 'n' occupies a contiguous chunk
    // because channels [g*C/G, (g+1)*C/G) are adjacent in memory.

    size_t batch_offset = (size_t)n * C * HW;
    size_t group_offset = batch_offset + (size_t)g * channels_per_group * HW;

    const float* x_ptr = input + group_offset;
    float* y_ptr = output + group_offset;

    // --- Pass 1: Calculate Mean ---
    float sum = 0.0f;
    for (int i = threadIdx.x; i < num_elements; i += blockDim.x) {
        sum += x_ptr[i];
    }
    sum = blockReduceSum(sum);

    __shared__ float s_mean;
    if (threadIdx.x == 0) {
        s_mean = sum / num_elements;
    }
    __syncthreads();
    float mean = s_mean;

    // --- Pass 2: Calculate Variance ---
    float sum_sq = 0.0f;
    for (int i = threadIdx.x; i < num_elements; i += blockDim.x) {
        float diff = x_ptr[i] - mean;
        sum_sq += diff * diff;
    }
    sum_sq = blockReduceSum(sum_sq);

    __shared__ float s_inv_std;
    if (threadIdx.x == 0) {
        s_inv_std = rsqrtf(sum_sq / num_elements + epsilon);
    }
    __syncthreads();
    float inv_std = s_inv_std;

    // --- Pass 3: Normalize and Apply Affine Transform ---
    // We iterate channel-by-channel to apply the specific gamma and beta for each channel
    int c_start = g * channels_per_group;

    for (int c = 0; c < channels_per_group; ++c) {
