#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Kernel to compute mean and reciprocal standard deviation for each group
__global__ void compute_stats_kernel(
    const float* __restrict__ x, 
    float* __restrict__ mean, 
    float* __restrict__ rstd, 
    int G, int S, int HW, int M, float eps) {

    int ng = blockIdx.x; // index in [0, N*G - 1]
    int n = ng / G;
    int g = ng % G;

    double sum = 0.0;
    double sq_sum = 0.0;

    // Elements for each group (n, g) are contiguous in memory in NCHW format
    // because group g covers channels [g*S, (g+1)*S - 1].
    long long base_idx = (long long)n * (G * S * HW) + (long long)g * (S * HW);

    for (int i = threadIdx.x; i < M; i += blockDim.x) {
        double val = (double)x[base_idx + i];
        sum += val;
        sq_sum += val * val;
    }

    // Block-level reduction using shared memory
    __shared__ double s_sum[256];
    __shared__ double s_sq_sum[256];
    int tid = threadIdx.x;
    s_sum[tid] = sum;
    s_sq_sum[tid] = sq_sum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            s_sum[tid] += s_sum[tid + stride];
            s_sq_sum[tid] += s_sq_sum[tid + stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        double m = s_sum[0] / (double)M;
        double v = (s_sq_sum[0] / (double)M) - (m * m);
        if (v < 0.0) v = 0.0;
        mean[ng] = (float)m;
        rstd[ng] = (float)(1.0 / sqrt(v + (double)eps));
    }
}

// Kernel to apply the normalization, scale (gamma), and shift (beta)
__global__ void apply_gn_kernel(
    const float* __restrict__ x,
    const float* __restrict__ mean,
    const float* __restrict__ rstd,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int G, int S, int HW) {

    int hw = blockIdx.x * blockDim.x + threadIdx.x;
    if (hw >= HW) return;

    int c = blockIdx.y;
    int n = blockIdx.z;
    int g = c / S;
    int ng = n * G + g;

    float m = mean[ng];
    float rs = rstd[ng];
    float w = weight[c];
    float b = bias[c];

    long long offset = (long long)n * (G * S * HW) + (long long)c * HW + (long long)hw;
    out[offset] = (x[offset] - m) * rs * w + b;
}

