    // The reduction happens along the Channel (C) dimension.
    // We treat the spatial dimension as a vector of float4, effectively S/4 elements.

    int S_vec = S / 4; // Stride of C in float4 terms
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_vecs = N * S_vec;

    if (idx < total_vecs) {
