        int n = idx / S_vec;
        int hw_vec = idx % S_vec;

        // Calculate the base offset in the flattened float4 array.
        // The memory layout is N-C-S (contiguous). 
        // In float4 view, the stride between channels is S_vec.
        // The start of the column for (n, hw_vec) is at:
        int base_offset = n * C * S_vec + hw_vec;

