import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# CUDA kernel for Layer Normalization
# Optimized for FP32 precision with large normalized shapes.
# Uses a two-pass approach within a single kernel:
# 1. First pass computes sum and squared sum for mean and variance calculation.
# 2. Second pass performs the actual normalization using precomputed mean and variance.
# Uses double precision for internal accumulation to ensure stability with large data sizes.
layer_norm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__inline__ __device__ double blockReduceSum(double val) {
    __shared__ double shared[32];
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);

    if (lane == 0) shared[wid] = val;
    __syncthreads();

    int num_warps = blockDim.x / 32;
    val = (wid == 0 && lane < num_warps) ? shared[lane] : 0.0;
    if (wid == 0) {
        for (int offset = 16; offset > 0; offset /= 2)
            val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}

__global__ void layer_norm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N,
    float eps) {

    int batch_idx = blockIdx.x;
    const float* x_row = x + (size_t)batch_idx * N;
    float* out_row = out + (size_t)batch_idx * N;

    double sum = 0.0;
    double sq_sum = 0.0;

    // First pass: compute mean and squared sum
    for (int i = threadIdx.x; i < N; i += blockDim.x) {
        double val = (double)x_row[i];
        sum += val;
        sq_sum += val * val;
    }

    sum = blockReduceSum(sum);
    sq_sum = blockReduceSum(sq_sum);

    __shared__ double m_shared, inv_std_shared;
    if (threadIdx.x == 0) {
        double mean = sum / (double)N;
        double var = (sq_sum / (double)N) - (mean * mean);
        if (var < 0.0) var = 0.0;
        m_shared = mean;
        inv_std_shared = 1.0 / sqrt(var + (double)eps);
    }
    __syncthreads();

    double m = m_shared;
    double inv_std = inv_std_shared;

    // Second pass: normalize and apply scale/bias
    for (int i = threadIdx.x; i < N; i += blockDim.x) {
        float gamma = (weight != nullptr) ? weight[i] : 1.0f;
        float beta = (bias != nullptr) ? bias[i] : 0.0f;
        out_row[i] = (float)(((double)x_row[i] - m) * inv_std * (double)gamma + (double)beta);
    }
}

