# 2. A general-purpose reduction for other dimensions that maintains memory coalescing for large inner dimensions.
max_reduction_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cfloat>

// Warp-level reduction for finding maximum values efficiently
__inline__ __device__ float warpReduceMax(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
    return val;
}

// Kernel optimized for reduction over the last dimension (inner_size == 1)
__global__ void max_reduction_last_dim_kernel(const float* __restrict__ input, float* __restrict__ output, int outer_size, int reduce_size) {
    int row = blockIdx.x; // Each block handles one row (one output element)
    if (row >= outer_size) return;

    float max_val = -FLT_MAX;
    // Each thread processes multiple elements in the row
    for (int i = threadIdx.x; i < reduce_size; i += blockDim.x) {
        max_val = fmaxf(max_val, input[row * reduce_size + i]);
    }

    // Collaborative reduction within the block using shared memory and warps
    __shared__ float shared_max[32]; // Max 32 warps in a block of 1024 threads
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    max_val = warpReduceMax(max_val);

    if (lane == 0) shared_max[wid] = max_val;
    __syncthreads();

    // Final reduction of warp results by the first warp
    if (wid == 0) {
        max_val = (threadIdx.x < (blockDim.x / 32)) ? shared_max[lane] : -FLT_MAX;
        max_val = warpReduceMax(max_val);
        if (lane == 0) output[row] = max_val;
    }
}

// General kernel for reduction over arbitrary dimensions
// Efficient when the inner_dimension is large enough to ensure coalesced memory access
__global__ void max_reduction_general_kernel(const float* __restrict__ input, float* __restrict__ output, int outer_size, int reduce_size, int inner_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int num_outputs = outer_size * inner_size;

    if (idx < num_outputs) {
        int outer_idx = idx / inner_size;
        int inner_idx = idx % inner_size;

        // Start pointer for this output element's reduction slice
        int base_offset = outer_idx * reduce_size * inner_size + inner_idx;
        float max_val = -FLT_MAX;

        // Iterate through the reduction dimension
        for (int k = 0; k < reduce_size; ++k) {
            float val = input[base_offset + k * inner_size];
            max_val = fmaxf(max_val, val);
        }
        output[idx] = max_val;
    }
