__global__ void argmax_kernel(const float* __restrict__ input, int64_t* __restrict__ output, int64_t pre_dim, int64_t mid_dim, int64_t post_dim) {
    // Each block handles one reduction along the specified dimension
    int64_t idx = blockIdx.x;
    if (idx >= pre_dim * post_dim) return;

    int64_t i = idx / post_dim;
    int64_t j = idx % post_dim;

    float max_val = -INFINITY;
    int64_t max_idx = 0;

    // Base pointer for this specific reduction
    const float* base_ptr = input + (i * mid_dim * post_dim + j);

    // Grid-stride loop within the block to find thread-local maximum
    for (int64_t k = threadIdx.x; k < mid_dim; k += blockDim.x) {
        float val = base_ptr[k * post_dim];
        if (k == threadIdx.x || val > max_val) {
            max_val = val;
            max_idx = k;
        }
    }

    // Shared memory for block-level reduction
    extern __shared__ char shared_mem[];
    float* shared_vals = (float*)shared_mem;
    int64_t* shared_idxs = (int64_t*)(shared_mem + blockDim.x * sizeof(float));

    shared_vals[threadIdx.x] = max_val;
    shared_idxs[threadIdx.x] = max_idx;
    __syncthreads();

    // Parallel reduction tree
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            if (shared_vals[threadIdx.x + s] > shared_vals[threadIdx.x]) {
                shared_vals[threadIdx.x] = shared_vals[threadIdx.x + s];
                shared_idxs[threadIdx.x] = shared_idxs[threadIdx.x + s];
