                // If values are equal, pick the smaller index to match PyTorch behavior
                if (shared_idxs[threadIdx.x + s] < shared_idxs[threadIdx.x]) {
                    shared_idxs[threadIdx.x] = shared_idxs[threadIdx.x + s];
