    if (row >= outer_size) return;

    float min_val = 3.402823466e+38F; // FLT_MAX
    for (long long i = threadIdx.x; i < reduce_size; i += blockDim.x) {
        min_val = fminf(min_val, input[row * reduce_size + i]);
    }

    // Shared memory for warp-level results
    __shared__ float shared_min[32]; // Max 1024 threads (32 warps)
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    min_val = warpReduceMin(min_val);

    if (lane == 0) shared_min[wid] = min_val;
    __syncthreads();

    // Final reduction by the first warp
    min_val = (threadIdx.x < (blockDim.x / 32)) ? shared_min[lane] : 3.402823466e+38F;
    if (wid == 0) min_val = warpReduceMin(min_val);

    if (threadIdx.x == 0) output[row] = min_val;
}

// General kernel for reduction over any dimension
__global__ void min_reduce_kernel(const float* __restrict__ input, float* __restrict__ output,
                                  long long outer_size, long long reduce_size, long long inner_size) {
    long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long total_output_elements = outer_size * inner_size;

    if (idx < total_output_elements) {
        long long i = idx / inner_size; // outer index
        long long k = idx % inner_size; // inner index

        // Pointer to the first element in the reduction dimension for this output element
        const float* input_ptr = input + (i * reduce_size * inner_size + k);
        float min_val = 3.402823466e+38F;

        for (long long j = 0; j < reduce_size; ++j) {
            min_val = fminf(min_val, *input_ptr);
            input_ptr += inner_size;
        }
        output[idx] = min_val;
    }
}

torch::Tensor min_reduce_cuda(torch::Tensor x, int64_t dim) {
    if (dim < 0) dim += x.dim();
    auto shape = x.sizes();

    long long outer_size = 1;
    for (int i = 0; i < dim; ++i) outer_size *= shape[i];
    long long reduce_size = shape[dim];
    long long inner_size = 1;
    for (int i = dim + 1; i < x.dim(); ++i) inner_size *= shape[i];

    std::vector<int64_t> output_shape;
    for (int i = 0; i < x.dim(); ++i) {
        if (i != dim) output_shape.push_back(shape[i]);
    }
    auto out = torch::empty(output_shape, x.options());

    if (inner_size == 1) {
        // Efficient row-wise reduction for last dimension
        const int threads = 256;
        const long long blocks = outer_size;
        min_reduce_last_dim_kernel<<<blocks, threads>>>(
            x.data_ptr<float>(), out.data_ptr<float>(), outer_size, reduce_size);
    } else {
        // Coalesced memory access reduction for other dimensions
        const int threads = 256;
        const long long total_out = outer_size * inner_size;
        const long long blocks = (total_out + threads - 1) / threads;
        min_reduce_kernel<<<blocks, threads>>>(
            x.data_ptr<float>(), out.data_ptr<float>(), outer_size, reduce_size, inner_size);
    }
    return out;
}
