// Uses tiling for output channels to improve memory reuse of the input tensor.
// Constraints: FP32, Stride=1, Padding=0

template <int OC_BLOCK>
__global__ void conv_transpose2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_h,
    int in_w,
    int k_h,
    int k_w,
    int out_h,
    int out_w) {

