    int ow = blockIdx.x * blockDim.x + threadIdx.x;
    int oh = blockIdx.y * blockDim.y + threadIdx.y;

    // The Z grid dimension flattens Batch and Output Channel Chunks
    int chunks_per_batch = (out_channels + OC_BLOCK - 1) / OC_BLOCK;
    int b = blockIdx.z / chunks_per_batch;
    int oc_chunk = blockIdx.z % chunks_per_batch;
    int oc_start = oc_chunk * OC_BLOCK;

    // Accumulators for a block of output channels
    float sums[OC_BLOCK];
    #pragma unroll
    for (int i = 0; i < OC_BLOCK; ++i) {
        sums[i] = 0.0f;
    }

    if (ow < out_w && oh < out_h && b < batch_size) {

        // Iterate over Input Channels
        for (int ic = 0; ic < in_channels; ++ic) {

            // Iterate over Kernel spatial dimensions
            // Relationship: oh = ih + kh  =>  ih = oh - kh
            for (int kh = 0; kh < k_h; ++kh) {
                int ih = oh - kh;

                // Bounds check Input Height
                if (ih >= 0 && ih < in_h) {

