                            int input_idx = ((b * in_channels + ic) * in_h + ih) * in_w + iw;
                            float val = input[input_idx];

                            // Accumulate for each output channel in the block
                            #pragma unroll
                            for (int i = 0; i < OC_BLOCK; ++i) {
