__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_d, int in_h, int in_w,
    int out_d, int out_h, int out_w,
    int k_d, int k_h, int k_w,
    int s_d, int s_h, int s_w,
    int p_d, int p_h, int p_w,
    int op_d, int op_h, int op_w) {

    // Calculate global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * out_d * out_h * out_w;

    if (idx >= total_elements) return;

    // Decode linear index into (n, c_out, d_out, h_out, w_out)
    // Layout: N, C_out, D_out, H_out, W_out
    int w_out_idx = idx % out_w;
    int rem = idx / out_w;
    int h_out_idx = rem % out_h;
    rem = rem / out_h;
    int d_out_idx = rem % out_d;
    rem = rem / out_d;
    int c_out_idx = rem % out_channels;
    int b_idx = rem / out_channels;

    // Initialize with bias if present
    float val = 0.0f;
    if (bias != nullptr) {
        val = bias[c_out_idx];
    }

    // Direct Transposed Convolution (Inverse Mapping / Gather approach)
    // For each output pixel, we gather contributions from valid input pixels and weights.
    // Mapping: out_pos = in_pos * stride - padding + kernel_pos
    // Inverse: in_pos = (out_pos + padding - kernel_pos) / stride

    // Iterate over kernel dimensions
    for (int kd = 0; kd < k_d; ++kd) {
        int d_in_numerator = d_out_idx + p_d - kd;
        if (d_in_numerator % s_d != 0) continue;
        int d_in_idx = d_in_numerator / s_d;
        if (d_in_idx < 0 || d_in_idx >= in_d) continue;

        for (int kh = 0; kh < k_h; ++kh) {
            int h_in_numerator = h_out_idx + p_h - kh;
            if (h_in_numerator % s_h != 0) continue;
            int h_in_idx = h_in_numerator / s_h;
            if (h_in_idx < 0 || h_in_idx >= in_h) continue;

            for (int kw = 0; kw < k_w; ++kw) {
                int w_in_numerator = w_out_idx + p_w - kw;
                if (w_in_numerator % s_w != 0) continue;
                int w_in_idx = w_in_numerator / s_w;
                if (w_in_idx < 0 || w_in_idx >= in_w) continue;

                // Accumulate over input channels
                for (int cin = 0; cin < in_channels; ++cin) {
                    // Input tensor shape: [N, Cin, Din, Hin, Win]
                    long long input_offset = 
                        ((long long)b_idx * in_channels + cin) * in_d * in_h * in_w +
                        (long long)d_in_idx * in_h * in_w +
                        h_in_idx * in_w +
                        w_in_idx;

                    // Weight tensor shape for ConvTranspose3d: [Cin, Cout, Kd, Kh, Kw] (assuming groups=1)
                    long long weight_offset = 
                        ((long long)cin * out_channels + c_out_idx) * k_d * k_h * k_w +
                        (long long)kd * k_h * k_w +
                        kh * k_w +
                        kw;

                    val += input[input_offset] * weight[weight_offset];
                }
            }
        }
    }

    output[idx] = val;
