    long long total_elements = (long long)batch_size * out_channels * out_depth * out_height * out_width;
    long long idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= total_elements) return;

    // Decode linear index into (n, c_out, d_out, h_out, w_out)
    int w_out_idx = idx % out_width;
    long long tmp = idx / out_width;
    int h_out_idx = tmp % out_height;
    tmp /= out_height;
    int d_out_idx = tmp % out_depth;
    tmp /= out_depth;
    int c_out_idx = tmp % out_channels;
    int n_idx = tmp; 

    float sum = 0.0f;
    if (bias != nullptr) {
        sum = bias[c_out_idx];
    }

    // Group logic
    int out_channels_per_group = out_channels / groups;
    int in_channels_per_group = in_channels / groups;
    int group_id = c_out_idx / out_channels_per_group;
    int c_out_in_group = c_out_idx % out_channels_per_group;
    int in_c_start = group_id * in_channels_per_group;

    // Iterate over input channels in the group
    for (int ic_g = 0; ic_g < in_channels_per_group; ++ic_g) {
        int ic = in_c_start + ic_g;

        // Iterate over kernel spatial dimensions
        // For transposed conv, we are essentially gathering contributions from the input.
        // Relationship: out_idx = in_idx * stride - padding + kernel_idx
        // Therefore: in_idx * stride = out_idx + padding - kernel_idx

        #pragma unroll
        for (int kd = 0; kd < k_d; ++kd) {
            int val_d = d_out_idx + padding - kd;
            // Check if this kernel position aligns with the strided input
            if (val_d % stride != 0) continue;
            int d_in = val_d / stride;
            // Check boundary
            if (d_in < 0 || d_in >= in_depth) continue;

            #pragma unroll
            for (int kh = 0; kh < k_h; ++kh) {
                int val_h = h_out_idx + padding - kh;
                if (val_h % stride != 0) continue;
                int h_in = val_h / stride;
                if (h_in < 0 || h_in >= in_height) continue;

                #pragma unroll
                for (int kw = 0; kw < k_w; ++kw) {
                    int val_w = w_out_idx + padding - kw;
                    if (val_w % stride != 0) continue;
                    int w_in = val_w / stride;
                    if (w_in < 0 || w_in >= in_width) continue;

                    // Compute memory indices
                    long long in_idx = (long long)n_idx * in_channels * in_depth * in_height * in_width +
                                       (long long)ic * in_depth * in_height * in_width +
                                       (long long)d_in * in_height * in_width +
                                       (long long)h_in * in_width +
                                       w_in;

                    // Weight shape for ConvTranspose3d: (in_channels, out_channels/groups, kD, kH, kW)
                    int w_idx = ic * out_channels_per_group * k_d * k_h * k_w +
                                c_out_in_group * k_d * k_h * k_w +
                                kd * k_h * k_w +
                                kh * k_w +
                                kw;

                    sum += input[in_idx] * weight[w_idx];
                }
            }
        }
    }

    output[idx] = sum;
}

