#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA Kernel: Tiled 2D Convolution
// Uses Shared Memory to cache input tiles to reduce global memory bandwidth usage.
// Optimized for FP32.
// Supports stride, padding, and groups.
// Assumes dilation=1 for shared memory efficiency.
__global__ void conv2d_tiled_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int kernel_h,
    int kernel_w,
    int stride,
    int padding,
    int groups) {

    // Dynamic shared memory configuration
    extern __shared__ float s_mem[];

    // Thread and Block indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int bz = blockIdx.z; // Maps to (Batch * Out_Channels)

    // Calculate specific batch and output channel for this block
    int out_ch = bz % out_channels;
    int batch = bz / out_channels;

    // Grouping logic
    int channels_per_group = out_channels / groups;
    int group_id = out_ch / channels_per_group;
    int in_channels_per_group = in_channels / groups;
    int start_in_ch = group_id * in_channels_per_group;

    // Global Output Coordinates
    int out_x = bx * blockDim.x + tx;
    int out_y = by * blockDim.y + ty;

    // Dimensions of the input tile required in Shared Memory
    // To compute a 16x16 output block, we need (16-1)*stride + kernel_size inputs
    int tile_w = (blockDim.x - 1) * stride + kernel_w;
    int tile_h = (blockDim.y - 1) * stride + kernel_h;
    int tile_size = tile_w * tile_h;

    float val = 0.0f;

    // Iterate over input channels belonging to the group
    for (int ic_rel = 0; ic_rel < in_channels_per_group; ++ic_rel) {
        int ic = start_in_ch + ic_rel;

        // Collaborative loading of the input tile into shared memory
        // Threads loop to cover the entire shared memory tile if it's larger than blockDim
        for (int i = ty * blockDim.x + tx; i < tile_size; i += blockDim.x * blockDim.y) {
            int t_y = i / tile_w;
            int t_x = i % tile_w;

            // Global input anchor for this block (top-left)
            int anchor_y = by * blockDim.y * stride - padding;
            int anchor_x = bx * blockDim.x * stride - padding;

            int in_r = anchor_y + t_y;
            int in_c = anchor_x + t_x;

