        if (out_x < out_w && out_y < out_h) {
            // Pointer to the specific 2D filter weights
            // Weight tensor shape: [Out, In/Groups, kH, kW]
            const float* w_ptr = weight + (out_ch * in_channels_per_group + ic_rel) * kernel_h * kernel_w;

            for (int ky = 0; ky < kernel_h; ++ky) {
                for (int kx = 0; kx < kernel_w; ++kx) {
                    // Calculate index in shared memory
                    // Input corresponding to output(ty, tx) starts at offset (ty*stride, tx*stride)
                    int smem_idx = (ty * stride + ky) * tile_w + (tx * stride + kx);
                    val += s_mem[smem_idx] * w_ptr[ky * kernel_w + kx];
                }
            }
        }

        // Synchronize before loading the next channel
        __syncthreads();
    }

    // Apply Bias and Write Output
    if (out_x < out_w && out_y < out_h) {
        if (bias != nullptr) {
            val += bias[out_ch];
        }
        int out_idx = (batch * out_channels + out_ch) * out_h * out_w + out_y * out_w + out_x;
        output[out_idx] = val;
    }
