    int boc_idx = blockIdx.y * blockDim.y + threadIdx.y;

    int out_hw = out_h * out_w;
    int batch_oc = batch_size * out_channels;

    if (hw_idx < out_hw && boc_idx < batch_oc) {
        int w_out = hw_idx % out_w;
        int h_out = hw_idx / out_w;
        int oc = boc_idx % out_channels;
        int b = boc_idx / out_channels;

