import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA source code for the optimized transposed convolution
# Optimized for the specific architecture:
# - Kernel size: 3x7
# - In/Out channels: 64
# - Stride: 1
conv_transpose_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// Hardcoded optimization constants matching the model architecture
#define K_H 3
#define K_W 7
#define BLOCK_W 16
#define BLOCK_H 16
#define TILE_H (BLOCK_H + K_H - 1) // 16 + 2 = 18
#define TILE_W (BLOCK_W + K_W - 1) // 16 + 6 = 22
#define IN_CHANNELS 64

__global__ void conv_transpose2d_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    float* __restrict__ y,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_h,
    int in_w,
    int out_h,
    int out_w) {

    // Shared memory for weights and input tile
    // Pre-load weights for the specific output channel handled by the block
    __shared__ float sm_w[IN_CHANNELS][K_H][K_W];
    // Input tile buffer
    __shared__ float sm_x[TILE_H][TILE_W];

    // Grid indices
    // Z dimension maps to (Batch, Out_Channel) pairs
    int bz = blockIdx.z;
    int n = bz / out_channels;
    int k = bz % out_channels;

    // Output spatial base coordinates for this block
    int out_x_base = blockIdx.x * BLOCK_W;
    int out_y_base = blockIdx.y * BLOCK_H;

    int tid = threadIdx.y * blockDim.x + threadIdx.x;
    int block_size = blockDim.x * blockDim.y;

    // 1. Load weights for output channel 'k' into shared memory
    // Weight shape: (in_channels, out_channels, K_H, K_W)
    // We need slice [:, k, :, :]
    int num_weights = in_channels * K_H * K_W;

    // Coalescing is not perfect here due to stride but it's done once per block
    for (int i = tid; i < num_weights; i += block_size) {
        int c = i / (K_H * K_W);
        int rem = i % (K_H * K_W);
        int p = rem / K_W;
        int q = rem % K_W;

        // Calculate global weight index
        // stride_in = out_channels * K_H * K_W
        // stride_out = K_H * K_W
        int w_idx = c * (out_channels * K_H * K_W) + k * (K_H * K_W) + p * K_W + q;
        sm_w[c][p][q] = w[w_idx];
    }

    __syncthreads();

    float acc = 0.0f;

    // 2. Iterate over input channels
    for (int c = 0; c < in_channels; ++c) {
        // Load input tile for channel 'c'
        // We need input pixels that contribute to output pixels [out_y_base, out_y_base+15]
        // Since Y[h] += X[h-p] * W[p], to compute Y[h], we need X[h-p].
        // Range of p is [0, 2].
        // Min input y needed: out_y_base - 2
        // Max input y needed: (out_y_base + 15) - 0
        // So we load tile of size 18x22

        int tile_pixels = TILE_H * TILE_W;
        for (int i = tid; i < tile_pixels; i += block_size) {
            int ty = i / TILE_W;
            int tx = i % TILE_W;

            // Map tile coordinates to global input coordinates
            int y_in = out_y_base - (K_H - 1) + ty;
            int x_in = out_x_base - (K_W - 1) + tx;

            float val = 0.0f;
            if (y_in >= 0 && y_in < in_h && x_in >= 0 && x_in < in_w) {
                 // x shape: (N, C, H, W)
                 int x_idx = ((n * in_channels + c) * in_h + y_in) * in_w + x_in;
                 val = x[x_idx];
            }
            sm_x[ty][tx] = val;
        }

        __syncthreads();

        // Convolve
        // Only threads within valid output dimensions compute
        int ty = threadIdx.y;
        int tx = threadIdx.x;

        if (out_y_base + ty < out_h && out_x_base + tx < out_w) {
            // Convolution sum: Y[h, w] += sum(X[h-p, w-q] * W[c, p, q])
            // In tile coords:
            // current pixel is at sm_x[ty + (K_H-1)][tx + (K_W-1)] (center of kernel influence)
            // shifted by p, q: sm_x[ty + (K_H-1) - p][tx + (K_W-1) - q]

            #pragma unroll
            for (int p = 0; p < K_H; ++p) {
                #pragma unroll
                for (int q = 0; q < K_W; ++q) {
                    acc += sm_x[ty + (K_H - 1) - p][tx + (K_W - 1) - q] * sm_w[c][p][q];
                }
            }
        }
        __syncthreads();
    }

    // 3. Write result
    int ty = threadIdx.y;
    int tx = threadIdx.x;
    int gy = out_y_base + ty;
    int gx = out_x_base + tx;

    if (gy < out_h && gx < out_w) {
        int y_idx = ((n * out_channels + k) * out_h + gy) * out_w + gx;
        y[y_idx] = acc;
    }
}

torch::Tensor conv_transpose2d_cuda_forward(torch::Tensor input, torch::Tensor weight) {
    int n = input.size(0);
    int in_c = input.size(1);
    int h = input.size(2);
    int w = input.size(3);

    // Weight shape: (in, out, kh, kw)
    int out_c = weight.size(1);
    int kh = weight.size(2);
    int kw = weight.size(3);

    int out_h = h + kh - 1;
    int out_w = w + kw - 1;

    auto output = torch::zeros({n, out_c, out_h, out_w}, input.options());

    dim3 block(BLOCK_W, BLOCK_H);
    dim3 grid((out_w + BLOCK_W - 1) / BLOCK_W, (out_h + BLOCK_H - 1) / BLOCK_H, n * out_c);

    conv_transpose2d_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        n, in_c, out_c, h, w, out_h, out_w
    );

    return output;
}
"""

