# CUDA kernel source code for optimized 1D Convolution
# This kernel uses shared memory tiling to reduce global memory accesses for the input tensor.
# It assumes a contiguous data layout (Batch, Channels, Length).
conv1d_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 256

__global__ void conv1d_cuda_kernel(
    const float* __restrict__ x, 
    const float* __restrict__ weight, 
    float* __restrict__ y, 
    int batch_size, 
    int in_channels, 
    int out_channels, 
    int length_in, 
    int length_out, 
    int kernel_size,
    int stride,
    int padding,
    int dilation
) {
    // Dynamic shared memory to cache a tile of input X
    extern __shared__ float s_x[];

    int bx = blockIdx.x; // Block index corresponding to output length dimension
    int by = blockIdx.y; // Block index corresponding to output channel
    int bz = blockIdx.z; // Block index corresponding to batch

    int tx = threadIdx.x;

    // Global output position for this thread
    int l_out = bx * TILE_SIZE + tx;
    int c_out = by;
    int n = bz;

    // Mask for valid output threads
    bool active = (l_out < length_out);

    float val = 0.0f;

    // Calculate Global Memory Offsets
    // x: (N, C_in, L_in)
    // weight: (C_out, C_in, K)
    int x_batch_offset = n * in_channels * length_in;
    int w_out_offset = c_out * in_channels * kernel_size;

    // Determine the range of input data required by this block.
    // Base input index corresponding to the start of the output tile.
    int base_in_idx = bx * TILE_SIZE * stride - padding;

    // Total number of input elements needed in shared memory for this tile
    int footprint = (TILE_SIZE - 1) * stride + (kernel_size - 1) * dilation + 1;

    // Loop over input channels
    for (int c_in = 0; c_in < in_channels; ++c_in) {
        // 1. Load Input Tile into Shared Memory
        int x_channel_offset = x_batch_offset + c_in * length_in;

        // Cooperative loading: all threads load the required footprint
        for (int i = tx; i < footprint; i += TILE_SIZE) {
            int global_in_idx = base_in_idx + i;
            if (global_in_idx >= 0 && global_in_idx < length_in) {
                s_x[i] = x[x_channel_offset + global_in_idx];
            } else {
                s_x[i] = 0.0f; // Handle zero padding
            }
        }

        // Ensure all data is loaded before computation
        __syncthreads();

        // 2. Compute convolution for this channel
        if (active) {
            int w_channel_offset = w_out_offset + c_in * kernel_size;

            #pragma unroll
            for (int k = 0; k < kernel_size; ++k) {
                // Calculate index in shared memory
                int s_idx = tx * stride + k * dilation;
                val += s_x[s_idx] * weight[w_channel_offset + k];
            }
        }

        // Ensure computation is done before reloading shared memory
        __syncthreads();
    }

    // Write result to global memory
    if (active) {
        int y_idx = n * (out_channels * length_out) + c_out * length_out + l_out;
        y[y_idx] = val; 
    }
}

torch::Tensor conv1d_cuda_forward(
    torch::Tensor x, 
    torch::Tensor weight, 
    int stride, 
    int padding, 
    int dilation
) {
    int batch_size = x.size(0);
    int in_channels = x.size(1);
    int length_in = x.size(2);

    int out_channels = weight.size(0);
    int kernel_size = weight.size(2);

    // Calculate output length
    int length_out = (length_in + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    // Allocate output tensor
    auto y = torch::zeros({batch_size, out_channels, length_out}, x.options());

    if (length_out <= 0) return y;

    const int block_size = TILE_SIZE;
    dim3 grid((length_out + block_size - 1) / block_size, out_channels, batch_size);

    // Calculate shared memory size required
    int footprint = (block_size - 1) * stride + (kernel_size - 1) * dilation + 1;
    size_t shared_mem_size = footprint * sizeof(float);

    conv1d_cuda_kernel<<<grid, block_size, shared_mem_size>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        y.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        length_in,
        length_out,
        kernel_size,
        stride,
        padding,
        dilation
    );

    return y;
}
