    // Precompute strides for weight tensor: (in_channels, out_channels/groups, kD, kH, kW)
    int w_stride_cin = out_group_size * k_d * k_h * k_w;
    int w_stride_cout = k_d * k_h * k_w;
    int w_stride_kd = k_h * k_w;
    int w_stride_kh = k_w;

    // Precompute strides for input tensor: (N, in_channels, D, H, W)
    int in_stride_n = in_channels * in_d * in_h * in_w;
    int in_stride_c = in_d * in_h * in_w;
    int in_stride_d = in_h * in_w;
    int in_stride_h = in_w;

    // Gather Logic: 
    // The relationship for Transposed Conv (gradient of Conv) is:
    // output_pos = input_pos * stride + kernel_offset * dilation - padding
    // We iterate over kernel_offsets to find the contributing input_pos:
    // input_pos * stride = output_pos + padding - kernel_offset * dilation

    for (int kd = 0; kd < k_d; ++kd) {
        int val_d = od + pad_d - kd * dilation_d;
        if (val_d % stride_d != 0) continue;
        int id = val_d / stride_d;
        if (id < 0 || id >= in_d) continue;

        for (int kh = 0; kh < k_h; ++kh) {
            int val_h = oh + pad_h - kh * dilation_h;
            if (val_h % stride_h != 0) continue;
            int ih = val_h / stride_h;
            if (ih < 0 || ih >= in_h) continue;

            for (int kw = 0; kw < k_w; ++kw) {
                int val_w = ow + pad_w - kw * dilation_w;
                if (val_w % stride_w != 0) continue;
                int iw = val_w / stride_w;
                if (iw < 0 || iw >= in_w) continue;

                // Calculate base memory offsets
                int in_offset_base = n * in_stride_n + id * in_stride_d + ih * in_stride_h + iw;
                int w_offset_base = c_out_local * w_stride_cout + kd * w_stride_kd + kh * w_stride_kh + kw;

                // Accumulate over input channels in the group
                for (int cin = c_in_start; cin < c_in_end; ++cin) {
                    float val = input[in_offset_base + cin * in_stride_c];
                    float w = weight[cin * w_stride_cin + w_offset_base];
                    acc += val * w;
                }
            }
        }
    }

    if (bias != nullptr) {
        acc += bias[c_out];
    }

    output[idx] = acc;
}

