    int64_t out_h = (H - 1) * stride[1] - 2 * padding[1] + dilation_h * (KH - 1) + output_padding[1] + 1;
    int64_t out_w = (W - 1) * stride[2] - 2 * padding[2] + dilation_w * (KW - 1) + output_padding[2] + 1;

