    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= n_elements) return;

    // Decode output index (N, Cout, Dout, Hout, Wout)
    int temp = idx;
    int w_out_idx = temp % out_w; temp /= out_w;
    int h_out_idx = temp % out_h; temp /= out_h;
    int d_out_idx = temp % out_d; temp /= out_d;
    int c_out_idx = temp % out_channels; temp /= out_channels;
    int b_idx = temp;

    float sum = 0.0f;
    if (bias != nullptr) {
        sum = bias[c_out_idx];
    }

    // Group logic
    int out_per_group = out_channels / groups;
    int group_idx = c_out_idx / out_per_group;
    int c_out_local = c_out_idx % out_per_group;

    int in_per_group = in_channels / groups;
    int c_in_start = group_idx * in_per_group;

    // Precompute strides for efficiency
    int in_hw = in_h * in_w;
    int in_dhw = in_d * in_hw;
    int in_cdhw = in_channels * in_dhw;

