    int k_dhw = k_d * k_hw;
    int w_out_group_size = out_per_group * k_dhw;

    // Iterate over input channels in the group
    for (int c_i = 0; c_i < in_per_group; ++c_i) {
        int in_channel = c_in_start + c_i;

        // Iterate over kernel spatial dimensions
        for (int kz = 0; kz < k_d; ++kz) {
            // Calculate corresponding input depth index
            // d_out = d_in * stride - padding + kz * dilation
            // => d_in * stride = d_out + padding - kz * dilation
            int d_shifted = d_out_idx + pad_d - kz * dil_d;

            // Check validity: must be non-negative and divisible by stride
            if (d_shifted < 0 || d_shifted % stride_d != 0) continue;
            int d_in_idx = d_shifted / stride_d;

            // Check input bounds
            if (d_in_idx < 0 || d_in_idx >= in_d) continue;

            for (int ky = 0; ky < k_h; ++ky) {
                int h_shifted = h_out_idx + pad_h - ky * dil_h;
                if (h_shifted < 0 || h_shifted % stride_h != 0) continue;
                int h_in_idx = h_shifted / stride_h;
                if (h_in_idx < 0 || h_in_idx >= in_h) continue;

                for (int kx = 0; kx < k_w; ++kx) {
                    int w_shifted = w_out_idx + pad_w - kx * dil_w;
                    if (w_shifted < 0 || w_shifted % stride_w != 0) continue;
                    int w_in_idx = w_shifted / stride_w;
