    int temp_idx = idx;
    int ow = temp_idx % out_width;
    temp_idx /= out_width;
    int oh = temp_idx % out_height;
    temp_idx /= out_height;
    int od = temp_idx % out_depth;
    temp_idx /= out_depth;
    int co = temp_idx % out_channels;
    int n = temp_idx / out_channels;

