    // Implies: k_d_idx <= op_d  AND  k_d_idx > op_d - in_depth * sd
    int kd_min = op_d - in_depth * sd + 1;
    if (kd_min < 0) kd_min = 0;
    int kd_max = (op_d < kd - 1) ? op_d : kd - 1;

    int kh_min = op_h - in_height * sh + 1;
    if (kh_min < 0) kh_min = 0;
    int kh_max = (op_h < kh - 1) ? op_h : kh - 1;

