    if (kw_min < 0) kw_min = 0;
    int kw_max = (op_w < kw - 1) ? op_w : kw - 1;

    // Adjust start indices to satisfy stride condition: (op - k) % s == 0
    int shift_d = (op_d % sd) - (kd_min % sd);
    if (shift_d < 0) shift_d += sd;
    int kd_start = kd_min + shift_d;

    int shift_h = (op_h % sh) - (kh_min % sh);
    if (shift_h < 0) shift_h += sh;
    int kh_start = kh_min + shift_h;

    int shift_w = (op_w % sw) - (kw_min % sw);
    if (shift_w < 0) shift_w += sw;
    int kw_start = kw_min + shift_w;

