from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for 3D Transposed Convolution
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels, int out_channels,
    int in_d, int in_h, int in_w,
    int out_d, int out_h, int out_w,
    int k_d, int k_h, int k_w,
    int stride, int padding, int groups) {

    // Total elements in the output tensor
    int total_elements = batch_size * out_channels * out_d * out_h * out_w;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= total_elements) return;

    // Decode linear index to (n, c_out, d_out, h_out, w_out)
    // Assuming NCDHW layout, W varies fastest
    int w_out_idx = idx % out_w;
    int temp = idx / out_w;
    int h_out_idx = temp % out_h;
    temp /= out_h;
    int d_out_idx = temp % out_d;
    temp /= out_d;
    int c_out_idx = temp % out_channels;
    int n_idx = temp / out_channels;

    // Calculate group information
    int out_c_per_group = out_channels / groups;
    int in_c_per_group = in_channels / groups;
    int group_idx = c_out_idx / out_c_per_group;
    int c_out_in_group = c_out_idx % out_c_per_group;

    float sum = 0.0f;
    if (bias != nullptr) {
        sum = bias[c_out_idx];
    }

    // Transposed Convolution formulation:
    // Output position (d_out, h_out, w_out) accumulates contributions from 
    // input positions (d_in, h_in, w_in) multiplied by weights.
    // Relation: out = in * stride + k - padding
    // Therefore: in = (out + padding - k) / stride

    // Iterate over kernel dimensions
    for (int kd = 0; kd < k_d; ++kd) {
        int d_in_numerator = d_out_idx + padding - kd;
        // Check if this kernel position aligns with an input on the strided grid
        if (d_in_numerator % stride != 0) continue;
        int d_in_idx = d_in_numerator / stride;

        // Boundary check for input depth
        if (d_in_idx < 0 || d_in_idx >= in_d) continue;

        for (int kh = 0; kh < k_h; ++kh) {
            int h_in_numerator = h_out_idx + padding - kh;
            if (h_in_numerator % stride != 0) continue;
            int h_in_idx = h_in_numerator / stride;

            if (h_in_idx < 0 || h_in_idx >= in_h) continue;

            for (int kw = 0; kw < k_w; ++kw) {
                int w_in_numerator = w_out_idx + padding - kw;
                if (w_in_numerator % stride != 0) continue;
                int w_in_idx = w_in_numerator / stride;

                if (w_in_idx < 0 || w_in_idx >= in_w) continue;

                // Accumulate over all input channels in the current group
                int c_in_start = group_idx * in_c_per_group;
                for (int ic = 0; ic < in_c_per_group; ++ic) {
                    int c_in_idx = c_in_start + ic;

                    // Compute flat indices
                    long long input_offset = (long long)n_idx * in_channels * in_d * in_h * in_w +
                                             (long long)c_in_idx * in_d * in_h * in_w +
                                             (long long)d_in_idx * in_h * in_w +
                                             h_in_idx * in_w +
                                             w_in_idx;

                    // Weight layout: (in_channels, out_channels/groups, k, k, k)
                    // Note: c_in_idx iterates 0..in_channels-1 globally
                    long long weight_offset = (long long)c_in_idx * out_c_per_group * k_d * k_h * k_w +
                                              (long long)c_out_in_group * k_d * k_h * k_w +
                                              kd * k_h * k_w +
                                              kh * k_w +
                                              kw;

                    sum += input[input_offset] * weight[weight_offset];
                }
            }
        }
    }

    output[idx] = sum;
}

torch::Tensor conv_transpose3d_cuda_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int groups) {

    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_d = input.size(2);
    int in_h = input.size(3);
    int in_w = input.size(4);

    // Weight shape is (in_channels, out_channels // groups, k, k, k)
    int out_c_per_group = weight.size(1);
    int k_d = weight.size(2);
    int k_h = weight.size(3);
    int k_w = weight.size(4);
    int out_channels = out_c_per_group * groups;

    // Calculate output dimensions
    int out_d = (in_d - 1) * stride - 2 * padding + k_d + output_padding;
    int out_h = (in_h - 1) * stride - 2 * padding + k_h + output_padding;
    int out_w = (in_w - 1) * stride - 2 * padding + k_w + output_padding;

    auto output = torch::zeros({batch_size, out_channels, out_d, out_h, out_w}, input.options());

    const float* bias_ptr = nullptr;
    if (bias.defined() && bias.numel() > 0) {
        bias_ptr = bias.data_ptr<float>();
    }

    int total_elements = batch_size * out_channels * out_d * out_h * out_w;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    conv_transpose3d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        in_d, in_h, in_w,
        out_d, out_h, out_w,
        k_d, k_h, k_w,
        stride, padding, groups
    );

    return output;
}
"""

cpp_source = """
torch::Tensor conv_transpose3d_cuda_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int groups);
"""

# Compile and load the extension
conv_transpose3d_op = load_inline(
    name="conv_transpose3d_op",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["conv_transpose3d_cuda_forward"],
    extra_cuda_cflags=["-O3"],
