class ModelNew(nn.Module):
    """
    Optimized Model with custom CUDA 3D Transposed Convolution operator.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.stride = stride
        self.padding = padding
        # In the original Model, output_padding is passed in __init__ but ignored 
        # when creating nn.ConvTranspose3d (which defaults to 0). 
        # We replicate this behavior by setting it to 0 for the op.
        self.output_padding = 0 
        self.groups = groups

        # Initialize weights to match expected shape for ConvTranspose3d:
        # (in_channels, out_channels // groups, k, k, k)
        self.weight = nn.Parameter(torch.randn(in_channels, out_channels // groups, kernel_size, kernel_size, kernel_size))

        if bias:
            self.bias = nn.Parameter(torch.randn(out_channels))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the 3D transposed convolution using the custom CUDA kernel.
        """
        return conv_transpose3d_op.conv_transpose3d_cuda_forward(
            x, 
            self.weight, 
            self.bias, 
            self.stride, 
            self.padding, 
            self.output_padding, 
            self.groups
        )

