#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int C_out,
    int D_in, int H_in, int W_in,
    int D_out, int H_out, int W_out,
    int K, int S, int P, int G,
    int C_in_per_group, int C_out_per_group) {

    long long total_elements = (long long)N * C_out * D_out * H_out * W_out;
    long long index = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    if (index >= total_elements) return;

    int wo = index % W_out;
    int ho = (index / W_out) % H_out;
    int do_ = (index / (1LL * W_out * H_out)) % D_out;
    int co = (index / (1LL * W_out * H_out * D_out)) % C_out;
    int n = index / (1LL * W_out * H_out * D_out * C_out);

    int group = co / C_out_per_group;
    int co_rel = co % C_out_per_group;
    int ci_start = group * C_in_per_group;

    float val = 0.0f;

    // The logic maps each output pixel back to contributing input pixels.
    // Given: do = di * S + kd - P => kd = do + P - di * S.
    // Since 0 <= kd < K, we iterate through kernel kd and check if (do + P - kd) is divisible by stride S.
    for (int kd = 0; kd < K; ++kd) {
        int di_s = do_ + P - kd;
        if (di_s >= 0 && di_s % S == 0) {
            int di = di_s / S;
            if (di < D_in) {
                for (int kh = 0; kh < K; ++kh) {
                    int hi_s = ho + P - kh;
                    if (hi_s >= 0 && hi_s % S == 0) {
                        int hi = hi_s / S;
                        if (hi < H_in) {
                            for (int kw = 0; kw < K; ++kw) {
                                int wi_s = wo + P - kw;
                                if (wi_s >= 0 && wi_s % S == 0) {
                                    int wi = wi_s / S;
                                    if (wi < W_in) {
                                        for (int ci_rel = 0; ci_rel < C_in_per_group; ++ci_rel) {
                                            int ci = ci_start + ci_rel;
                                            // Weight shape: (C_in, C_out_per_group, K, K, K)
                                            // Input shape: (N, C_in, D_in, H_in, W_in)
                                            long long input_idx = ((((1LL * n * C_in + ci) * D_in + di) * H_in + hi) * W_in + wi);
                                            long long weight_idx = ((((1LL * ci * C_out_per_group + co_rel) * K + kd) * K + kh) * K + kw);
                                            val += input[input_idx] * weight[weight_idx];
                                        }
                                    }
                                }
