__global__ void conv_transpose1d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int length_in,
    int length_out,
    int kernel_size,
    int stride,
    int padding,
    int dilation) {

    // Map thread to output position (b, c_out, j)
    // j corresponds to the spatial index in output
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    int c_out = blockIdx.y;
    int b = blockIdx.z;

    if (j >= length_out) return;

    float sum = 0.0f;
    if (bias != nullptr) {
        sum = bias[c_out];
    }

    // The relationship between input index i and output index j is:
    // j = i * stride + k * dilation - padding
    // We iterate over k (kernel index) to find the corresponding i.
    // i = (j - k * dilation + padding) / stride

    for (int k = 0; k < kernel_size; ++k) {
        int rhs = j - k * dilation + padding;

        // Check if a valid i exists for this k
        if (rhs >= 0 && rhs % stride == 0) {
            int i = rhs / stride;

            // Check input bounds
            if (i < length_in) {
                // Perform dot product over input channels
                // Weight layout: (in_channels, out_channels, kernel_size) for groups=1
                // Input layout: (batch_size, in_channels, length_in)

