    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size, int in_channels, int out_channels,
    int length_in, int length_out,
    int kernel_size, int stride, int padding, int dilation,
    bool has_bias) {

    int l_out = blockIdx.x * blockDim.x + threadIdx.x;
    int c_out = blockIdx.y;
    int n = blockIdx.z;

    if (l_out < length_out && c_out < out_channels && n < batch_size) {
        float sum = 0.0f;
        // Transposed convolution indexing logic:
        // Output index j = i * stride - padding + k * dilation
        // Solving for input index i: i = (j + padding - k * dilation) / stride
        for (int k = 0; k < kernel_size; ++k) {
            int source_idx_raw = l_out + padding - k * dilation;
            if (source_idx_raw >= 0) {
                int l_in = source_idx_raw / stride;
                // Check if division was exact and within input bounds
