// CUDA Kernel for Depthwise Convolution (Square kernel, variable size/stride/padding/dilation)
__global__ void depthwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int channels,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    bool has_bias
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * channels * out_h * out_w;

    if (idx < total_elements) {
        // Map linear index to (n, c, h_out, w_out)
        int w_out = idx % out_w;
        int h_out = (idx / out_w) % out_h;
        int c = (idx / (out_w * out_h)) % channels;
        int n = idx / (out_w * out_h * channels);

        float val = 0.0f;

        int h_in_base = h_out * stride - padding;
        int w_in_base = w_out * stride - padding;

        // Weight layout for depthwise conv in PyTorch (groups=channels): (Channels, 1, K, K)
        // Memory layout is flat: c * K * K + ky * K + kx
        int weight_offset_base = c * kernel_size * kernel_size;

        for (int ky = 0; ky < kernel_size; ++ky) {
            for (int kx = 0; kx < kernel_size; ++kx) {
                int h_in = h_in_base + ky * dilation;
                int w_in = w_in_base + kx * dilation;

