// CUDA Kernel for Pointwise Convolution (1x1 Convolution)
__global__ void pointwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int h,
    int w,
    bool has_bias
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * h * w;

    if (idx < total_elements) {
        // Map linear index to (n, oc, y, x)
        int x = idx % w;
        int y = (idx / w) % h;
        int oc = (idx / (w * h)) % out_channels;
        int n = idx / (w * h * out_channels);

        float val = 0.0f;

        // Input: (N, Cin, H, W)
        // Weight: (Cout, Cin, 1, 1) -> effectively (Cout, Cin)

        // Loop over input channels
        for (int ic = 0; ic < in_channels; ++ic) {
