# Define the custom CUDA kernel for 1x1 Convolution (Pointwise)
# optimized for NCHW layout and coalesced memory access.
pointwise_conv2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void pointwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int height,
    int width) {

    // Kernel strategy:
    // - Map x dimension to Width (w) to ensure coalesced reads/writes.
    // - Map y dimension to Output Channels (oc) subset for parallelism.
    // - Map grid y to Batch * Height (n * h) to parallelize over spatial dims and batch.

    // Global indices
    int w = blockIdx.x * blockDim.x + threadIdx.x;
    int oc = blockIdx.z * blockDim.y + threadIdx.y;
    int n_h = blockIdx.y; // flattened batch and height index

    // Boundary checks
    if (w >= width || oc >= out_channels || n_h >= batch_size * height) return;

    // Decode flattened index
    int n = n_h / height;
    int h = n_h % height;

    // Pre-calculate strides for efficiency
    // Input shape: (N, Cin, H, W)
    // Stride for Cin is H * W
    size_t hw = (size_t)height * width;

    // Base address for input: element at (n, 0, h, w)
    size_t input_base = (size_t)n * in_channels * hw + (size_t)h * width + w;

    // Base address for weight: row for 'oc'
    // Weight shape: (Cout, Cin)
    size_t weight_base = (size_t)oc * in_channels;

    // Initialize accumulation with bias if present
    float sum = 0.0f;
    if (bias != nullptr) {
        sum = bias[oc];
    }

    // Loop over input channels (reduction dimension)
    for (int ic = 0; ic < in_channels; ++ic) {
        // Load input: memory access is coalesced because adjacent threads (diff w) 
        // read adjacent memory locations.
        float val_x = input[input_base + (size_t)ic * hw];

        // Load weight: broadcasted across warp for threads with same 'oc'
        float val_w = weight[weight_base + ic];

        sum += val_x * val_w;
    }

