import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for pointwise (1x1) 2D convolution.
# Pointwise convolution is memory-bound. This kernel optimizes memory access by:
# 1. Mapping each thread to a specific spatial output pixel (n, h, w).
# 2. Using a 2D grid where gridDim.x covers the spatial dimension and gridDim.y covers output channels.
# 3. Ensuring perfectly coalesced memory reads for input pixels across threads in a warp.
# 4. Utilizing single-value broadcasts for weights within a warp.
pointwise_conv2d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void pointwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int Cin, int Cout, int H, int W,
    bool has_bias) {

    // hw represents the spatial index (h * W + w)
    int hw = blockIdx.x * blockDim.x + threadIdx.x;
    // n_oc represents a combined batch and output channel index
    int n_oc = blockIdx.y;
    int S = H * W;

    if (hw < S) {
        int oc = n_oc % Cout;
        int n = n_oc / Cout;

        float sum = has_bias ? bias[oc] : 0.0f;

        // Base pointer for input at (n, 0, h, w)
        long long in_idx = (long long)n * Cin * S + hw;
        // Base pointer for weight at (oc, 0)
        int w_idx = oc * Cin;

        // Dot product along input channels
        // Input access is (n*Cin + ic)*S + hw. As ic increments, index jumps by S.
        // For a warp, hw is consecutive, so threads read consecutive floats -> Coalesced.
        for (int ic = 0; ic < Cin; ++ic) {
            sum += __ldg(&input[in_idx]) * __ldg(&weight[w_idx]);
            in_idx += S;
            w_idx++;
        }

        // Write output at (n, oc, h, w)
        output[(long long)n_oc * S + hw] = sum;
    }
}

