#include <cuda_runtime.h>
#include <cmath>

__global__ void gelu_approx_kernel(const float* __restrict__ x, float* __restrict__ out, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
