// Each block processes one row.
__global__ void cumsum_row_kernel(float* data, int rows, int cols) {
    int row_idx = blockIdx.x;
    if (row_idx >= rows) return;

    // Pointer to the start of the row
    float* row_ptr = data + row_idx * cols;

    // Running aggregate to carry sum across chunks of the row
    float block_aggregate = 0.0f;

    // Loop over the row in chunks of blockDim.x
    for (int offset = 0; offset < cols; offset += blockDim.x) {
        int tid = threadIdx.x;
        int idx = offset + tid;

        float val = 0.0f;
        // Load data if within bounds
        if (idx < cols) {
            val = row_ptr[idx];
        }

        // 1. Warp-level inclusive scan using shuffle instructions
        unsigned int mask = 0xffffffff;
        int lane = tid % 32;
        int warp = tid / 32;

        #pragma unroll
        for (int delta = 1; delta < 32; delta *= 2) {
            float temp = __shfl_up_sync(mask, val, delta);
            if (lane >= delta) val += temp;
        }

        // 2. Store the total sum of each warp into shared memory
        // Assuming blockDim.x <= 1024, we have at most 32 warps.
        __shared__ float warp_sums[32];
        if (lane == 31) {
            warp_sums[warp] = val;
        }
        __syncthreads();

        // 3. Perform scan on the warp sums (using the first warp)
        if (warp == 0) {
            float w_val = (tid < 32) ? warp_sums[tid] : 0.0f;

            #pragma unroll
            for (int delta = 1; delta < 32; delta *= 2) {
                float temp = __shfl_up_sync(mask, w_val, delta);
                if (tid >= delta) w_val += temp;
            }

            if (tid < 32) {
                warp_sums[tid] = w_val;
            }
        }
        __syncthreads();

        // 4. Add the base offset from previous warps to all threads
        if (warp > 0) {
            val += warp_sums[warp - 1];
        }

        // 5. Add the aggregate from previous chunks
        val += block_aggregate;

        // 6. Write the scanned value back to global memory
        if (idx < cols) {
            row_ptr[idx] = val;
        }

        // 7. Calculate and broadcast the total sum of this chunk for the next iteration
        // The last valid thread in this chunk holds the cumulative sum up to this point.
        int remaining = cols - offset;
        int last_active_tid = (remaining < blockDim.x) ? (remaining - 1) : (blockDim.x - 1);

        __shared__ float next_aggregate;
        if (tid == last_active_tid) {
