#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 1024

__global__ void reverse_cumsum_kernel(const float* __restrict__ input, float* __restrict__ output, int width, int total_rows) {
    // Each block processes one row independently
    int row_idx = blockIdx.x;
    if (row_idx >= total_rows) return;

    // Pointers to the start of the row
    const float* row_in = input + row_idx * width;
    float* row_out = output + row_idx * width;

    // Shared memory for block-level scan
    __shared__ float smem[BLOCK_SIZE];
    __shared__ float s_carry;

    float current_carry = 0.0f;

    // Calculate number of chunks needed to cover the width
    // We process chunks from right to left (end of row to start)
    int num_chunks = (width + BLOCK_SIZE - 1) / BLOCK_SIZE;

    for (int c = num_chunks - 1; c >= 0; --c) {
        int base_idx = c * BLOCK_SIZE;
        int tid = threadIdx.x;
        int idx = base_idx + tid;

        // 1. Load data into shared memory
        float val = 0.0f;
        if (idx < width) {
            val = row_in[idx];
        }
        smem[tid] = val;
        __syncthreads();

        // 2. Perform inclusive reverse scan (suffix sum) within the block using Hillis-Steele
        // We accumulate from right to left: x[i] += x[i+offset]
        for (int offset = 1; offset < BLOCK_SIZE; offset *= 2) {
            float temp = 0.0f;
            if (tid + offset < BLOCK_SIZE) {
                temp = smem[tid + offset];
            }
            __syncthreads();
            smem[tid] += temp;
            __syncthreads();
        }

        // 3. Add carry from the previous chunk (which was to the right of this one)
        if (idx < width) {
            smem[tid] += current_carry;
        }

        // Ensure smem update is visible before reading new carry
        __syncthreads();

        // 4. Determine carry for the next iteration (chunk to the left)
        // The leftmost element (tid=0) in shared memory now contains the total sum of this chunk + previous carry.
        if (tid == 0) {
            s_carry = smem[0];
        }

        // 5. Write result to global memory
        if (idx < width) {
            row_out[idx] = smem[tid];
        }

        // Wait for s_carry to be written so all threads can read it
        __syncthreads();
        current_carry = s_carry;
    }
}

