    int cols = input.size(1);

    auto output = torch::empty_like(input);

    // Grid x dimension covers all rows. Modern GPUs support large Grid X (2^31-1).
    dim3 grid(rows);
    dim3 block(BLOCK_SIZE);

    reverse_cumsum_kernel<<<grid, block>>>(input.data_ptr<float>(), output.data_ptr<float>(), cols, rows);

    return output;
