#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void exclusive_cumsum_kernel(const float* __restrict__ input, 
                                        float* __restrict__ output, 
                                        long long outer_size, 
                                        long long scan_size, 
                                        long long inner_size) {
