    long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long total_sequences = outer_size * inner_size;

    if (idx < total_sequences) {
        long long i_outer = idx / inner_size;
        long long i_inner = idx % inner_size;

