        long long j = j_start + tid;
        bool within_bounds = (j < dim1);
        long long flat_idx = (d0 * dim1 + j) * dim2 + d2;

        // Fusing the multiplication by mask
        float val = within_bounds ? (x[flat_idx] * (float)mask_ptr[flat_idx]) : 0.0f;

