# Define the custom CUDA kernel for Cross Entropy Loss
# This implementation uses a fused kernel that computes the loss per sample.
# It employs vectorized memory access (float4) for higher bandwidth utilization
# and warp/block-level reductions for computing the Max and SumExp values efficiently.
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// Warp Reduce Max
__inline__ __device__ float warpReduceMax(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
    return val;
}

// Warp Reduce Sum
__inline__ __device__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__global__ void cross_entropy_kernel(
    const float* __restrict__ logits, 
    const int64_t* __restrict__ targets, 
    float* __restrict__ losses,
    int batch_size, 
    int num_classes) 
{
    int row = blockIdx.x; 
    if (row >= batch_size) return;

    // Use float4 for vectorized loads to improve memory bandwidth
    // num_classes (4096) is divisible by 4
    const float4* row_logits_4 = reinterpret_cast<const float4*>(logits + row * num_classes);
    int num_classes_4 = num_classes / 4;

    int tid = threadIdx.x;

    // 1. Find Max (for numerical stability)
    float thread_max = -1e30f; 

    for (int i = tid; i < num_classes_4; i += blockDim.x) {
        float4 v = row_logits_4[i];
        float local_max = fmaxf(fmaxf(v.x, v.y), fmaxf(v.z, v.w));
        thread_max = fmaxf(thread_max, local_max);
    }

    // Intra-warp reduction
    thread_max = warpReduceMax(thread_max);

    // Shared memory for inter-warp reduction
    // Block size 256 -> 8 warps. 32 is sufficient.
    __shared__ float sdata[32];
    int lane = tid % 32;
    int wid = tid / 32;

    if (lane == 0) sdata[wid] = thread_max;
    __syncthreads();

    // First warp reduces the shared memory values
    // Only threads 0 to (num_warps-1) need to load
    float row_max = (tid < blockDim.x / 32) ? sdata[lane] : -1e30f;
    if (wid == 0) {
        row_max = warpReduceMax(row_max);
    }
    // Broadcast row_max to all threads via shared memory
    if (tid == 0) sdata[0] = row_max;
    __syncthreads();
    row_max = sdata[0];

    // 2. Compute Sum of Exponentials
    float thread_sum = 0.0f;
    for (int i = tid; i < num_classes_4; i += blockDim.x) {
        float4 v = row_logits_4[i];
        thread_sum += expf(v.x - row_max) + expf(v.y - row_max) + 
                      expf(v.z - row_max) + expf(v.w - row_max);
    }

    thread_sum = warpReduceSum(thread_sum);

    if (lane == 0) sdata[wid] = thread_sum;
    __syncthreads();

    float row_sum = (tid < blockDim.x / 32) ? sdata[lane] : 0.0f;
    if (wid == 0) {
        row_sum = warpReduceSum(row_sum);
    }
    // No need to broadcast row_sum, only thread 0 writes the output

    // 3. Compute Final Loss for Row
    if (tid == 0) {
        // LogSoftmax calculation: log(sum(exp(x_i - max))) + max
        float log_sum_exp = logf(row_sum) + row_max;

        // Get target value
        const float* row_logits_ptr = logits + row * num_classes;
        int64_t target_idx = targets[row];
        float target_val = row_logits_ptr[target_idx];

        // Cross Entropy Loss = log_sum_exp - target_logit
        losses[row] = log_sum_exp - target_val;
    }
}

