#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

// Warp reduction to sum values within a warp
template <typename T>
__device__ __forceinline__ T warpReduceSum(T val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

// Block reduction to sum values within a block
template <typename T>
__device__ __forceinline__ T blockReduceSum(T val) {
    static __shared__ T shared[32]; // Shared memory for 32 partial sums (max 1024 threads / 32)
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceSum(val);     // Reduce within warp

    if (lane == 0) shared[wid] = val; // Store warp sum
    __syncthreads();              // Wait for all warps

    // Read back partial sums (only first warp does this)
    val = (threadIdx.x < blockDim.x / 32) ? shared[lane] : 0;

    if (wid == 0) val = warpReduceSum(val); // Final reduce in first warp

    return val;
}

__global__ void smooth_l1_kernel(const float* __restrict__ predictions, 
                                 const float* __restrict__ targets, 
                                 float* __restrict__ out, 
                                 int64_t n) {
    // Grid-stride loop indices
    int64_t tid = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = blockDim.x * gridDim.x;

    float local_sum = 0.0f;

    // Grid-stride loop: process elements
    for (int64_t i = tid; i < n; i += stride) {
        float diff = predictions[i] - targets[i];
        float abs_diff = fabsf(diff);
        float loss_val;

        // Smooth L1 logic: 0.5 * x^2 if |x| < 1 else |x| - 0.5
        if (abs_diff < 1.0f) {
            loss_val = 0.5f * diff * diff;
        } else {
            loss_val = abs_diff - 0.5f;
        }
        local_sum += loss_val;
    }

    // Reduce thread local sums to block sum
    local_sum = blockReduceSum(local_sum);

    // Atomic add block sum to global accumulator
    if (threadIdx.x == 0) {
        atomicAdd(out, local_sum);
    }
