import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA source code for the Fused Attention Kernel
# This kernel implements a simplified Flash Attention-like algorithm.
# It processes 4 queries per thread block to optimize memory bandwidth.
# Optimizations:
# - Tiling: Processes Q and K/V in blocks to fit in Shared Memory.
# - Vectorized Loads: Uses float4 for efficient global memory access.
# - Fused Softmax: Computes softmax online/fused within the kernel.
# - Shared Memory Buffering: Minimizes global memory round-trips.
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <vector>

#define TILE_Q 4
#define TILE_K 4
#define WARP_SIZE 32
#define BLOCK_SIZE 256

// Helper for warp reduction
__device__ inline float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__device__ inline float warpReduceMax(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
    return val;
}

__global__ void fused_attention_kernel(
    const float* __restrict__ Q,
    const float* __restrict__ K,
    const float* __restrict__ V,
    float* __restrict__ Out,
    int B, int H, int L, int D,
    float scale) 
{
    // Grid: x = L / TILE_Q, y = H, z = B
    int l_tile_idx = blockIdx.x;
    int h_idx = blockIdx.y;
    int b_idx = blockIdx.z;

    // Offsets
    long long batch_head_offset = (long long)b_idx * (H * L * D) + (long long)h_idx * (L * D);
    const float* q_ptr = Q + batch_head_offset;
    const float* k_base = K + batch_head_offset;
    const float* v_base = V + batch_head_offset;
    float* out_ptr = Out + batch_head_offset;

    // Shared Memory Layout
    // 1. Q_tile: TILE_Q * D floats
    // 2. K_tile (reused for V): TILE_K * D floats
    // 3. Logits: TILE_Q * L floats
    // 4. Reductions: 4 subgroups * 2 warps floats
    extern __shared__ float smem[];
    float* smem_q = smem;
    float* smem_k = smem + TILE_Q * D; 
    float* smem_logits = smem_k + TILE_K * D;
    float* smem_red = smem_logits + TILE_Q * L;

    int tid = threadIdx.x;

    // Subgroup info: Each subgroup of 64 threads handles 1 Query
    // We have TILE_Q = 4 queries. 256 threads / 4 = 64 threads per query.
    int sg_id = tid / 64;     // 0..3
    int lane_id = tid % 64;   // 0..63

    // 1. Load Q Tile into Shared Memory
    // We load TILE_Q rows of Q. Row indices: l_tile_idx * 4 + 0..3
    // Total floats: 4 * 1024 = 4096.
    // 256 threads. Each loads 16 floats (4 float4).
    int q_start_row = l_tile_idx * TILE_Q;
    const float4* q_ptr_4 = (const float4*)(q_ptr + q_start_row * D);
    float4* smem_q_4 = (float4*)smem_q;

    // Copy 4 float4s per thread
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        int idx = tid + i * 256; // index in float4 array (total 1024 float4s)
        if (idx < TILE_Q * (D/4)) {
            smem_q_4[idx] = q_ptr_4[idx];
        }
    }
    __syncthreads();

    // 2. Compute Logits
    // Iterate over K in tiles
    for (int k_tile_start = 0; k_tile_start < L; k_tile_start += TILE_K) {
        // Load K Tile (4 rows)
        const float4* k_ptr_4 = (const float4*)(k_base + k_tile_start * D);
        float4* smem_k_4 = (float4*)smem_k;

        #pragma unroll
        for (int i = 0; i < 4; ++i) {
            int idx = tid + i * 256;
            if (idx < TILE_K * (D/4)) {
                smem_k_4[idx] = k_ptr_4[idx];
            }
        }
        __syncthreads();

        // Compute Dot Product
        // Subgroup sg_id computes dot product of Q[sg_id] with K[0..3]
        // Each thread (lane_id) handles subset of D (1024).
        // 64 threads. Each handles 16 elements.

        float q_vals[16];
        // Load Q values for this thread from smem
        #pragma unroll
        for (int i = 0; i < 16; ++i) {
            q_vals[i] = smem_q[sg_id * D + lane_id + i * 64];
        }

        // For each key in the tile
        for (int k = 0; k < TILE_K; ++k) {
            float sum = 0.0f;
            #pragma unroll
            for (int i = 0; i < 16; ++i) {
                sum += q_vals[i] * smem_k[k * D + lane_id + i * 64];
            }

            // Reduce sum within subgroup (64 threads)
            // 1. Warp reduction
            sum = warpReduceSum(sum);

            // 2. Inter-warp reduction (2 warps per subgroup)
            int warp_id = lane_id / 32;
            if (lane_id % 32 == 0) {
                smem_red[sg_id * 2 + warp_id] = sum;
            }
            __syncthreads(); // Wait for shared mem write

            if (lane_id == 0) {
                sum = smem_red[sg_id * 2 + 0] + smem_red[sg_id * 2 + 1];
                smem_logits[sg_id * L + k_tile_start + k] = sum * scale;
            }
            __syncthreads();
        }
        __syncthreads();
    }

    // 3. Softmax (per subgroup/query)
    // Range of logits: sg_id * L to sg_id * L + L - 1
    float* my_logits = smem_logits + sg_id * L;

    // Find Max
    float l_max = -1e37f;
    for (int i = lane_id; i < L; i += 64) {
        l_max = fmaxf(l_max, my_logits[i]);
    }
    l_max = warpReduceMax(l_max);

    int warp_in_sg = lane_id / 32;
    if (lane_id % 32 == 0) smem_red[sg_id * 2 + warp_in_sg] = l_max;
    __syncthreads();

    float global_max;
    if (lane_id == 0) {
        global_max = fmaxf(smem_red[sg_id * 2 + 0], smem_red[sg_id * 2 + 1]);
        smem_red[sg_id * 2 + 0] = global_max; // Broadcast via smem
    }
    __syncthreads();
    global_max = smem_red[sg_id * 2 + 0];

    // Exponentials and Sum
    float l_sum = 0.0f;
    for (int i = lane_id; i < L; i += 64) {
        float val = __expf(my_logits[i] - global_max);
        my_logits[i] = val;
        l_sum += val;
    }
    l_sum = warpReduceSum(l_sum);

    if (lane_id % 32 == 0) smem_red[sg_id * 2 + warp_in_sg] = l_sum;
    __syncthreads();

    float global_sum;
    if (lane_id == 0) {
        global_sum = smem_red[sg_id * 2 + 0] + smem_red[sg_id * 2 + 1];
        smem_red[sg_id * 2 + 0] = global_sum;
    }
    __syncthreads();
    global_sum = smem_red[sg_id * 2 + 0];
    float inv_sum = 1.0f / (global_sum + 1e-6f);

    // Normalize (Optional, we can just use inv_sum in accumulation)
    // We'll normalize in registers during accumulation to save stores?
    // No, let's update smem to keep it clean.
    for (int i = lane_id; i < L; i += 64) {
        my_logits[i] *= inv_sum;
    }
    __syncthreads();

    // 4. Compute Output (Accumulate V)
    // Accumulators for this thread's slice of D
    float acc[16];
    #pragma unroll
    for (int i = 0; i < 16; ++i) acc[i] = 0.0f;

    // Reuse smem_k for V tiles
    for (int v_tile_start = 0; v_tile_start < L; v_tile_start += TILE_K) {
        // Load V Tile
        const float4* v_ptr_4 = (const float4*)(v_base + v_tile_start * D);
        float4* smem_v_4 = (float4*)smem_k; // Reuse K buffer

        #pragma unroll
        for (int i = 0; i < 4; ++i) {
            int idx = tid + i * 256;
            if (idx < TILE_K * (D/4)) {
                smem_v_4[idx] = v_ptr_4[idx];
            }
        }
        __syncthreads();

        // Accumulate
        // Thread (lane) computes output indices: lane + i*64
        for (int k = 0; k < TILE_K; ++k) {
            float weight = my_logits[v_tile_start + k];
            #pragma unroll
            for (int i = 0; i < 16; ++i) {
                acc[i] += weight * smem_k[k * D + lane_id + i * 64];
            }
        }
        __syncthreads();
    }

    // 5. Write Output
    int out_row = q_start_row + sg_id;
    // Each thread writes its 16 values
    // We need to write float4s for speed if possible, but indices are scattered?
    // lane + i*64.
    // i=0: lane. i=1: lane+64.
    // If lane=0: 0, 64, 128... Not contiguous.
    // Can't use float4 stores easily without shuffling. Use float stores.
    // Global Memory: Out + out_row * D
    float* my_out_ptr = out_ptr + out_row * D;
    #pragma unroll
    for (int i = 0; i < 16; ++i) {
        my_out_ptr[lane_id + i * 64] = acc[i];
    }
}

torch::Tensor fused_attention_cuda(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    auto B = Q.size(0);
    auto H = Q.size(1);
    auto L = Q.size(2);
    auto D = Q.size(3);

    auto options = torch::TensorOptions().dtype(Q.dtype()).device(Q.device());
    auto Out = torch::empty({B, H, L, D}, options);

    float scale = 1.0f / sqrtf((float)D);

    // TILE_Q = 4
    dim3 grid(L / 4, H, B);
    dim3 block(256);

    // Shared Mem Size
    // Q: 4 * 1024 * 4 bytes = 16KB
    // K: 4 * 1024 * 4 bytes = 16KB
    // Logits: 4 * 512 * 4 bytes = 8KB
    // Reductions: 8 * 4 bytes = 32 bytes
