import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused KL Divergence
# This kernel fuses the element-wise operations: log, multiplication, subtraction,
# and performs a global reduction (sum) using a grid-stride loop and block reductions.
kl_div_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Warp reduction to sum values within a warp
__device__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

// Block reduction to sum values within a block
__device__ float blockReduceSum(float val) {
    static __shared__ float shared[32]; // Shared memory for warp sums
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceSum(val); // Sum within warp

    if (lane == 0) shared[wid] = val; // Store warp sum

    __syncthreads();

    // Read warp sums. Only the first warp needs to do this.
    // Since we use 256 threads, we have 8 warps. shared[0...7] are valid.
    val = (threadIdx.x < blockDim.x / 32) ? shared[lane] : 0;

    if (wid == 0) val = warpReduceSum(val); // Sum the warp sums

    return val;
}

__global__ void kl_div_fused_kernel(const float* __restrict__ preds, 
                                    const float* __restrict__ targets, 
                                    float* __restrict__ output, 
                                    int size) {
    // Grid-stride loop index
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    float sum = 0.0f;

    // Iterate over the data
    for (int i = tid; i < size; i += stride) {
        float p = preds[i];
        float t = targets[i];

        // KL Divergence formula element-wise: target * (log(target) - log(prediction))
        // We accumulate only if target > 0 to avoid 0*log(0) which should be 0 limit-wise.
        // Assuming predictions are positive (result of softmax), log(p) is valid.
        if (t > 0.0f) {
            sum += t * (logf(t) - logf(p));
        }
    }

    // Reduce accumulated sum within the block
    sum = blockReduceSum(sum);

    // Write the result for this block to global memory
    if (threadIdx.x == 0) {
        output[blockIdx.x] = sum;
    }
}

torch::Tensor kl_div_cuda(torch::Tensor preds, torch::Tensor targets) {
    // Ensure inputs are contiguous for direct pointer access
    preds = preds.contiguous();
    targets = targets.contiguous();

    int size = preds.numel();
    const int threads = 256;
    const int blocks = 1024; // Fixed number of blocks for grid-stride

    // Allocate output tensor for partial sums (one float per block)
    auto out = torch::empty({blocks}, preds.options());

    kl_div_fused_kernel<<<blocks, threads>>>(
        preds.data_ptr<float>(), 
        targets.data_ptr<float>(), 
        out.data_ptr<float>(), 
        size
    );

    return out;
}
"""

