# F.kl_div(torch.log(predictions), targets, reduction='batchmean')
# This fuses the log(predictions), the kl_div element-wise calculation, 
# and the summation into a single kernel to maximize memory bandwidth usage.
kl_div_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void kl_div_kernel(const float* predictions, const float* targets, float* out, size_t N) {
    double thread_sum = 0.0;
    size_t idx = (size_t)blockIdx.x * blockDim.x + threadIdx.x;
    size_t stride = (size_t)blockDim.x * gridDim.x;

    for (size_t i = idx; i < N; i += stride) {
        float p = predictions[i];
        float t = targets[i];
        if (t > 0.0f) {
            // Formula: L = target * (log(target) - input)
            // Original: input = log(predictions), target = targets
            // Fused: L = t * (logf(t) - logf(p))
            thread_sum += (double)t * (logf(t) - logf(p));
        }
    }

    // Warp-level reduction
    for (int offset = 16; offset > 0; offset /= 2)
        thread_sum += __shfl_down_sync(0xffffffff, thread_sum, offset);

    // Atomic add the warp sum to the global scalar
    if ((threadIdx.x & 31) == 0) {
        atomicAdd(out, (float)thread_sum);
    }
}

