    int wid = threadIdx.x / 32;

    val = warpReduceSum(val);     // Each warp performs partial reduction

    if (lane == 0) shared[wid] = val; // Write reduced value to shared memory

    __syncthreads();              // Wait for all partial reductions

    // Read from shared memory only if that warp existed
    val = (threadIdx.x < blockDim.x / 32) ? shared[lane] : 0;

    if (wid == 0) val = warpReduceSum(val); // Final reduce within first warp

    return val;
}

__global__ void triplet_loss_kernel(
    const float* __restrict__ anchor,
    const float* __restrict__ positive,
    const float* __restrict__ negative,
    float* __restrict__ output,
    int features,
    float margin,
    float eps) {

    // Each block handles one sample in the batch
    int batch_idx = blockIdx.x;

    // Vectorized loading (float4) for higher memory bandwidth
    const float4* a_ptr = reinterpret_cast<const float4*>(anchor + batch_idx * features);
    const float4* p_ptr = reinterpret_cast<const float4*>(positive + batch_idx * features);
    const float4* n_ptr = reinterpret_cast<const float4*>(negative + batch_idx * features);

    float sum_p = 0.0f;
    float sum_n = 0.0f;

    // Process 4 elements per thread per iteration
    int vec_features = features / 4;

    for (int i = threadIdx.x; i < vec_features; i += blockDim.x) {
        float4 a = a_ptr[i];
        float4 p = p_ptr[i];
        float4 n = n_ptr[i];

        float4 dp, dn;
        dp.x = a.x - p.x; dp.y = a.y - p.y; dp.z = a.z - p.z; dp.w = a.w - p.w;
        dn.x = a.x - n.x; dn.y = a.y - n.y; dn.z = a.z - n.z; dn.w = a.w - n.w;

        sum_p += dp.x*dp.x + dp.y*dp.y + dp.z*dp.z + dp.w*dp.w;
        sum_n += dn.x*dn.x + dn.y*dn.y + dn.z*dn.z + dn.w*dn.w;
    }

    // Reduce sums within the block
    sum_p = blockReduceSum(sum_p);
    __syncthreads(); // Synchronize before reusing shared memory
