    __shared__ float s_sum[4][2];
    __shared__ float s_sum_sq[4][2];

    int warpId = tid / 32;
    int laneId = tid % 32;

    if (laneId == 0) {
        #pragma unroll
        for(int i=0; i<4; ++i) {
            s_sum[i][warpId] = l_sum[i];
            s_sum_sq[i][warpId] = l_sum_sq[i];
        }
    }
    __syncthreads();

    // Compute global mean/std on thread 0 and broadcast via shared memory
    if (tid == 0) {
        #pragma unroll
        for(int i=0; i<4; ++i) {
            float total_sum = s_sum[i][0] + s_sum[i][1];
            float total_sum_sq = s_sum_sq[i][0] + s_sum_sq[i][1];
            float mu = total_sum / 64.0f;
            float sigma2 = (total_sum_sq / 64.0f) - (mu * mu);
