cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void add_layernorm_kernel(const float* input, float* output, float sum_weight, const float* gamma, const float* beta, int W, int total_rows) {
    int row_idx = blockIdx.x;
    if (row_idx >= total_rows) return;

    const float* row_input = input + row_idx * W;
    float* row_output = output + row_idx * W;

    extern __shared__ float s_mem[];
    float* s_sum = s_mem;

    // Phase 1: Compute Mean
    float sum = 0.0f;
    for (int i = threadIdx.x; i < W; i += blockDim.x) {
        sum += row_input[i] + sum_weight;
    }
    s_sum[threadIdx.x] = sum;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
        __syncthreads();
    }
    float mean = s_sum[0] / W;
    __syncthreads();

    // Phase 2: Compute Variance
    float var_sum = 0.0f;
    for (int i = threadIdx.x; i < W; i += blockDim.x) {
        float val = row_input[i] + sum_weight;
        float diff = val - mean;
        var_sum += diff * diff;
    }
    s_sum[threadIdx.x] = var_sum;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
        __syncthreads();
    }
    float var = s_sum[0] / W;
    float inv_std = rsqrtf(var + 1e-5f);

    // Phase 3: Normalize and scale
    for (int i = threadIdx.x; i < W; i += blockDim.x) {
        float val = row_input[i] + sum_weight;
        row_output[i] = (val - mean) * inv_std * gamma[i] + beta[i];
    }
}

__global__ void avgpool3d_gelu_kernel(const float* input, float* output, int N, int C, int D, int H, int W, int D_out, int H_out, int W_out) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * D_out * H_out * W_out;
    if (idx >= total_elements) return;

    int w_o = idx % W_out;
    int h_o = (idx / W_out) % H_out;
    int d_o = (idx / (W_out * H_out)) % D_out;
    int c = (idx / (W_out * H_out * D_out)) % C;
    int n = idx / (W_out * H_out * D_out * C);

    int d_in = d_o * 2;
    int h_in = h_o * 2;
    int w_in = w_o * 2;

    float sum = 0.0f;
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            for (int k = 0; k < 2; ++k) {
                int input_idx = ((((n * C + c) * D + (d_in + i)) * H + (h_in + j)) * W + (w_in + k));
                sum += input[input_idx];
            }
        }
    }
    float avg = sum / 8.0f;

    // GELU activation: 0.5 * x * (1 + erf(x / sqrt(2)))
    output[idx] = 0.5f * avg * (1.0f + erff(avg * 0.70710678118f));
