    for (int i = threadIdx.x; i < items_per_batch; i += blockDim.x) {
        int c = i / (Do * Ho * Wo);
        int rem = i % (Do * Ho * Wo);
        int d = rem / (Ho * Wo);
        int rem2 = rem % (Ho * Wo);
        int h = rem2 / Wo;
        int w = rem2 % Wo;

        float max_val = -1e38f; 
