# This kernel performs the following operations in a single pass:
# 1. Reads 2x2 input window (corresponding to MaxPool kernel=2, stride=2)
# 2. Applies Batch Normalization (using inference statistics)
# 3. Computes Max of the 2x2 window
# 4. Applies Tanh activation (Optimized: Tanh(Max(x)) == Max(Tanh(x)))
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_bn_tanh_pool_kernel(
    const float* __restrict__ input,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H, int W,
    float epsilon) {

    // Output dimensions (MaxPool stride 2, kernel 2)
    int H_out = H / 2;
    int W_out = W / 2;
    int total_elements = N * C * H_out * W_out;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_elements) return;

    // Map linear index to (n, c, h_out, w_out)
    // Layout: N, C, H_out, W_out
    int w_out_idx = idx % W_out;
    int tmp = idx / W_out;
    int h_out_idx = tmp % H_out;
    tmp = tmp / H_out;
    int c_idx = tmp % C;
    int n_idx = tmp / C;

    // Load BN parameters for this channel
    float m = mean[c_idx];
    float v = var[c_idx];
    float w = weight[c_idx];
    float b = bias[c_idx];

    // Calculate fused scale and shift for BN
    // y = (x - mean) / sqrt(var + eps) * weight + bias
    // y = x * (weight * rsqrt(var + eps)) + (bias - mean * weight * rsqrt(var + eps))
    float inv_std = rsqrtf(v + epsilon);
    float scale = w * inv_std;
    float shift = b - m * scale;

    // Calculate input starting coordinates (stride 2)
    int h_in_start = h_out_idx * 2;
    int w_in_start = w_out_idx * 2;

    int input_channel_offset = n_idx * (C * H * W) + c_idx * (H * W);

    float max_val = -1e38f; // Initialize with a very small number

    // Fused Loop: Apply BN, then find Max
    #pragma unroll
    for (int i = 0; i < 2; ++i) {
        #pragma unroll
        for (int j = 0; j < 2; ++j) {
            int h_in = h_in_start + i;
            int w_in = w_in_start + j;

            // Assuming valid input sizes divisible by 2 for simplicity as per problem constraints
            int input_idx = input_channel_offset + h_in * W + w_in;
            float val = input[input_idx];

            // Apply BN
            val = val * scale + shift;

            // Max reduction
            if (val > max_val) {
                max_val = val;
            }
        }
    }

    // Apply Tanh to the max value
    // Optimization: Max(Tanh(x)) is equivalent to Tanh(Max(x)) because Tanh is monotonically increasing.
    // This saves 3 Tanh calls per output pixel.
    output[idx] = tanhf(max_val);
}

