    int oh = blockIdx.y * blockDim.y + threadIdx.y;
    int nc = blockIdx.z;

    if (ow < W_out && oh < H_out && nc < N * C) {
        int c = nc % C;

        float m = mean[c];
        float v = var[c];
        float w_param = weight[c];
        float b_param = bias[c];
        float inv_std = rsqrtf(v + eps);

        auto bn_tanh = [&](float val) {
            return tanhf((val - m) * inv_std * w_param + b_param);
