#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Kernel 1: Fused Mean Pooling (Depth) + Bias Addition
// Input X: (B, C, D, H, W)
// Bias: (C) broadcasted
// Output Y: (B, C, 1, H, W)
__global__ void mean_bias_kernel(const float* __restrict__ x, const float* __restrict__ bias, float* __restrict__ y, 
                                 int B, int C, int D, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * C * H * W;

    if (idx < total) {
        // Decode index to (b, c, h, w)
        // Treated output layout as (B, C, H, W) for indexing convenience
        int w = idx % W;
        int tmp = idx / W;
        int h = tmp % H;
        tmp = tmp / H;
        int c = tmp % C;
        int b = tmp / C;

        // Calculate base offset in Input X corresponding to (b, c, 0, h, w)
        // X Strides: C*D*H*W, D*H*W, H*W, W, 1
        long long x_offset = (long long)b * (C*D*H*W) + (long long)c * (D*H*W) + (long long)h * W + w;

        // Stride along Depth dimension
        int stride_d = H * W;

        float sum = 0.0f;
        for (int d = 0; d < D; ++d) {
            sum += x[x_offset + d * stride_d];
        }

        // Write to Output Y
        // Y effectively flat here, idx maps 1-to-1
        y[idx] = (sum / (float)D) + bias[c];
    }
}

// Kernel 2: Fused Softmax + Tanh + Scale
// Input/Output Data: (B, C, 1, H, W)
// Operations: Softmax(dim=1), Tanh, Scale
// Parallelism: Over spatial dimensions (B, H, W), looping over C inside thread
__global__ void softmax_tanh_scale_kernel(float* __restrict__ data, int B, int C, int H, int W, float scaling_factor) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * H * W;

    if (idx < total) {
        // Decode index to (b, h, w)
        int w = idx % W;
        int tmp = idx / W;
        int h = tmp % H;
        int b = tmp / H;

        // The data is contiguous in W, but we need to iterate over C.
        // Data layout: (B, C, H, W) (squeezed D)
        // Strides: C*H*W, H*W, W, 1

        // Base pointer offset for the column (b, :, h, w)
        long long col_offset = (long long)b * (C*H*W) + (long long)h * W + w;
        int stride_c = H * W;

        // Online Softmax (Single pass for Max and Sum of Exps)
        float m = -1e30f; // -infinity
        float s = 0.0f;

        for (int c = 0; c < C; ++c) {
            float val = data[col_offset + c * stride_c];
            float m_prev = m;
            if (val > m) {
                m = val;
            }
            // Welford-like update for sum of exps
            s = s * expf(m_prev - m) + expf(val - m);
        }

        // Apply Softmax normalization, Tanh, and Scaling
        float inv_s = 1.0f / s;
        for (int c = 0; c < C; ++c) {
            long long addr = col_offset + c * stride_c;
            float val = data[addr];
            float softmax_val = expf(val - m) * inv_s;
