#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_post_conv_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int B, int C, int D, int H, int W,
    float scaling_factor) {

    int p = threadIdx.y;
    int c = threadIdx.x;
    int hw = blockIdx.x * blockDim.y + p;
    int b = blockIdx.y;

    extern __shared__ float shared_data[];
    float* pixel_data = &shared_data[p * C];

    bool active = (hw < H * W && b < B && c < C);

    if (active) {
        float sum = 0;
        // 1. Mean pool over depth (D) dimension
        // input layout: (B, C, D, H, W)
        // index = b*C*D*H*W + c*D*H*W + d*H*W + hw
        int base_idx = ((b * C + c) * D) * H * W + hw;
        int stride = H * W;
        for (int d = 0; d < D; ++d) {
            sum += input[base_idx + d * stride];
        }
        // 2. Addition (bias)
        pixel_data[c] = (sum / (float)D) + bias[c];
    }

    __syncthreads();

    if (active) {
        float val = pixel_data[c];

        // 3. Softmax over channel (C) dimension
        float max_val = pixel_data[0];
        for (int i = 1; i < C; ++i) {
            if (pixel_data[i] > max_val) max_val = pixel_data[i];
