# Define the custom CUDA kernel for Fused GEMV and Scaling
# This kernel performs Matrix-Vector multiplication followed by a scalar scaling.
# Operation: out[i] = scale * sum_j(mat[i, j] * vec[j])
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void fused_gemv_scale_kernel(
    const scalar_t* __restrict__ mat,
    const scalar_t* __restrict__ vec,
    scalar_t* __restrict__ out,
    const float scale,
    const int M,
    const int N) {

    // Each block processes one row of the matrix 'mat'
    int row = blockIdx.x;
    if (row >= M) return;

    scalar_t sum = 0;

    // Grid-stride loop to accumulate dot product for the row
    for (int col = threadIdx.x; col < N; col += blockDim.x) {
        sum += mat[row * N + col] * vec[col];
    }

    // Shared memory for block reduction
    extern __shared__ char sdata[];
    scalar_t* s_sum = reinterpret_cast<scalar_t*>(sdata);

    int tid = threadIdx.x;
    s_sum[tid] = sum;
    __syncthreads();

    // Parallel reduction within the block
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            s_sum[tid] += s_sum[tid + s];
        }
        __syncthreads();
    }

    // Write result to global memory
    if (tid == 0) {
        out[row] = s_sum[0] * scale;
    }
}

