    auto N = mat.size(1);

    auto out = torch::empty({M, 1}, mat.options());

    const int block_size = 256;
    const int grid_size = M;
    int shared_mem_size = block_size * mat.element_size();

    AT_DISPATCH_FLOATING_TYPES(mat.scalar_type(), "fused_gemv_scale_cuda", ([&] {
        fused_gemv_scale_kernel<scalar_t><<<grid_size, block_size, shared_mem_size>>>(
            mat.data_ptr<scalar_t>(),
            vec.data_ptr<scalar_t>(),
            out.data_ptr<scalar_t>(),
            scale,
            M,
            N);
    }));

    return out;
}
