import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# CUDA source for the optimized operator
# The original architecture does: O = sum( (X @ W.T) / 2, dim=1 ) * scaling_factor
# This can be simplified to: O = (X @ col_sum(W)) * (scaling_factor / 2)
# This changes complexity from O(M*N*K) to O((M+N)*K).
fused_op_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Kernel to sum columns of W: W (N, K) -> V (K)
// Coalesced memory access as threads in a warp read contiguous W[j, k] for fixed j.
__global__ void col_sum_kernel(const float* W, float* V, int N, int K) {
    int k = blockIdx.x * blockDim.x + threadIdx.x;
    if (k < K) {
        float sum = 0.0f;
        for (int j = 0; j < N; ++j) {
            sum += W[j * K + k];
        }
        V[k] = sum;
    }
}

// Kernel to compute row-wise dot product of X and V: X (M, K), V (K) -> O (M, 1)
// Uses shared memory reduction for high performance and coalesced access.
__global__ void row_dot_kernel(const float* X, const float* V, float* O, int M, int K, float factor) {
    extern __shared__ float sdata[];
    int i = blockIdx.x; // Row index
    int tid = threadIdx.x;

    float sum = 0.0f;
    for (int k = tid; k < K; k += blockDim.x) {
        sum += X[i * K + k] * V[k];
    }
    sdata[tid] = sum;
    __syncthreads();

    // Parallel reduction in shared memory (block size must be power of 2)
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        O[i] = sdata[0] * factor;
    }
}

torch::Tensor fused_model_forward(torch::Tensor x, torch::Tensor weight, float scaling_factor) {
    const int M = x.size(0);
    const int K = x.size(1);
    const int N = weight.size(0);

    auto options = torch::TensorOptions().device(x.device()).dtype(x.dtype());
    auto V = torch::empty({K}, options);
    auto O = torch::empty({M, 1}, options);

    const int block_size_col = 256;
    const int num_blocks_K = (K + block_size_col - 1) / block_size_col;
    col_sum_kernel<<<num_blocks_K, block_size_col>>>(
        weight.data_ptr<float>(), V.data_ptr<float>(), N, K);

    const int block_size_row = 256;
    const int num_blocks_M = M;
    row_dot_kernel<<<num_blocks_M, block_size_row, block_size_row * sizeof(float)>>>(
        x.data_ptr<float>(), V.data_ptr<float>(), O.data_ptr<float>(), M, K, scaling_factor / 2.0f);

    return O;
}
"""

