__global__ void fused_instance_norm_div_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int hw_size,
    float epsilon,
    float divide_by) {

    // Each block processes one instance (one channel of one batch item)
    // Grid dimension x corresponds to N * C
    int instance_idx = blockIdx.x;

    // Calculate offsets for this instance
    int offset = instance_idx * hw_size;
    const float* input_ptr = input + offset;
    float* output_ptr = output + offset;

    // 1. Compute Sum and Sum of Squares
    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int i = threadIdx.x; i < hw_size; i += blockDim.x) {
        float val = input_ptr[i];
        sum += val;
        sum_sq += val * val;
    }

    // 2. Block Reduction using Shared Memory
    // Allocate shared memory for partial sums: 2 * blockDim.x * sizeof(float)
    extern __shared__ float sdata[];
    float* s_sum = sdata;
    float* s_sum_sq = sdata + blockDim.x;

    s_sum[threadIdx.x] = sum;
    s_sum_sq[threadIdx.x] = sum_sq;

    __syncthreads();

    // Standard tree reduction
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + stride];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + stride];
        }
        __syncthreads();
    }

    // 3. Compute Mean, Variance, and Scaling Factor
    // Use shared memory variables to broadcast results to all threads in the block
    __shared__ float mean;
    __shared__ float scale;

    if (threadIdx.x == 0) {
        mean = s_sum[0] / hw_size;
        float mean_sq = s_sum_sq[0] / hw_size;
        float var = mean_sq - mean * mean;

        // Clamp variance to 0 to avoid numerical issues
        if (var < 0.0f) var = 0.0f;

        // Calculate the fused scaling factor:
        // Standard Instance Norm: (x - mean) / sqrt(var + eps)
        // Then divide by constant: / divide_by
        // Combined: (x - mean) * [1 / (sqrt(var + eps) * divide_by)]
        scale = rsqrtf(var + epsilon) / divide_by;
    }
    __syncthreads();

    // 4. Normalize and Write Output
    float m = mean;
    float s = scale;

    for (int i = threadIdx.x; i < hw_size; i += blockDim.x) {
        output_ptr[i] = (input_ptr[i] - m) * s;
    }
}

