        // W is stored row-major: W[j, k] = W[j * K + k]
        // Coalescing: Adjacent threads (k, k+1) access W[j*K+k], W[j*K+k+1] which are adjacent.
        for (int j = 0; j < M; ++j) {
            sum += W[j * K + k];
