    int g = blockIdx.x; 

    int channels_per_group = C / G;
    int spatial_size = H * W;
    int num_elements = channels_per_group * spatial_size; // Total elements to reduce per group per batch

    float sum = 0.0f;
    float sum_sq = 0.0f;

    int tid = threadIdx.x;
    int stride = blockDim.x;

    // Calculate memory offset
    // Data for (n, g) is contiguous because channels per group are contiguous and spatial dims are contiguous
    // offset = n * C * H * W + (g * channels_per_group) * H * W

    int start_channel = g * channels_per_group;
    long long offset = (long long)n * C * spatial_size + (long long)start_channel * spatial_size;

