    int group_idx = blockIdx.x; 
    if (group_idx >= N * G) return;

    int n = group_idx / G;
    int g = group_idx % G;
    int channels_per_group = C / G;
    int hw = H * W;
    int elements_per_group = channels_per_group * hw;
    int group_offset = n * C * hw + g * channels_per_group * hw;

    // Part 1: Compute Mean and Variance of GELU(input)
    float sum = 0.0f;
    float sq_sum = 0.0f;

    for (int i = threadIdx.x; i < elements_per_group; i += blockDim.x) {
        float val = input[group_offset + i];
        float g_val = gelu_func(val);
        sum += g_val;
        sq_sum += g_val * g_val;
    }

    // Block-level reduction using shared memory
    extern __shared__ float shared_mem[];
    float* s_sum = shared_mem;
    float* s_sq_sum = &shared_mem[blockDim.x];

