#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

__device__ inline float sigmoid_f(float x) {
    return 1.0f / (1.0f + expf(-x));
}

// Warp reduction for shared memory
__device__ void warpReduce(volatile float* sdata, int tid) {
    sdata[tid] += sdata[tid + 32];
    sdata[tid] += sdata[tid + 16];
    sdata[tid] += sdata[tid + 8];
    sdata[tid] += sdata[tid + 4];
    sdata[tid] += sdata[tid + 2];
    sdata[tid] += sdata[tid + 1];
}

__global__ void fused_gn_kernel(
    const float* __restrict__ x,
    const float* __restrict__ bias,
    const float* __restrict__ scale,
    const float* __restrict__ gn_weight,
    const float* __restrict__ gn_bias,
    float* __restrict__ out,
    int N, int C, int H, int W, int G,
    float eps) 
{
    // Grid structure: x=N (batch), y=G (groups)
    int n = blockIdx.x;
    int g = blockIdx.y;
    int tid = threadIdx.x;

    // Calculate dimensions
    int C_per_G = C / G;
    int HW = H * W;
    int elems_per_group = C_per_G * HW;

    // Offsets
    // Memory is NCHW. Group data is contiguous because channels are contiguous.
    // Offset for batch n, group g
    int group_offset = n * (C * HW) + g * elems_per_group;

    const float* x_ptr = x + group_offset;
    float* out_ptr = out + group_offset;

