    // Stride by blockDim.x to cover all pixels and channels in this group
    for (int i = tid; i < elems_per_group; i += blockDim.x) {
        float val = x_ptr[i];

        // Determine channel index for bias/scale lookup
        // i is offset within group data (C_per_G * H * W)
        int c_local = i / HW; // Integer division, HW is 256*256
        int c_global = g * C_per_G + c_local;

        // Fused Operations: (x + bias) * scale -> sigmoid
        val = (val + bias[c_global]) * scale[c_global];
        val = sigmoid_f(val);

        local_sum += val;
        local_sq_sum += val * val;
