        warpReduce(sdata_sum, tid);
        warpReduce(sdata_sq, tid);
    }

    // Compute Mean and InvStdDev
    __shared__ float mean;
    __shared__ float inv_std;

    if (tid == 0) {
        float sum = sdata_sum[0];
        float sq_sum = sdata_sq[0];
        mean = sum / elems_per_group;
        float var = (sq_sum / elems_per_group) - (mean * mean);
