        inv_std = rsqrtf(var + eps);
    }
    __syncthreads();

    float m = mean;
    float is = inv_std;

    // Second Pass: Re-compute and Normalize
    for (int i = tid; i < elems_per_group; i += blockDim.x) {
        float val = x_ptr[i];

        int c_local = i / HW;
        int c_global = g * C_per_G + c_local;

