import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel source code
# We fuse the element-wise scaling, residual addition (doubling), clamping,
# LogSumExp reduction, and the final element-wise Mish post-processing into a single kernel.
# This drastically reduces global memory reads/writes compared to executing operations sequentially.

fused_cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>
#include <cfloat>

// Helper for softplus: log(1 + exp(x))
__device__ __forceinline__ float softplus_f(float x) {
    // For large x, softplus(x) approx x. Threshold prevents overflow in expf.
    if (x > 20.0f) return x;
    return log1pf(expf(x));
}

// Helper for Mish: x * tanh(softplus(x))
__device__ __forceinline__ float mish_f(float x) {
    return x * tanhf(softplus_f(x));
}

__global__ void fused_reduction_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int hidden_size,
    float scale,
    float clamp_min,
    float clamp_max) {

    // Grid configuration: One block per batch row (dim 0)
    int row_idx = blockIdx.x;
    int tid = threadIdx.x;

    // Pointer to the start of the current row
    const float* row_ptr = input + row_idx * hidden_size;

    // Shared memory for block reduction
    extern __shared__ float sdata[];

    // ---------------------------------------------------------------
    // Step 1: Find Row Max (necessary for numerical stability of LSE)
    // ---------------------------------------------------------------
    float local_max = -FLT_MAX;

    // Grid-stride loop (though usually one block per row covers it)
    for (int i = tid; i < hidden_size; i += blockDim.x) {
        float val = row_ptr[i];

        // Fused Element-wise Ops:
        // x = x * scale
        // x = x + x  --> effectively x * 2.0
        val = val * scale * 2.0f;

        // Clamp
        val = fminf(fmaxf(val, clamp_min), clamp_max);

        if (val > local_max) {
            local_max = val;
        }
    }

    // Load into shared memory
    sdata[tid] = local_max;
    __syncthreads();

    // Parallel Reduction for Max
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] = fmaxf(sdata[tid], sdata[tid + s]);
        }
        __syncthreads();
    }
    float row_max = sdata[0];

    // ---------------------------------------------------------------
    // Step 2: Compute Sum of Exponentials: sum(exp(x_i - row_max))
    // ---------------------------------------------------------------
    float local_sum = 0.0f;

    for (int i = tid; i < hidden_size; i += blockDim.x) {
        float val = row_ptr[i];

        // Recompute ops to save memory bandwidth (compute bound is better than memory bound)
        val = val * scale * 2.0f;
        val = fminf(fmaxf(val, clamp_min), clamp_max);

        local_sum += expf(val - row_max);
    }

    sdata[tid] = local_sum;
    __syncthreads();

    // Parallel Reduction for Sum
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }
    float row_sum = sdata[0];

    // ---------------------------------------------------------------
    // Step 3: Final LogSumExp and Post-Processing (x * Mish(x))
    // ---------------------------------------------------------------
    if (tid == 0) {
        // LogSumExp
        float lse = row_max + logf(row_sum);

        // Mish activation on the result of LSE
        float m = mish_f(lse);

        // Final multiplication: x * mish(x) -> lse * m
        output[row_idx] = lse * m;
    }
}

