#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Mish activation function: x * tanh(softplus(x))
__device__ __forceinline__ float mish_func(float x) {
    if (x > 20.0f) return x;
    if (x < -20.0f) return 0.0f;
    return x * tanhf(log1pf(expf(x)));
}

// Data structure to store intermediate LogSumExp reduction results
struct LSEData {
    float max_val;
    float sum_exp;
};

// Helper function to combine two LSE reduction results
__device__ __forceinline__ LSEData combine_lse(LSEData a, LSEData b) {
    if (a.max_val > b.max_val) {
        return {a.max_val, a.sum_exp + b.sum_exp * expf(b.max_val - a.max_val)};
    } else {
        return {b.max_val, b.sum_exp + a.sum_exp * expf(a.max_val - b.max_val)};
    }
}

// Fused kernel: Scaling -> Residual-add -> Clamp -> LogSumExp (dim=1) -> Mish-scale
__global__ void fused_lse_mish_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int hidden_size,
    float combined_scale,
    float clamp_min,
    float clamp_max) {

    int row = blockIdx.x;
    if (row >= batch_size) return;

    // Single-pass online LogSumExp per thread
    LSEData thread_data = {-1e38f, 0.0f};

    for (int col = threadIdx.x; col < hidden_size; col += blockDim.x) {
        float val = input[row * hidden_size + col];

        // Combined Scale and Residual-add (x * scale + x * scale = x * scale * 2)
        val = val * combined_scale;

        // Clamp
        if (val < clamp_min) val = clamp_min;
        if (val > clamp_max) val = clamp_max;

        // Update online LSE
        if (val > thread_data.max_val) {
            thread_data.sum_exp = thread_data.sum_exp * expf(thread_data.max_val - val) + 1.0f;
            thread_data.max_val = val;
        } else {
            thread_data.sum_exp += expf(val - thread_data.max_val);
        }
    }

    // Tree reduction within the block
    __shared__ LSEData sdata[256];
    int tid = threadIdx.x;
    sdata[tid] = thread_data;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
