# This kernel avoids writing the intermediate large tensor (Output of GroupNorm) to global memory,
# saving significant memory bandwidth.
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define MAX_GROUPS 32

__global__ void fused_gn_mean_kernel(
    const float* __restrict__ input,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ output,
    int N,
    int C,
    int V,
    int num_groups,
    float epsilon) {

    // Block ID corresponds to batch index
    int n = blockIdx.x;
    if (n >= N) return;

    // Shared memory layout:
    // [0 ... num_groups-1]: group_sum (stores mean mu later)
    // [num_groups ... 2*num_groups-1]: group_sq_sum (stores rsigma later)
    // [2*num_groups ... ]: scratch for block reduction
    extern __shared__ float shared_mem[];
    float* group_sum = shared_mem;
    float* group_sq_sum = group_sum + num_groups;
    float* scratch = group_sq_sum + num_groups;

    int channels_per_group = C / num_groups;
    int tid = threadIdx.x;

    // Initialize shared memory for stats
    if (tid < num_groups) {
        group_sum[tid] = 0.0f;
        group_sq_sum[tid] = 0.0f;
    }
    __syncthreads();

    // Local accumulation registers for groups
    float local_stats_sum[MAX_GROUPS];
    float local_stats_sq_sum[MAX_GROUPS];

    #pragma unroll
    for (int i = 0; i < MAX_GROUPS; ++i) {
        local_stats_sum[i] = 0.0f;
        local_stats_sq_sum[i] = 0.0f;
    }

    int input_offset = n * C * V;

    // Pass 1: Accumulate sums and squared sums per group
    // Each thread processes a stride of spatial pixels for each channel
    for (int c = 0; c < C; ++c) {
        int g = c / channels_per_group;
        if (g >= MAX_GROUPS) continue; // Safety check

        float c_sum = 0.0f;
        float c_sq_sum = 0.0f;

        for (int v = tid; v < V; v += blockDim.x) {
            float val = input[input_offset + c * V + v];
            c_sum += val;
            c_sq_sum += val * val;
        }

        local_stats_sum[g] += c_sum;
        local_stats_sq_sum[g] += c_sq_sum;
    }

    // Reduce local stats to shared memory using atomicAdd
    // Since num_groups is small (e.g., 8), atomic contention is low compared to global memory benefit
    for (int g = 0; g < num_groups; ++g) {
        atomicAdd(&group_sum[g], local_stats_sum[g]);
        atomicAdd(&group_sq_sum[g], local_stats_sq_sum[g]);
    }

    __syncthreads();

    // Compute Mean (mu) and Inverse Standard Deviation (rsig) per group
    if (tid < num_groups) {
        float count = (float)(channels_per_group * V);
        float mu = group_sum[tid] / count;
        float var = (group_sq_sum[tid] / count) - (mu * mu);
        // Store back to shared memory
        group_sum[tid] = mu;
        group_sq_sum[tid] = rsqrtf(fmaxf(var, 0.0f) + epsilon);
    }
    __syncthreads();

    // Pass 2: Calculate normalized values and accumulate global sum
    // We do NOT write the normalized tensor to global memory, we only sum it.
    float local_total_sum = 0.0f;

    for (int c = 0; c < C; ++c) {
        int g = c / channels_per_group;
        float mu = group_sum[g];
        float rsig = group_sq_sum[g];
        float gam = gamma[c];
        float bet = beta[c];

        for (int v = tid; v < V; v += blockDim.x) {
            float val = input[input_offset + c * V + v];
            // Apply GroupNorm
            float norm = (val - mu) * rsig * gam + bet;
            // Accumulate for Mean
            local_total_sum += norm;
