    // Block-wide reduction for total sum using shared memory
    scratch[tid] = local_total_sum;
    __syncthreads();

    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            scratch[tid] += scratch[tid + s];
        }
        __syncthreads();
    }

    // Write result
    if (tid == 0) {
        // Global mean = sum / (C * V)
        float total_mean = scratch[0] / (float)(C * V);
        output[n] = total_mean;
    }
}

