import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Group Normalization and Mean reduction.
# The kernel computes per-channel sums and sum-of-squares, then uses these
# to calculate group statistics and final global mean reduction in a single pass 
# over the large 3D feature map to save memory bandwidth.
fused_gn_mean_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Step 1: Compute per-channel sums and sum-of-squares
__global__ void stats_kernel(const float* x, float* sums, float* sq_sums, int N, int C, int V) {
    int nc = blockIdx.x; // Block for each (batch_element, channel)
    if (nc >= N * C) return;

    float s = 0;
    float ss = 0;
    const float* ptr = x + nc * V;
    for (int i = threadIdx.x; i < V; i += blockDim.x) {
        float val = ptr[i];
        s += val;
        ss += val * val;
    }

    // Shared memory for block reduction
    extern __shared__ float shared_mem[];
    float* s_mem = shared_mem;
    float* ss_mem = shared_mem + blockDim.x;

    s_mem[threadIdx.x] = s;
    ss_mem[threadIdx.x] = ss;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_mem[threadIdx.x] += s_mem[threadIdx.x + stride];
            ss_mem[threadIdx.x] += ss_mem[threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        sums[nc] = s_mem[0];
        sq_sums[nc] = ss_mem[0];
    }
}

// Step 2: Compute GroupNorm and then the global mean reduction for each batch element
__global__ void final_reduction_kernel(
    const float* sums, const float* sq_sums,
    const float* gamma, const float* beta,
    float* out,
    int N, int C, int V, int G, float eps) {

    int n = blockIdx.x; // Each block handles one batch element
    if (n >= N) return;

    int channels_per_group = C / G;
    float total_sum_gn = 0;

    for (int g = 0; g < G; ++g) {
        // Compute group mean and variance
        float g_sum = 0;
        float g_sq_sum = 0;
        for (int i = 0; i < channels_per_group; ++i) {
            int c = g * channels_per_group + i;
            g_sum += sums[n * C + c];
            g_sq_sum += sq_sums[n * C + c];
        }

        float count = (float)channels_per_group * (float)V;
        float mu = g_sum / count;
        float var = (g_sq_sum / count) - (mu * mu);
        float inv_std = 1.0f / sqrtf(fmaxf(0.0f, var) + eps);

        // Sum up the GroupNorm contributions for this group to the global mean
        for (int i = 0; i < channels_per_group; ++i) {
            int c = g * channels_per_group + i;
            float c_sum = sums[n * C + c];
            float g_c = gamma[c];
            float b_c = beta[c];
            total_sum_gn += g_c * (c_sum - (float)V * mu) * inv_std + (float)V * b_c;
        }
    }

    // Final global mean for batch element n
    out[n] = total_sum_gn / (float)((long long)C * V);
}

torch::Tensor fused_gn_mean_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, int num_groups, float eps) {
    auto x_contig = x.contiguous();
    int N = x_contig.size(0);
    int C = x_contig.size(1);
    int V = x_contig.size(2) * x_contig.size(3) * x_contig.size(4);
    int G = num_groups;

    auto sums = torch::empty({N, C}, x_contig.options());
    auto sq_sums = torch::empty({N, C}, x_contig.options());
    auto out = torch::empty({N}, x_contig.options());

    int threads = 256;
    int blocks = N * C;
    size_t shared_size = 2 * threads * sizeof(float);
    stats_kernel<<<blocks, threads, shared_size>>>(x_contig.data_ptr<float>(), sums.data_ptr<float>(), sq_sums.data_ptr<float>(), N, C, V);

    final_reduction_kernel<<<N, 1>>>(sums.data_ptr<float>(), sq_sums.data_ptr<float>(), 
                                     weight.data_ptr<float>(), bias.data_ptr<float>(), 
                                     out.data_ptr<float>(), N, C, V, G, eps);

    return out.unsqueeze(1);
}
"""

