min_softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void min_softmax_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int D1, int D2, int D3,
    int min_dim) 
{
    int s1_dim, s2_dim, r_dim;
    // Map dimensions based on which spatial dimension is being reduced.
    if (min_dim == 2) {
        r_dim = D1; s1_dim = D2; s2_dim = D3;
    } else if (min_dim == 3) {
        r_dim = D2; s1_dim = D1; s2_dim = D3;
    } else if (min_dim == 4) {
        r_dim = D3; s1_dim = D1; s2_dim = D2;
    } else {
        return; 
    }

    int spatial_size = N * s1_dim * s2_dim;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= spatial_size) return;

    // Decode thread index to (batch, spatial_1, spatial_2) coordinates
    int s2 = idx % s2_dim;
    int s1 = (idx / s2_dim) % s1_dim;
    int n = idx / (s1_dim * s2_dim);

    // Buffer to store values for softmax (up to 128 channels). 
    // Small buffer ensures it stays in registers for the typical case C=24.
    float local_mins[128]; 
    if (C > 128) return;

    // 1. Perform Reduction: Find minimum value along the specified reduction dimension (dim) for each channel (C).
    for (int c = 0; c < C; ++c) {
        float min_val = 1e38f;
        for (int r = 0; r < r_dim; ++r) {
            int in_idx;
            if (min_dim == 2) 
                in_idx = (((n * C + c) * D1 + r) * D2 + s1) * D3 + s2;
            else if (min_dim == 3)
                in_idx = (((n * C + c) * D1 + s1) * D2 + r) * D3 + s2;
            else // min_dim == 4
                in_idx = (((n * C + c) * D1 + s1) * D2 + s2) * D3 + r;

            float val = input[in_idx];
            if (val < min_val) min_val = val;
        }
        local_mins[c] = min_val;
    }

    // 2. Perform Softmax along the Channel Dimension.
    // Find max for numerical stability.
    float max_m = local_mins[0];
    for (int c = 1; c < C; ++c) {
        if (local_mins[c] > max_m) max_m = local_mins[c];
    }

    // Calculate sum of exponentials.
    float sum_exp = 0.0f;
    for (int c = 0; c < C; ++c) {
        local_mins[c] = expf(local_mins[c] - max_m);
        sum_exp += local_mins[c];
    }

    // Normalize and write results to global memory.
    float inv_sum = 1.0f / sum_exp;
    for (int c = 0; c < C; ++c) {
        int out_idx = ((n * C + c) * s1_dim + s1) * s2_dim + s2;
        output[out_idx] = local_mins[c] * inv_sum;
    }
