import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused HardSwish + Spatial Statistics
# This kernel computes the sum and sum-of-squares of the activation over spatial dimensions
# after applying HardSwish on the fly. This avoids writing the large activated tensor to memory.
fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

__device__ __forceinline__ float hardswish_func(float x) {
    if (x <= -3.0f) {
        return 0.0f;
    } else if (x >= 3.0f) {
        return x;
    } else {
        return x * (x + 3.0f) / 6.0f;
    }
}

__global__ void fused_stats_kernel(
    const float* __restrict__ input,
    float* __restrict__ sums,
    float* __restrict__ sq_sums,
    int spatial_size,
    int total_channels
) {
    // gridDim.x = B * C
    // blockDim.x = 256
    int bc_idx = blockIdx.x; 
    if (bc_idx >= total_channels) return;

    int offset = bc_idx * spatial_size;

    float local_sum = 0.0f;
    float local_sq_sum = 0.0f;

    // Grid-stride loop over spatial dimensions (D, H, W)
    for (int i = threadIdx.x; i < spatial_size; i += blockDim.x) {
        float val = input[offset + i];
        val = hardswish_func(val); // Fused activation

        local_sum += val;
        local_sq_sum += val * val;
    }

    // Block reduction using shared memory
    extern __shared__ float sdata[];
    float* s_sum = sdata;
    float* s_sq_sum = sdata + blockDim.x;

    s_sum[threadIdx.x] = local_sum;
    s_sq_sum[threadIdx.x] = local_sq_sum;
    __syncthreads();

    // Standard reduction in shared memory
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sq_sum[threadIdx.x] += s_sq_sum[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Write result for this channel to global memory
    if (threadIdx.x == 0) {
        sums[bc_idx] = s_sum[0];
        sq_sums[bc_idx] = s_sq_sum[0];
    }
}

std::vector<torch::Tensor> fused_forward_cuda(torch::Tensor input) {
