    int total_channels = batch * channels;

    auto options = input.options();
    auto sums = torch::empty({batch, channels}, options);
    auto sq_sums = torch::empty({batch, channels}, options);

    const int threads = 256;
    const int blocks = total_channels;
    // Shared memory size: 2 float arrays of size 'threads'
    int shared_mem = threads * 2 * sizeof(float);

    fused_stats_kernel<<<blocks, threads, shared_mem>>>(
        input.data_ptr<float>(),
        sums.data_ptr<float>(),
        sq_sums.data_ptr<float>(),
        spatial_size,
        total_channels
    );

    return {sums, sq_sums};
