class ModelNew(nn.Module):
    """
    Optimized Model that performs:
    1. Conv3D (Standard cuDNN)
    2. Fused HardSwish + GroupNorm Statistics + Global Average Pooling

    Optimization Strategy:
    - Conv3D is compute-bound and left to PyTorch/cuDNN.
    - HardSwish, GroupNorm, and MeanPooling are memory-bound.
    - Instead of writing the large (B, C, D, H, W) tensor after HardSwish 
      and again after GroupNorm, we compute the necessary statistics (spatial sums 
      and squared sums) in a single fused kernel.
    - The GroupNorm logic and final scaling are applied on the reduced (B, C) tensors,
      drastically reducing global memory traffic.
    """
    def __init__(self, in_channels, out_channels, kernel_size, num_groups=4, bias=True):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size, bias=bias)
        self.num_groups = num_groups
        self.out_channels = out_channels
        self.eps = 1e-5

        # GroupNorm parameters
        self.gn_weight = nn.Parameter(torch.ones(out_channels))
        self.gn_bias = nn.Parameter(torch.zeros(out_channels))

        self.fused_ops = fused_ops

    def forward(self, x):
        # 1. Conv3D
        x = self.conv(x)

        # 2. Fused Kernel: HardSwish + Spatial Reduction
        # Returns spatial sums and squared sums of activated data: (B, C)
        sums, sq_sums = self.fused_ops.fused_forward_cuda(x)

        # 3. Compute GroupNorm statistics and Mean Pooling result
        B, C = sums.shape
        G = self.num_groups
        C_per_G = C // G

        # Spatial size (D*H*W)
        spatial_size = x.numel() // (B * C)

        # Reshape to separate groups: (B, G, C/G)
        sums_g = sums.view(B, G, C_per_G)
        sq_sums_g = sq_sums.view(B, G, C_per_G)

        # Compute group sums and squared sums
        g_sum = sums_g.sum(dim=2, keepdim=True)        # (B, G, 1)
        g_sq_sum = sq_sums_g.sum(dim=2, keepdim=True)  # (B, G, 1)

        # Number of elements in a group (Spatial * Channels_per_Group)
        N_group = spatial_size * C_per_G

        # Mean and Variance per group
        mu_g = g_sum / N_group
        var_g = (g_sq_sum / N_group) - (mu_g * mu_g)
        std_g = torch.sqrt(var_g + self.eps)

        # Expand stats back to (B, C)
        mu_g = mu_g.expand(B, G, C_per_G).reshape(B, C)
        std_g = std_g.expand(B, G, C_per_G).reshape(B, C)

        # 4. Final Calculation
        # The target operation is Mean(GroupNorm(HardSwish(x))) over spatial dims.
        # Let y = GroupNorm(h), where h = HardSwish(x).
        # y = gamma * (h - mu_g) / std_g + beta
        # Mean(y) = gamma * (Mean(h) - mu_g) / std_g + beta
        # Mean(h) is simply sums / spatial_size

        mean_h = sums / spatial_size
        out = self.gn_weight * (mean_h - mu_g) / std_g + self.gn_bias

        return out

