import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused InstanceNorm + Add + Mul
# This kernel computes row-wise statistics (mean, var) and applies normalization,
# addition, and multiplication in a single pass over the data (after reduction).
cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_norm_add_mul_kernel(float* __restrict__ x, const float* __restrict__ y, int rows, int cols, float eps) {
    // Each block handles one row (batch item)
    int row = blockIdx.x;
    if (row >= rows) return;

    // Pointers to the current row
    float* x_row = x + row * cols;
    const float* y_row = y + row * cols;

    float local_sum = 0.0f;
    float local_sq_sum = 0.0f;

    // 1. Accumulate Sums (first pass)
    // Stride loop to handle columns > blockDim
    for (int i = threadIdx.x; i < cols; i += blockDim.x) {
        float val = x_row[i];
        local_sum += val;
        local_sq_sum += val * val;
    }

    // 2. Reduction within block
    // Shared memory for partial sums
    // 32 is max warps per block (1024 threads / 32)
    static __shared__ float s_sum[32]; 
    static __shared__ float s_sq_sum[32];

    unsigned int mask = 0xffffffff;

    // Warp reduction
    for (int offset = 16; offset > 0; offset /= 2) {
        local_sum += __shfl_down_sync(mask, local_sum, offset);
        local_sq_sum += __shfl_down_sync(mask, local_sq_sum, offset);
    }

    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    // Write warp results to shared memory
    if (lane == 0) {
        s_sum[wid] = local_sum;
        s_sq_sum[wid] = local_sq_sum;
    }
    __syncthreads();

    // Final reduction by the first warp
    if (wid == 0) {
        int num_warps = blockDim.x / 32;
        local_sum = (threadIdx.x < num_warps) ? s_sum[threadIdx.x] : 0.0f;
        local_sq_sum = (threadIdx.x < num_warps) ? s_sq_sum[threadIdx.x] : 0.0f;

        for (int offset = 16; offset > 0; offset /= 2) {
            local_sum += __shfl_down_sync(mask, local_sum, offset);
            local_sq_sum += __shfl_down_sync(mask, local_sq_sum, offset);
        }

        if (lane == 0) {
            s_sum[0] = local_sum;
            s_sq_sum[0] = local_sq_sum;
        }
    }
    __syncthreads();

    // Broadcast mean and var to all threads in block
    float mean = s_sum[0] / cols;
    // Var = E[x^2] - (E[x])^2
    float var = (s_sq_sum[0] / cols) - (mean * mean);
    // Calculate inverse standard deviation with epsilon
    float inv_std = rsqrtf(fmaxf(var, 0.0f) + eps);

    // 3. Apply transformation (second pass)
    for (int i = threadIdx.x; i < cols; i += blockDim.x) {
        float val = x_row[i];
        // Normalize
        val = (val - mean) * inv_std;
        // Residual Add
        float y_val = y_row[i];
        val = val + y_val;
        // Multiplication
        val = val * y_val;
        // Write back
        x_row[i] = val;
    }
}

