#include <cuda_runtime.h>
#include <cmath>

// Helper device function for Mish activation
// Mish(x) = x * tanh(ln(1 + e^x))
__device__ __forceinline__ float mish_activation(float x) {
    // Softplus: ln(1 + e^x). 
    // We use a threshold of 20.0f for numerical stability (avoiding overflow of expf).
    // For x > 20, ln(1 + e^x) is approximately x.
    float sp = (x > 20.0f) ? x : log1pf(expf(x));
    return x * tanhf(sp);
}

__global__ void fused_bias_mish_mish_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int size,
    int inner_dim) {

