from torch.utils.cpp_extension import load_inline

# --------------------------------------------------------------------------------
# Custom CUDA Kernel: Fused Scale + Batch Normalization
# --------------------------------------------------------------------------------
# This kernel performs the following operations in a single pass (fused):
# 1. Scaling: x = x * scale
# 2. Batch Normalization: y = (x - mean) / sqrt(var + eps) * gamma + beta
# 
# It handles both training (calculating batch stats) and inference (using running stats)
# modes, significantly reducing global memory read/write operations compared to 
# separate PyTorch operators.
# --------------------------------------------------------------------------------

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <typename T>
__device__ __forceinline__ T warpReduceSum(T val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__global__ void fused_scale_bn_kernel(
    const float* __restrict__ input,
    const float* __restrict__ scale,
    const float* __restrict__ bn_weight,
    const float* __restrict__ bn_bias,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    float* __restrict__ output,
    int N,
    int C,
    float momentum,
    float epsilon,
    bool training) {

    // Grid configuration: One block per channel (feature)
    int c = blockIdx.x;
    if (c >= C) return;

    int tid = threadIdx.x;

    // Load channel-specific parameters
    float s = scale[c];

    // ------------------------------------------------------------------
    // Phase 1: Statistics Calculation (Mean & Variance)
    // ------------------------------------------------------------------

    float sum = 0.0f;
    float sq_sum = 0.0f;

    // Grid-stride loop to handle N larger than block size
    for (int i = tid; i < N; i += blockDim.x) {
        float val = input[i * C + c] * s;
        sum += val;
        sq_sum += val * val;
    }

    // Reduce within warp
    sum = warpReduceSum(sum);
    sq_sum = warpReduceSum(sq_sum);

    // Reduce across warps using shared memory
    // Assuming blockDim.x <= 1024 (max 32 warps)
    static __shared__ float shared_sum[32];
    static __shared__ float shared_sq_sum[32];

    int warpId = tid / 32;
    int laneId = tid % 32;

    if (laneId == 0) {
        shared_sum[warpId] = sum;
        shared_sq_sum[warpId] = sq_sum;
    }
    __syncthreads();

    // First warp reduces the results from shared memory
    float total_sum = 0.0f;
    float total_sq_sum = 0.0f;

    int num_warps = blockDim.x / 32;
    if (warpId == 0) {
        if (laneId < num_warps) {
            total_sum = shared_sum[laneId];
            total_sq_sum = shared_sq_sum[laneId];
        }
        total_sum = warpReduceSum(total_sum);
        total_sq_sum = warpReduceSum(total_sq_sum);
    }

    // Calculate final mean and inverse std dev
    __shared__ float s_mu;
    __shared__ float s_inv_std;

    if (tid == 0) {
        float mu, var_val;
        if (training) {
            mu = total_sum / N;
            // Biased variance for normalization
            var_val = (total_sq_sum / N) - (mu * mu);

            // Unbiased variance for running stats update
            if (N > 1) {
                float unbiased_var = (total_sq_sum - (total_sum * total_sum) / N) / (N - 1);
                // Update global running stats
                float rm = running_mean[c];
                float rv = running_var[c];
                running_mean[c] = (1.0f - momentum) * rm + momentum * mu;
                running_var[c] = (1.0f - momentum) * rv + momentum * unbiased_var;
            }
        } else {
            // Inference mode: use running stats
            mu = running_mean[c];
            var_val = running_var[c];
        }

        s_mu = mu;
        s_inv_std = rsqrtf(var_val + epsilon);
    }
    __syncthreads();

    float mu = s_mu;
    float inv_std = s_inv_std;
    float gamma = bn_weight[c];
    float beta = bn_bias[c];

    // ------------------------------------------------------------------
    // Phase 2: Apply Transformation and Write Output
    // ------------------------------------------------------------------
    for (int i = tid; i < N; i += blockDim.x) {
        float val = input[i * C + c] * s;
        output[i * C + c] = (val - mu) * inv_std * gamma + beta;
    }
}

