import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Swish + Add Bias + GroupNorm
# This kernel optimizes memory bandwidth by fusing element-wise operations 
# (Swish, Add) directly into the GroupNorm reduction pass.
fused_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_swish_gn_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    const float* __restrict__ gn_weight,
    const float* __restrict__ gn_bias,
    float* __restrict__ output,
    int N, int C, int G, int D, float eps) 
{
    // N: Batch Size
    // C: Total Channels (out_features)
    // G: Number of Groups
    // D: Channels per Group (C / G)

    // Grid Setup:
    // Grid X: Batch Index (0..N-1)
    // Grid Y: Group Index (0..G-1)
    // Block X: Channel in Group Index (0..D-1)

    int n = blockIdx.x;
    int g = blockIdx.y;
    int d = threadIdx.x;

    // Global channel index
    int c = g * D + d;

    // Flat index for input/output (Row-major: N x C)
    long long idx = (long long)n * C + c;

    // --- Phase 1: Fused Pre-Ops (Swish + Add Bias) ---
    // Load data once
    float x = input[idx];

    // Swish Activation: x * sigmoid(x)
    float sig = 1.0f / (1.0f + expf(-x));
    float val = x * sig;

    // Add external bias
    val = val + bias[c];

    // --- Phase 2: GroupNorm Statistics (Mean & Variance) ---
    // We calculate mean and variance across the D channels in this group.
    // Using shared memory for parallel reduction.
    extern __shared__ float s_data[];

    // Store 'val' in shared memory for reduction
    s_data[d] = val;
    __syncthreads();

    // Tree Reduction for Sum (Mean)
    // Assumes D is a power of 2 (e.g., 64).
    for (int stride = D / 2; stride > 0; stride >>= 1) {
        if (d < stride) {
            s_data[d] += s_data[d + stride];
        }
        __syncthreads();
    }

    // Broadcast Mean to all threads in block
    float mean = s_data[0] / D;

    // Calculate Squared Difference
    // We reuse 'val' from register
    float diff = val - mean;
    s_data[d] = diff * diff;
    __syncthreads();

    // Tree Reduction for Sum of Squares (Variance)
    for (int stride = D / 2; stride > 0; stride >>= 1) {
        if (d < stride) {
            s_data[d] += s_data[d + stride];
        }
        __syncthreads();
    }

    // Broadcast Variance and calculate Inverse Standard Deviation
    float var = s_data[0] / D;
    float inv_std = rsqrtf(var + eps);

    // --- Phase 3: Normalize and Apply Affine Parameters ---
    float norm = (val - mean) * inv_std;
    output[idx] = norm * gn_weight[c] + gn_bias[c];
}

torch::Tensor fused_forward_cuda(torch::Tensor input, torch::Tensor bias, 
                                 torch::Tensor gn_weight, torch::Tensor gn_bias, 
                                 int groups, float eps) {
