    auto output = torch::empty_like(input);

    // Launch bounds
    // We launch one block per (Batch, Group) pair.
    // Block size is D (Channels per group). 
    // For C=4096, G=64 -> D=64. Fits in block.
    dim3 grid(N, groups);
    dim3 block(D);
    size_t shared_mem_size = D * sizeof(float);

    fused_swish_gn_kernel<<<grid, block, shared_mem_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        gn_weight.data_ptr<float>(),
        gn_bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, groups, D, eps
    );

    return output;
}
