#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_swish_bias_gn_kernel(
    const float* __restrict__ input,      // [N, C] - result of matmul + linear_bias
    const float* __restrict__ extra_bias, // [C]
    const float* __restrict__ gn_weight,  // [C] - group_norm weight
    const float* __restrict__ gn_bias,    // [C] - group_norm bias
    float* __restrict__ output,           // [N, C]
    int N, int C, int G, int L) {

    int row = blockIdx.x;
    if (row >= N) return;

    // Use shared memory to store the row of z values and reduction intermediates
    // Shared memory layout: [shared_z (C floats), shared_sums (blockDim.x floats)]
    extern __shared__ float shared_mem[];
    float* shared_z = shared_mem;
    float* shared_sums = &shared_mem[C];

    // Step 1: Load input, apply Swish, and add extra bias
    // input[row, i] is already (X * W^T + b_linear)
    for (int i = threadIdx.x; i < C; i += blockDim.x) {
        float val = input[row * C + i];
        float s = 1.0f / (1.0f + expf(-val)); // Sigmoid
        shared_z[i] = (val * s) + extra_bias[i];
    }
    __syncthreads();

    // Step 2: Compute Group Normalization (Mean and Variance)
    // We assume L (elements per group) is 64 for efficient warp-based reduction.
    // Each group of 64 threads handles one group's normalization.
    int num_sub_blocks = blockDim.x / L; 
    int sub_id = threadIdx.x / L; 
    int tid_in_sub = threadIdx.x % L; 

    // Every thread in the block will enter this loop an equal number of times 
    // because G=64 and num_sub_blocks=16 (G % 16 == 0).
    for (int g = sub_id; g < G; g += num_sub_blocks) {
        int offset = g * L;
        float val = shared_z[offset + tid_in_sub];

        // Mean reduction across the 64 threads in the group (2 warps)
        float sum = val;
        for (int mask = 16; mask > 0; mask /= 2)
            sum += __shfl_xor_sync(0xffffffff, sum, mask);

        // Store warp sums in shared memory to combine them
        shared_sums[threadIdx.x] = sum;
        __syncthreads();

        // Each thread in the sub-block now computes the group mean
        float group_mean = (shared_sums[sub_id * L + 0] + 
                            shared_sums[sub_id * L + 32]) / (float)L;

        // Variance reduction across the 64 threads
        float diff = val - group_mean;
        float sq_diff = diff * diff;
        for (int mask = 16; mask > 0; mask /= 2)
            sq_diff += __shfl_xor_sync(0xffffffff, sq_diff, mask);

        shared_sums[threadIdx.x] = sq_diff;
        __syncthreads();

        float group_var = (shared_sums[sub_id * L + 0] + 
                           shared_sums[sub_id * L + 32]) / (float)L;
