        int h_out = temp % H_out; temp /= H_out;
        int d_out = temp % D_out; temp /= D_out;
        int c     = temp % C;     temp /= C;
        int n     = temp;

        int d_start = d_out * stride;
        int h_start = h_out * stride;
        int w_start = w_out * stride;

