    __shared__ float ds_A[TILE_WIDTH][TILE_WIDTH];
    __shared__ float ds_W[TILE_WIDTH][TILE_WIDTH];

    // Loop over tiles
    int num_phases = (K + TILE_WIDTH - 1) / TILE_WIDTH;

    for (int ph = 0; ph < num_phases; ++ph) {
