        // Stride of Channel dimension is spatial_size (S).
        // Element (n, c, s) is at: n * (C * S) + c * S + s
        // Base offset for this pixel (c=0) is:
        int base_offset = n * (channels * spatial_size) + s;
        int stride = spatial_size;

        // Pass 1: Find Max for numerical stability
        float max_val = -1e38f;
        for (int c = 0; c < channels; ++c) {
            float val = input[base_offset + c * stride];
            if (val > max_val) {
