__global__ void softmax_sigmoid_kernel(const float* __restrict__ input, float* __restrict__ output, int N, int C, int S) {
    // Each block handles one spatial location (n, d, h, w) across all channels c
    // The dimension of the reduction (Softmax) is C (dim=1).
    // S = D * H * W
    int spatial_idx = blockIdx.x; 
