    int n = spatial_idx / S;
    int s = spatial_idx % S;

    extern __shared__ float shared_data[];

    int tid = threadIdx.x;
    int base_offset = n * C * S + s;

    // 1. Find Max along C dimension for numerical stability of Softmax
    float local_max = -1e38f;
    for (int c = tid; c < C; c += blockDim.x) {
        local_max = fmaxf(local_max, input[base_offset + c * S]);
    }
    shared_data[tid] = local_max;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            shared_data[tid] = fmaxf(shared_data[tid], shared_data[tid + stride]);
        }
        __syncthreads();
    }
    float max_val = shared_data[0];
    __syncthreads();

    // 2. Compute Sum of Exp(x - max) along C
    float local_sum = 0.0f;
    for (int c = tid; c < C; c += blockDim.x) {
