#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_pool_scale_bias_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    float scale1,
    float scale2,
    float* __restrict__ output,
    int B, int C, int Di, int Hi, int Wi,
    int Do, int Ho, int Wo) {

    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * C * Do * Ho * Wo;
    if (tid >= total) return;

    // Mapping tid to output coordinates (b, c, do, ho, wo)
    int wo = tid % Wo;
    int ho = (tid / Wo) % Ho;
    int do_idx = (tid / (Wo * Ho)) % Do;
    int c = (tid / (Wo * Ho * Do)) % C;
    int b = tid / (Wo * Ho * Do * C);

    float sum = 0.0f;
    int base_channel_idx = ((b * C + c) * Di);

    // Average Pooling kernel_size=2, stride=2
    #pragma unroll
    for (int di = 0; di < 2; ++di) {
        int cur_di = do_idx * 2 + di;
        #pragma unroll
        for (int hi = 0; hi < 2; ++hi) {
            int cur_hi = ho * 2 + hi;
