#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Warp reduction helper
__inline__ __device__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

// Block reduction helper
__inline__ __device__ float blockReduceSum(float val) {
    static __shared__ float shared[32]; // Shared memory for 32 partial sums
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceSum(val);

    if (lane == 0) shared[wid] = val;
    __syncthreads();

    // Read from shared memory only if thread is in first warp
    val = (threadIdx.x < blockDim.x / 32.0f) ? shared[threadIdx.x] : 0.0f;
    if (wid == 0) val = warpReduceSum(val);

    return val;
}

__global__ void fused_kernel(
    const float* __restrict__ gemm_out,
    const float* __restrict__ subtract,
    const float* __restrict__ original_x,
    float* __restrict__ out,
    int rows,
    int cols) {

    // Each block processes one row (one batch item)
    int row_idx = blockIdx.x;
    if (row_idx >= rows) return;

    float sum = 0.0f;

    // Phase 1: Calculate Mean(Gemm - Subtract)
    // Grid-stride loop over columns
    for (int i = threadIdx.x; i < cols; i += blockDim.x) {
        float g = gemm_out[row_idx * cols + i];
        float s = subtract[i];
        sum += (g - s);
