    __syncthreads();

    float scalar_to_add = broadcast_scalar;

    // Phase 2: Add scalar to original_x and store
    for (int i = threadIdx.x; i < cols; i += blockDim.x) {
        int idx = row_idx * cols + i;
        out[idx] = original_x[idx] + scalar_to_add;
    }
