import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused GEMM-reduction, GELU, and Residual Addition.
# The original architecture's sequence (GEMM -> Subtract -> Mean -> LogSumExp -> GELU -> ResidualAdd)
# collapses the large 'out_features' dimension into a single scalar per row before the GELU and ResidualAdd.
# This means we can mathematically simplify the heavy GEMM + Mean into a simple row-wise dot product
# with a precomputed mean weight vector.
fused_op_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_reduction_gelu_add_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w_vec,
    const float* __restrict__ b_scalar_ptr,
    float* __restrict__ out,
    int B,
    int Fin) {

    int b_idx = blockIdx.x;
    if (b_idx >= B) return;

    // Shared memory for block-level reduction
    extern __shared__ float sdata[];

    float sum = 0.0f;
    int row_offset = b_idx * Fin;

    // Step 1: Compute dot product m_i = x_i dot w_vec
    for (int k = threadIdx.x; k < Fin; k += blockDim.x) {
        sum += x[row_offset + k] * w_vec[k];
    }
    sdata[threadIdx.x] = sum;
    __syncthreads();

    // Standard block reduction
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Step 2: Apply GELU to the reduction result
    __shared__ float row_gelu;
    if (threadIdx.x == 0) {
        float m_i = sdata[0] + (*b_scalar_ptr);
        // GELU formula: 0.5 * x * (1 + erf(x / sqrt(2)))
        // 0.7071067811865476f is approximately 1.0 / sqrt(2.0)
        row_gelu = 0.5f * m_i * (1.0f + erff(m_i * 0.7071067811865476f));
    }
    __syncthreads();

    // Step 3: Residual Add (out_ik = x_ik + row_gelu)
    for (int k = threadIdx.x; k < Fin; k += blockDim.x) {
        out[row_offset + k] = x[row_offset + k] + row_gelu;
    }
}

torch::Tensor fused_op_cuda(torch::Tensor x, torch::Tensor w_vec, torch::Tensor b_scalar_tensor) {
    int B = x.size(0);
    int Fin = x.size(1);
    auto out = torch::empty_like(x);

    const int threads = 512;
    const int blocks = B;
    const int shared_mem = threads * sizeof(float);

    fused_reduction_gelu_add_kernel<<<blocks, threads, shared_mem>>>(
        x.data_ptr<float>(),
        w_vec.data_ptr<float>(),
        b_scalar_tensor.data_ptr<float>(),
        out.data_ptr<float>(),
        B,
        Fin
    );

    return out;
}
"""

fused_op_cpp_source = (
    "torch::Tensor fused_op_cuda(torch::Tensor x, torch::Tensor w_vec, torch::Tensor b_scalar_tensor);"
)

# Compile the inline CUDA code
fused_op = load_inline(
    name="fused_op",
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_op_source,
    functions=["fused_op_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model using an algorithmic change and CUDA fusion.
    The sequence (Linear -> Subtract -> Mean -> LogSumExp) is collapsed into a single dot-product-like reduction.
    Complexity is reduced from O(Batch * Fin * Fout) to O(Batch * Fin + Fin * Fout).
    """
    def __init__(self, in_features, out_features, bias=True) -> None:
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features, bias=bias)
        self.subtract = nn.Parameter(torch.randn(out_features))
        self.in_features = in_features
        self.out_features = out_features

    def forward(self, x):
        # 1. Simplify GEMM + Subtract + Mean + LogSumExp(dim=1)
        # Because Mean(dim=1) reduces output to shape (Batch, 1), 
        # LogSumExp(dim=1) acts as an identity function.
        # The result is equivalent to: x @ (W.sum(dim=0)/Nout) + (bias - subtract).sum()/Nout.

        # Compute the averaged weight vector and scalar bias term.
        # This is much faster than the full GEMM when Batch is large.
        w_vec = self.gemm.weight.mean(dim=0)

        if self.gemm.bias is not None:
            b_scalar = (self.gemm.bias - self.subtract).mean()
        else:
            b_scalar = (-self.subtract).mean()

        # 2. Invoke the fused CUDA kernel
        # This kernel performs the dot product, GELU, and residual addition in a single pass.
        # Passing b_scalar as a 1-element tensor avoids host-device synchronization.
        return fused_op.fused_op_cuda(x, w_vec, b_scalar.view(1))

