import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused operations
# Operations: LogSumExp (dim=1) -> x * sigmoid(x+3)/6 -> Sub Bias -> Clamp
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>
#include <limits>

__global__ void fused_ops_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    float bias,
    int N,
    int C,
    int spatial_size,
    int total_output_elements
) {
    // We parallelize over the output elements (N, 1, D, H, W)
    // idx represents the linear index in the output tensor
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_output_elements) {
        // Map idx to (n, s), where s is the spatial index (flat D,H,W index)
        int n = idx / spatial_size;
        int s = idx % spatial_size;

        // Calculate base pointer for the input at batch n and spatial location s
        // Input layout is (N, C, D, H, W). Stride for C is spatial_size.
        // The element at (n, c, s) is at input[n * (C * spatial_size) + c * spatial_size + s]
        // Which simplifies to: (n * C * spatial_size + s) + c * spatial_size
        int input_base_offset = n * C * spatial_size + s;

        // --- Step 1: LogSumExp reduction across channel dimension C ---
        // For numerical stability: log(sum(exp(x_i))) = max + log(sum(exp(x_i - max)))

        float max_val = -std::numeric_limits<float>::infinity();

        // First pass: Find maximum value
        for (int c = 0; c < C; ++c) {
            float val = input[input_base_offset + c * spatial_size];
            if (val > max_val) {
                max_val = val;
            }
        }

        // Second pass: Sum exponentials
        float sum_exp = 0.0f;
        for (int c = 0; c < C; ++c) {
            float val = input[input_base_offset + c * spatial_size];
            sum_exp += expf(val - max_val);
        }

        float res = max_val + logf(sum_exp);

        // --- Step 2: Custom Activation: x * sigmoid(x + 3) / 6 ---
        // sigmoid(z) = 1.0 / (1.0 + exp(-z))
        // Here z = res + 3.0
        float sig = 1.0f / (1.0f + expf(-(res + 3.0f)));
        res = res * sig * 0.16666667f; // Divide by 6

        // --- Step 3: Subtract Bias ---
        // Bias is a scalar broadcasted to the whole tensor
        res = res - bias;

        // --- Step 4: Clamp between -1 and 1 ---
        res = fminf(fmaxf(res, -1.0f), 1.0f);

        // Write to output
        output[idx] = res;
    }
}

