import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for Fused GroupNorm + LeakyReLU + Add
# Optimized for the specific case where channels per group (K) is 16.
# Architecture parameters: hidden_size=8192, num_groups=512 -> 8192/512 = 16 channels per group.

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define K 16 

template <typename T>
__device__ __forceinline__ T warpReduceSum(T val) {
    // XOR shuffle reduction for 16 threads (sub-warp reduction)
    // Since K=16, we only need to exchange data within aligned chunks of 16 threads.
    // The mask 0xffffffff implies all threads in the warp participate, but XOR logic
    // ensures data doesn't cross the 16-thread boundaries for these strides.
    unsigned int mask = 0xffffffff;
    val += __shfl_xor_sync(mask, val, 8);
    val += __shfl_xor_sync(mask, val, 4);
    val += __shfl_xor_sync(mask, val, 2);
    val += __shfl_xor_sync(mask, val, 1);
    return val;
}

__global__ void fused_gn_lrelu_add_kernel(
    float* __restrict__ x,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    int N,
    int C,
    int num_groups,
    float eps,
    float negative_slope) {

    // Each block handles multiple groups.
    // Thread logic:
    // tid % 16 -> lane index within the group (0..15)
    // tid / 16 -> local group index within the block

    int tid = threadIdx.x;
    int lane = tid % K; 
    int group_id_in_block = tid / K;

    int groups_per_block = blockDim.x / K;
    int global_group_idx = blockIdx.x * groups_per_block + group_id_in_block;

    // Total groups = N * num_groups
    if (global_group_idx >= N * num_groups) return;

    // Determine which batch sample (n) and which group (g) this corresponds to
    int n = global_group_idx / num_groups;
    int g = global_group_idx % num_groups;

    // Calculate memory offset
    // x is (N, C). Group g starts at index g*K within the channel dimension C.
    int offset = n * C + g * K + lane;

    // Load input
    float val = x[offset];

    // --- Group Normalization ---

    // 1. Mean
    float sum = warpReduceSum(val);
    float mean = sum / float(K);

    // 2. Variance
    float diff = val - mean;
    float diff_sq = diff * diff;
    float sum_sq = warpReduceSum(diff_sq);
    float var = sum_sq / float(K); // Biased variance matching PyTorch default
    float inv_std = rsqrtf(var + eps);

    // 3. Normalize & Affine Transform
    // Gamma and Beta are shape (C). The index corresponds to the specific channel.
    int c_idx = g * K + lane;
    float norm = diff * inv_std;
    float out = norm * gamma[c_idx] + beta[c_idx];

    // --- LeakyReLU ---
    if (out < 0.0f) {
        out = out * negative_slope;
    }

    // --- Element-wise Add (x + x) ---
    out = out + out;

    // Store result
    x[offset] = out;
}

