    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    // Verify optimization assumption
    int channels_per_group = C / num_groups;
    TORCH_CHECK(channels_per_group == K, "Kernel is optimized for 16 channels per group");

    const int threads_per_block = 256;
    const int groups_per_block = threads_per_block / K;
    const int total_groups = N * num_groups;
    const int num_blocks = (total_groups + groups_per_block - 1) / groups_per_block;

    fused_gn_lrelu_add_kernel<<<num_blocks, threads_per_block>>>(
