import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# -------------------------------------------------------------------------------------------------
# Custom CUDA Kernel: Fused Bias Add + Dropout + Softmax
# -------------------------------------------------------------------------------------------------
# This kernel fuses three operations:
# 1. Bias Addition: x + b
# 2. Dropout: Apply random mask and scale
# 3. Softmax: exp(x - max) / sum(exp(x - max))
#
# It uses an "Online Softmax" 2-pass algorithm to compute the Softmax normalization
# constants without storing intermediate dropout results in global memory, saving bandwidth.
# To ensure the dropout mask is consistent across the two passes (one for max/sum, one for output),
# we use a stateless hash-based Random Number Generator (Wang Hash) seeded by a global seed
# and the element index.

cuda_source = """
#include <cuda_runtime.h>
#include <torch/extension.h>
#include <math.h>

// A fast, statistically decent hash function for generating deterministic random numbers
// based on a seed and an index. Returns a float in [0, 1).
__device__ __forceinline__ float get_random_uniform(unsigned int seed, unsigned int idx) {
    unsigned int h = idx ^ seed;
    h = (h ^ 61) ^ (h >> 16);
    h *= 9;
    h = h ^ (h >> 4);
    h *= 0x27d4eb2d;
    h = h ^ (h >> 15);
    // Convert to float [0, 1)
    return (h & 0xFFFFFF) / 16777216.0f;
}

__global__ void fused_bias_dropout_softmax_kernel(
    const float* __restrict__ input, 
    const float* __restrict__ bias, 
    float* __restrict__ output,
    int rows, 
    int cols, 
    float dropout_p, 
    float dropout_scale, 
    unsigned int seed
) {
    // Each block handles one row (batch element)
    int row = blockIdx.x;
    if (row >= rows) return;

    int tid = threadIdx.x;

    // Shared memory for warp/block reductions
    // Layout: [warps_max | warps_sum]
    // Assuming block size 256 -> 8 warps. 32 floats * 2 is enough.
    extern __shared__ float s_mem[];
    float* s_max_vals = s_mem;
    float* s_sum_vals = &s_mem[32]; 

    // --- Pass 1: Compute Max and Sum (Online Softmax) ---
    // We compute local max and sum of exp(val - max)

    float local_max = -1e20f; // -inf
    float local_sum = 0.0f;

    // Stride loop over columns
    for (int i = tid; i < cols; i += blockDim.x) {
        int idx = row * cols + i;
        float val = input[idx] + bias[i]; // Fused Bias Add

        // Fused Dropout
        float r = get_random_uniform(seed, idx);
        if (r > dropout_p) {
            val = val * dropout_scale;
        } else {
            val = 0.0f; 
        }

        // Online Softmax Update
        // Update local max and correct local sum
        float new_max = fmaxf(local_max, val);
        float multiplier = expf(local_max - new_max);
        local_sum = local_sum * multiplier + expf(val - new_max);
        local_max = new_max;
    }

    // --- Reduction: Intra-Warp ---
    // Reduce max and sum within the warp
    for (int offset = 16; offset > 0; offset /= 2) {
        float other_max = __shfl_down_sync(0xffffffff, local_max, offset);
        float other_sum = __shfl_down_sync(0xffffffff, local_sum, offset);

        float new_max = fmaxf(local_max, other_max);
        float s1 = local_sum * expf(local_max - new_max);
        float s2 = other_sum * expf(other_max - new_max);

        local_max = new_max;
        local_sum = s1 + s2;
    }

    // --- Reduction: Warp-to-Block ---
    int lane = tid % 32;
    int warp = tid / 32;

    // First thread of each warp writes to shared memory
    if (lane == 0) {
        s_max_vals[warp] = local_max;
        s_sum_vals[warp] = local_sum;
    }
    __syncthreads();

    // First warp reduces the shared results
    float block_max = -1e20f;
    float block_sum = 0.0f;

    if (warp == 0) {
        int num_warps = blockDim.x / 32;
        if (lane < num_warps) {
            block_max = s_max_vals[lane];
            block_sum = s_sum_vals[lane];
        } else {
            block_max = -1e20f;
            block_sum = 0.0f;
        }

        // Reduce within first warp
        for (int offset = 16; offset > 0; offset /= 2) {
            float other_max = __shfl_down_sync(0xffffffff, block_max, offset);
            float other_sum = __shfl_down_sync(0xffffffff, block_sum, offset);

            float new_max = fmaxf(block_max, other_max);
            float s1 = block_sum * expf(block_max - new_max);
            float s2 = other_sum * expf(other_max - new_max);

            block_max = new_max;
            block_sum = s1 + s2;
        }

        // Broadcast result to shared memory for all threads
        if (lane == 0) {
            s_max_vals[0] = block_max; // Reuse index 0
            s_sum_vals[0] = block_sum;
        }
    }
    __syncthreads();

    block_max = s_max_vals[0];
    block_sum = s_sum_vals[0];

    // --- Pass 2: Normalize and Write Output ---
    for (int i = tid; i < cols; i += blockDim.x) {
        int idx = row * cols + i;
        float val = input[idx] + bias[i];

        // Re-compute dropout (Deterministic due to same seed/idx)
        float r = get_random_uniform(seed, idx);
        if (r > dropout_p) {
            val = val * dropout_scale;
        } else {
            val = 0.0f;
        }

        output[idx] = expf(val - block_max) / block_sum;
