#include <torch/extension.h>
#include <cuda_runtime.h>

__device__ __forceinline__ float gelu(float x) {
    // Exact GELU approximation: 0.5 * x * (1 + erf(x / sqrt(2)))
    // 1/sqrt(2) approx 0.70710678f
    return 0.5f * x * (1.0f + erff(x * 0.70710678f));
}

__global__ void fused_gelu_pool_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N,
    int C,
    int S) {

    // We parallelize over (Batch * Channels). Each block handles one channel of one sample.
    int idx = blockIdx.x;
    if (idx >= N * C) return;

    // Calculate offset for the current channel slice.
    // Input layout is NCHW, so each slice is contiguous with size S = H * W.
    int offset = idx * S;

    float sum = 0.0f;

    // Grid-stride loop over the spatial dimension S
    for (int i = threadIdx.x; i < S; i += blockDim.x) {
        float val = input[offset + i];
        sum += gelu(val);
    }

    // Shared memory for block reduction
    extern __shared__ float sdata[];
    sdata[threadIdx.x] = sum;
    __syncthreads();

    // Tree reduction in shared memory
    // Assumes blockDim.x is a power of 2
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
        }
        __syncthreads();
    }

    // Write result to global memory
    // Average pooling means dividing the sum by the number of spatial elements (S)
    if (threadIdx.x == 0) {
        output[idx] = sdata[0] / static_cast<float>(S);
    }
}

