    // Calculate output index and store result
    // Output shape: (N, Cout, H_out, W_out)
    int out_idx = b * (out_channels * out_h * out_w) + 
                  oc * (out_h * out_w) + 
                  row * out_w + 
                  col;

    output[out_idx] = val;
}

