# Define the custom CUDA kernel for fused Pooling + BatchNorm
fused_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_pool_bn_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ scale,
    const float* __restrict__ shift,
    int N, int C, 
    int D_in, int H_in, int W_in,
    int D_out, int H_out, int W_out) {

    // Calculate global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * D_out * H_out * W_out;

    if (idx < total_elements) {
        // Map linear index to output coordinates (n, c, d_out, h_out, w_out)
        int w_out = idx % W_out;
        int temp = idx / W_out;
        int h_out = temp % H_out;
        temp /= H_out;
        int d_out = temp % D_out;
        temp /= D_out;
        int c = temp % C;
        int n = temp / C;

        // Map output coordinates to input coordinates
        // The effective operation is AvgPool with kernel=4, stride=4
        int d_in_start = d_out * 4;
        int h_in_start = h_out * 4;
        int w_in_start = w_out * 4;

        float sum = 0.0f;

        // Calculate the base offset for this specific image and channel
        // Input layout assumption: N, C, D, H, W (Contiguous)
        int channel_offset = (n * C + c) * (D_in * H_in * W_in);

        // Iterate over the 4x4x4 pooling window
        #pragma unroll
        for (int z = 0; z < 4; ++z) {
            int d_idx = d_in_start + z;
            // Check bounds just in case, though calculated sizes should ensure safety
            if (d_idx < D_in) {
                int row_offset = channel_offset + d_idx * (H_in * W_in);
                #pragma unroll
                for (int y = 0; y < 4; ++y) {
                    int h_idx = h_in_start + y;
                    if (h_idx < H_in) {
                        int col_offset = row_offset + h_idx * W_in;
                        #pragma unroll
                        for (int x = 0; x < 4; ++x) {
                            int w_idx = w_in_start + x;
                            if (w_idx < W_in) {
                                sum += input[col_offset + w_idx];
                            }
                        }
                    }
                }
            }
        }

        // Compute average (divide by 4*4*4 = 64)
        float avg = sum * 0.015625f;

        // Apply Batch Normalization: y = (x - mean)/std * gamma + beta
        // Precomputed as: y = x * scale + shift
        output[idx] = avg * scale[c] + shift[c];
    }
}

torch::Tensor fused_pool_bn_cuda(torch::Tensor input, torch::Tensor scale, torch::Tensor shift) {
    auto N = input.size(0);
    auto C = input.size(1);
    auto D_in = input.size(2);
    auto H_in = input.size(3);
    auto W_in = input.size(4);

