    auto D_out = (D_in - 4) / 4 + 1;
    auto H_out = (H_in - 4) / 4 + 1;
    auto W_out = (W_in - 4) / 4 + 1;

    auto output = torch::empty({N, C, D_out, H_out, W_out}, input.options());

    int total_elements = N * C * D_out * H_out * W_out;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_pool_bn_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        scale.data_ptr<float>(),
        shift.data_ptr<float>(),
        N, C, D_in, H_in, W_in, D_out, H_out, W_out
    );

    return output;
}
