    Performs 3D transposed convolution using PyTorch's implementation,
    followed by a custom kernel that fuses Batch Normalization and two 
    stages of Average Pooling (effectively 4x4x4 pooling).
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, bias_shape):
        super(ModelNew, self).__init__()
        # We keep the ConvTranspose3d as it is highly optimized in CuDNN
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding)

        # We define BatchNorm to hold the parameters (weights/bias/running stats)
        # but we won't call it directly in forward.
        self.batch_norm = nn.BatchNorm3d(out_channels)

        # Pooling layers are removed; their logic is fused into the custom kernel.

    def forward(self, x):
        # 1. Transposed Convolution
        x = self.conv_transpose(x)

        # 2. Fused Pooling and BatchNorm
        # To fuse BN with pooling, we exploit the linearity: Avg(BN(x)) == BN(Avg(x)).
