#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_bn_scale_kernel(float* x, const float* w_eff, const float* b_eff, 
                                      int channels, int spatial_size) {
    // Grid dimension X covers (Batch * Channels)
    // Grid dimension Y covers Spatial dimensions (H * W)

    int nc = blockIdx.x; // Index representing (n * channels + c)
    int c = nc % channels; // The channel index

    // Calculate global spatial index within the (n, c) slice
    int s_idx = blockIdx.y * blockDim.x + threadIdx.x;

    if (s_idx < spatial_size) {
        // Calculate the flat index in the 4D tensor
        // Layout is NCHW, so each (n, c) block is contiguous of size spatial_size
        int idx = nc * spatial_size + s_idx;

        float val = x[idx];
        // Apply affine transform: x = x * w_eff + b_eff
        x[idx] = val * w_eff[c] + b_eff[c];
    }
}

torch::Tensor apply_fused_bn_scale(torch::Tensor x, torch::Tensor w_eff, torch::Tensor b_eff) {
    // x dimensions: (N, C, H, W)
    int batch = x.size(0);
    int channels = x.size(1);
    int height = x.size(2);
    int width = x.size(3);
    int spatial_size = height * width;

    // Configure Grid
    // We treat each (Batch, Channel) slice independently for the Z/Y grid
    // Grid X: batch * channels (Total number of feature maps)
    // Grid Y: Number of blocks needed to cover spatial_size

    const int block_size = 256;
    int num_spatial_blocks = (spatial_size + block_size - 1) / block_size;

    dim3 grid(batch * channels, num_spatial_blocks);
    dim3 block(block_size);

    fused_bn_scale_kernel<<<grid, block>>>(
        x.data_ptr<float>(), 
        w_eff.data_ptr<float>(), 
        b_eff.data_ptr<float>(),
        channels, 
        spatial_size
    );

    return x;
}
"""

