class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor):
        super(ModelNew, self).__init__()
        # Keep optimized PyTorch Conv2d
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)

        # Manually manage BatchNorm parameters to interface with custom kernel
        self.bn_weight = nn.Parameter(torch.ones(out_channels))
        self.bn_bias = nn.Parameter(torch.zeros(out_channels))
        self.register_buffer('running_mean', torch.zeros(out_channels))
        self.register_buffer('running_var', torch.ones(out_channels))

        self.scaling_factor = scaling_factor
        self.fused_ops = fused_ops

    def forward(self, x):
        # 1. Convolution (PyTorch optimized)
        x = self.conv(x)

        # 2. Prepare Statistics for BN
        # Matches nn.BatchNorm2d default behavior (affine=True, track_running_stats=True)
        if self.training:
            # Calculate batch stats
            # dim=(0, 2, 3) corresponds to (Batch, Height, Width) -> reduces to (Channels)
            mean = x.mean(dim=(0, 2, 3))
            var = x.var(dim=(0, 2, 3), unbiased=False)

            # Update running stats (momentum=0.1 default)
            n = x.numel() / x.size(1)
            with torch.no_grad():
                self.running_mean = 0.9 * self.running_mean + 0.1 * mean
                # PyTorch running_var update uses unbiased variance
                var_unbiased = x.var(dim=(0, 2, 3), unbiased=True)
                self.running_var = 0.9 * self.running_var + 0.1 * var_unbiased
        else:
            mean = self.running_mean
            var = self.running_var

        # 3. Calculate fused effective weights and bias
        # Original: y = ((x - mean) / sqrt(var + eps)) * gamma + beta
        # Output:   z = y * scale
        # Fused:    z = x * w_eff + b_eff
        # w_eff = (gamma * scale) / sqrt(var + eps)
        # b_eff = (beta * scale) - (mean * w_eff)

        eps = 1e-5
        std = torch.sqrt(var + eps)

        # Calculate effective parameters for the custom kernel
        # These are small 1D tensors (size C), computation is negligible
        w_eff = (self.bn_weight * self.scaling_factor) / std
        b_eff = (self.bn_bias * self.scaling_factor) - (mean * w_eff)

        # 4. Apply Custom Fused Kernel
        # This replaces the element-wise ops of BN (sub, div, mul, add) and Scaling (mul)
        # with a single fused Ax + B operation.
        # Ensure parameters are contiguous for the CUDA kernel
        x = self.fused_ops.apply_fused_bn_scale(x, w_eff.contiguous(), b_eff.contiguous())

        return x

