# It uses shared memory tiling (32x32 blocks) to optimize memory access.
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_linear_relu_kernel(
    const float* __restrict__ A, 
    const float* __restrict__ W, 
    const float* __restrict__ Bias, 
    float* __restrict__ C, 
    int M, int N, int K) {

    // -------------------------------------------------------------------------
    // Dimensions and Indices
    // -------------------------------------------------------------------------
    // Block index
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread index
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global Matrix Coordinates
    // row corresponds to M dimension (Batch Size)
    // col corresponds to N dimension (Out Features)
    int row = by * 32 + ty; 
    int col = bx * 32 + tx; 

    // -------------------------------------------------------------------------
    // Shared Memory Setup
    // -------------------------------------------------------------------------
    // Tile size 32x32.
    // Padding of 1 float to avoid shared memory bank conflicts (32 banks).
    // As stores a tile of Input A.
    // Ws stores a tile of Weight W.
    __shared__ float As[32][33];
    __shared__ float Ws[32][33];

    float val = 0.0f;

    // -------------------------------------------------------------------------
    // Main Loop - Iterate over K dimension (In Features) in chunks of 32
    // -------------------------------------------------------------------------
    for (int k = 0; k < K; k += 32) {

        // 1. Load Tile from A (Input)
        // A is (M, K). We need A[row, k...k+31].
        // Each thread loads one element A[row, k+tx].
        if (row < M && (k + tx) < K) {
            As[ty][tx] = A[row * K + k + tx];
        } else {
            As[ty][tx] = 0.0f;
        }

        // 2. Load Tile from W (Weights)
        // W is (N, K). We need rows of W corresponding to output columns.
        // The block computes output cols: bx*32 ... bx*32+31.
        // So we need W rows: bx*32 ... bx*32+31.
        // We load W sub-block: rows [bx*32, bx*32+31], cols [k, k+31].
        // Thread (ty, tx) loads W[bx*32 + ty, k + tx].
        // This mapping ensures coalesced reads from global memory.

        int w_row = bx * 32 + ty;
        int w_col = k + tx;

        if (w_row < N && w_col < K) {
            Ws[ty][tx] = W[w_row * K + w_col];
        } else {
            Ws[ty][tx] = 0.0f;
        }

        // Synchronize to ensure tiles are loaded
        __syncthreads();

        // 3. Compute Partial Dot Product
        // C[row, col] += sum(A[row, k+kk] * W[col, k+kk])
        // We accumulate results for C[row, col] which corresponds to thread (ty, tx).
        // A row is mapped to As[ty].
        // W row (corresponding to col) is mapped to Ws[tx].

        #pragma unroll
        for (int kk = 0; kk < 32; ++kk) {
            val += As[ty][kk] * Ws[tx][kk];
        }

        // Synchronize before overwriting shared memory in next iteration
        __syncthreads();
    }

    // -------------------------------------------------------------------------
    // Epilogue: Bias Add + ReLU + Write
    // -------------------------------------------------------------------------
    if (row < M && col < N) {
        // Add Bias (broadcast over batch)
        val += Bias[col];

        // ReLU
        val = fmaxf(val, 0.0f);

        // Write to global memory
        C[row * N + col] = val;
    }
}

