from torch.utils.cpp_extension import load_inline

# CUDA source for fused Global Average Pooling and Scaling.
# This kernel reduces the spatial dimensions (D, H, W) of the input tensor 
# to (1, 1, 1) and applies a scaling factor in a single pass.
# This avoids reading/writing the large intermediate tensor generated by ConvTranspose3d
# multiple times (for Scale and BN), significantly saving memory bandwidth.
pool_scale_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void global_avg_pool_scale_kernel(
    const float* __restrict__ input, 
    float* __restrict__ output, 
    int batch_size, 
    int channels, 
    int spatial_size, 
    float scale_factor) 
{
    // Grid layout: x -> Batch (N), y -> Channel (C)
    int n = blockIdx.x;
    int c = blockIdx.y;

    if (n >= batch_size || c >= channels) return;

    // Calculate offset for this batch and channel
    // Input tensor is contiguous in memory (N, C, D, H, W)
    long long offset = static_cast<long long>(n) * channels * spatial_size + static_cast<long long>(c) * spatial_size;

    float sum = 0.0f;

    // Grid-stride loop to sum up all spatial elements for this channel
    // All threads in the block contribute to the sum for this specific (n, c)
    for (int i = threadIdx.x; i < spatial_size; i += blockDim.x) {
        sum += input[offset + i];
    }

    // Shared memory for block reduction
    extern __shared__ float sdata[];
    int tid = threadIdx.x;
    sdata[tid] = sum;
    __syncthreads();

    // Reduce within the block
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // The first thread writes the result
    if (tid == 0) {
        float avg = sdata[0] / static_cast<float>(spatial_size);
        // Apply scaling factor here
        // Output is stored linearly, viewed as (N, C, 1, 1, 1) in Python
        output[n * channels + c] = avg * scale_factor;
    }
}

