    auto C = input.size(1);
    auto D = input.size(2);
    auto H = input.size(3);
    auto W = input.size(4);

    int spatial_size = D * H * W;

    // Allocate output tensor
    auto options = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    // Output shape (N, C, 1, 1, 1)
