#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void scale_bn_pool_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    float* __restrict__ output,
    float scale_factor,
    float eps,
    int N, int C, int spatial_size) {

    int nc = blockIdx.x;
    int tid = threadIdx.x;

    if (nc >= N * C) return;

    // Load BN parameters for this channel
    int c = nc % C;
    float w_val = weight[c];
    float b_val = bias[c];
    float m_val = mean[c];
    float v_val = var[c];

    // Precompute scaling and offset based on BN and scale factor
    // y = ((x * scale - mean) / sqrt(var + eps)) * weight + bias
    // y = x * (scale * weight / sqrt(var + eps)) + (bias - mean * weight / sqrt(var + eps))
    float inv_std = rsqrtf(v_val + eps);
    float factor = scale_factor * inv_std * w_val;
    float offset = b_val - m_val * inv_std * w_val;

    float sum = 0.0f;
    const float* input_ptr = input + (size_t)nc * spatial_size;

    // Each thread sums a portion of the spatial elements
    for (int i = tid; i < spatial_size; i += blockDim.x) {
        sum += input_ptr[i] * factor + offset;
    }

    // Warp-level reduction
    for (int offset_warp = 16; offset_warp > 0; offset_warp /= 2) {
        sum += __shfl_down_sync(0xffffffff, sum, offset_warp);
    }

    // Block-level reduction using shared memory
    __shared__ float shared_sum[32]; // Enough for 1024 threads (32 warps)
    int lane = tid % 32;
    int wid = tid / 32;

    if (lane == 0) shared_sum[wid] = sum;
    __syncthreads();

    // Final reduction in the first warp
    if (wid == 0) {
        float final_sum = (tid < (blockDim.x + 31) / 32) ? shared_sum[lane] : 0.0f;
        for (int offset_warp = 16; offset_warp > 0; offset_warp /= 2) {
            final_sum += __shfl_down_sync(0xffffffff, final_sum, offset_warp);
        }
        if (tid == 0) {
            output[nc] = final_sum / (float)spatial_size;
        }
    }
