        const float* input_n = input + n * stride_n;

        // The effective pooling operation is MaxPool3d(kernel_size=6, stride=6)
        // Calculate the top-left-front corner of the window in the input tensor
        int d_start = d_out * 6;
        int h_start = h_out * 6;
        int w_start = w_out * 6;

        float sum_val = 0.0f;

