#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// GELU approximation: 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
__device__ __forceinline__ float gelu_f(float x) {
    return 0.5f * x * (1.0f + tanhf(0.7978845608f * (x + 0.044715f * x * x * x)));
}

// Column-wise max reduction kernel (for max_dim = 0)
__global__ void column_max_kernel(const float* __restrict__ input, float* __restrict__ output, int rows, int cols) {
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    if (col < cols) {
        float max_val = input[col]; // Start with the first row
        for (int row = 1; row < rows; ++row) {
            float val = input[row * cols + col];
            if (val > max_val) max_val = val;
        }
        output[col] = max_val;
    }
}

// Computes the mean of the reduction vector and applies fused subtraction + GELU
// Since n=8192, a single block of 512 threads is sufficient.
__global__ void apply_mean_gelu_kernel(float* data, int n) {
    __shared__ float shared_sum;
    if (threadIdx.x == 0) shared_sum = 0.0f;
    __syncthreads();

    float local_sum = 0.0f;
    for (int i = threadIdx.x; i < n; i += blockDim.x) {
        local_sum += data[i];
    }
    atomicAdd(&shared_sum, local_sum);
    __syncthreads();

    float mean = shared_sum / (float)n;
