#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Helper for warp-level reduction
template <typename T>
__device__ __forceinline__ T warpReduceMax(T val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val = max(val, __shfl_down_sync(0xffffffff, val, offset));
    return val;
}

template <typename T>
__device__ __forceinline__ T warpReduceSum(T val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

// Fused Kernel: BN (Inference) -> Scale -> Softmax
// Assumptions: 
// - Block size covers the row logic (uses loops for large rows)
// - One block per row (batch element)
__global__ void fused_bn_scale_softmax_kernel(
    const float* __restrict__ x,
    const float* __restrict__ bn_mean,
    const float* __restrict__ bn_var,
    const float* __restrict__ bn_weight,
    const float* __restrict__ bn_bias,
    const float* __restrict__ scale,
    float* __restrict__ out,
    int batch_size,
    int features,
    float eps) {

    int row = blockIdx.x;
    if (row >= batch_size) return;

    // Shared memory for block-level reductions
    // Layout: [s_max (32 floats)] [s_sum (32 floats)]
    extern __shared__ float shared_mem[];
    float* s_max = shared_mem;
    float* s_sum = shared_mem + 32;

    int tid = threadIdx.x;
    int lane = tid % 32;
    int warp_id = tid / 32;
    int num_warps = blockDim.x / 32;

    // Pointers to the current row
    const float* row_x = x + row * features;
    float* row_out = out + row * features;

    float s_val = scale[0];

    // Register buffer to avoid re-reading global memory
    // Capacity for 8192 features with 256 threads -> 32 items per thread
    const int MAX_ITEMS = 32; 
    float buffer[MAX_ITEMS];

    // 1. Load Data, Apply BN + Scale, Find Max
    float local_max = -1e37f; // effectively -infinity

    int idx = tid;
    #pragma unroll
    for (int i = 0; i < MAX_ITEMS; ++i) {
        if (idx < features) {
            float val = row_x[idx];

            // BN (Inference): (x - mean) / sqrt(var + eps) * weight + bias
            float mean = bn_mean[idx];
            float var = bn_var[idx];
            float w = bn_weight[idx];
            float b = bn_bias[idx];

            float inv_std = rsqrtf(var + eps);
            val = (val - mean) * inv_std * w + b;

            // Scale
            val = val * s_val;

            buffer[i] = val;
            local_max = fmaxf(local_max, val);
        } else {
            buffer[i] = -1e37f; // Padding
        }
        idx += blockDim.x;
    }

    // Warp Reduce Max
    local_max = warpReduceMax(local_max);
    if (lane == 0) s_max[warp_id] = local_max;
    __syncthreads();

    // Block Reduce Max
    if (tid == 0) {
        float block_max = -1e37f;
        for (int i = 0; i < num_warps; ++i) block_max = fmaxf(block_max, s_max[i]);
        s_max[0] = block_max;
    }
    __syncthreads();
    float row_max = s_max[0];

    // 2. Compute Exp and Sum
    float local_sum = 0.0f;
    idx = tid;
    #pragma unroll
    for (int i = 0; i < MAX_ITEMS; ++i) {
        if (idx < features) {
            float val = expf(buffer[i] - row_max);
            buffer[i] = val; // Store exp value
            local_sum += val;
        }
        idx += blockDim.x;
    }

    // Warp Reduce Sum
    local_sum = warpReduceSum(local_sum);
    if (lane == 0) s_sum[warp_id] = local_sum;
    __syncthreads();

    // Block Reduce Sum
    if (tid == 0) {
        float block_sum = 0.0f;
        for (int i = 0; i < num_warps; ++i) block_sum += s_sum[i];
        s_sum[0] = block_sum;
    }
    __syncthreads();
    float row_sum = s_sum[0];
    float inv_sum = 1.0f / row_sum;

    // 3. Normalize and Write
    idx = tid;
    #pragma unroll
    for (int i = 0; i < MAX_ITEMS; ++i) {
        if (idx < features) {
            row_out[idx] = buffer[i] * inv_sum;
        }
        idx += blockDim.x;
    }
