    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H_out * W_out;

    if (idx < total_elements) {
        // Map linear index to output coordinates (n, c, h_out, w_out)
        int w_out_idx = idx % W_out;
        int tmp = idx / W_out;
        int h_out_idx = tmp % H_out;
        tmp = tmp / H_out;
        int c_idx = tmp % C;
        int n_idx = tmp / C;

        // Calculate base input offset for this batch and channel
        // Input layout is (N, C, H, W)
        int input_offset_base = n * (C * H_in * W_in) + c * (H_in * W_in);

