import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel source code
# We implement a fused kernel that performs: (input + bias) / divisor -> GELU
# We optimize this using float4 vectorization to maximize memory bandwidth utilization.
fused_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// GELU Approximation: 0.5 * x * (1 + erf(x / sqrt(2)))
__device__ __forceinline__ float gelu_func(float x) {
    const float k0 = 0.70710678f; // 1 / sqrt(2)
    return 0.5f * x * (1.0f + erff(x * k0));
}

// Vectorized Kernel (float4)
__global__ void fused_bias_div_gelu_kernel_vec(
    const float* __restrict__ input, 
    const float* __restrict__ bias, 
    float* __restrict__ output, 
    float divisor, 
    int numel, 
    int cols
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Cast pointers to float4
    const float4* in_vec = reinterpret_cast<const float4*>(input);
    const float4* bias_vec = reinterpret_cast<const float4*>(bias);
    float4* out_vec = reinterpret_cast<float4*>(output);

    int num_vec = numel / 4;
    int cols_vec = cols / 4;

    float inv_divisor = 1.0f / divisor;

    for (int i = idx; i < num_vec; i += stride) {
        float4 v = in_vec[i];

        // Determine the column index for the vector to broadcast bias correctly
        // Since 'cols' is a multiple of 4, the bias pattern aligns with vectors.
        int b_idx = i % cols_vec;
        float4 b = bias_vec[b_idx];

        // Apply (val + bias) / divisor -> GELU component-wise
        v.x = gelu_func((v.x + b.x) * inv_divisor);
        v.y = gelu_func((v.y + b.y) * inv_divisor);
        v.z = gelu_func((v.z + b.z) * inv_divisor);
        v.w = gelu_func((v.w + b.w) * inv_divisor);

        out_vec[i] = v;
    }
}

// Scalar Fallback Kernel
__global__ void fused_bias_div_gelu_kernel_scalar(
    const float* __restrict__ input, 
    const float* __restrict__ bias, 
    float* __restrict__ output, 
    float divisor, 
    int numel, 
    int cols
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    float inv_divisor = 1.0f / divisor;

    for (int i = idx; i < numel; i += stride) {
        // Broadcast bias
        int col = i % cols;
        float val = input[i];
        float b = bias[col];

        // Compute
        val = (val + b) * inv_divisor;
        output[i] = gelu_func(val);
    }
}

torch::Tensor fused_forward_cuda(torch::Tensor input, torch::Tensor bias, float divisor) {
    auto numel = input.numel();
    auto cols = input.size(-1);

    auto output = torch::empty_like(input);

    // Get raw pointers
    float* in_ptr = input.data_ptr<float>();
    float* bias_ptr = bias.data_ptr<float>();
    float* out_ptr = output.data_ptr<float>();

    // Check if tensors are aligned to 16 bytes (sizeof(float4)) and dimensions allow vectorization
    bool aligned = (reinterpret_cast<uintptr_t>(in_ptr) % 16 == 0) &&
                   (reinterpret_cast<uintptr_t>(bias_ptr) % 16 == 0) &&
                   (reinterpret_cast<uintptr_t>(out_ptr) % 16 == 0) &&
                   (cols % 4 == 0) &&
                   (numel % 4 == 0);

    const int block_size = 256;

    if (aligned) {
        int num_vec = numel / 4;
        int grid_size = (num_vec + block_size - 1) / block_size;

        fused_bias_div_gelu_kernel_vec<<<grid_size, block_size>>>(
            in_ptr, bias_ptr, out_ptr, divisor, numel, cols
        );
    } else {
        int grid_size = (numel + block_size - 1) / block_size;

        fused_bias_div_gelu_kernel_scalar<<<grid_size, block_size>>>(
            in_ptr, bias_ptr, out_ptr, divisor, numel, cols
        );
    }

    return output;
}
"""

