import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused GroupNorm + Swish + Multiply + Swish
# This kernel is highly optimized for the specific case where channels_per_group == 32 (Warp Size).
# Given the architecture: out_features=8192, num_groups=256 -> 8192/256 = 32.
# This allows us to use warp-level primitives for reduction without shared memory synchronization.

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__device__ __forceinline__ float sigmoid_f(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__device__ __forceinline__ float swish_f(float x) {
    return x * sigmoid_f(x);
}

// Warp-level reduction sum. 
// Assumes mask is 0xffffffff (all threads active in warp).
__device__ __forceinline__ float warpReduceSum(float val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset /= 2) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}

__global__ void fused_gn_swish_mul_kernel(
    float* __restrict__ x,
    const float* __restrict__ gn_gamma,
    const float* __restrict__ gn_beta,
    const float* __restrict__ mul_weight,
    int N, 
    int C, 
    int G, 
    float eps
) {
    // Configuration:
    // BlockDim.x = 256 (8 warps)
    // GridDim.x = (N * G + 7) / 8
    // Each warp processes exactly one group (32 elements).

    int warp_id = threadIdx.x / 32;
    int lane_id = threadIdx.x % 32; // This maps to the channel index within the group

    int groups_per_block = blockDim.x / 32;
    int global_group_idx = blockIdx.x * groups_per_block + warp_id;

    // Total number of groups across the batch = BatchSize * NumGroups
    if (global_group_idx >= N * G) return;

    // Map linear group index to (Sample Index, Group Index)
    int n = global_group_idx / G;
    int g = global_group_idx % G;

    // Calculate global channel index c for accessing weights (gamma/beta/mul)
    // c ranges from 0 to C-1
    int c = g * 32 + lane_id;

    // Calculate flat index for accessing input/output tensor x
    int idx = n * C + c;

    float val = x[idx];

    // --- Step 1: GroupNorm Statistics (Mean & Variance) ---

    // Calculate Mean
    float sum = warpReduceSum(val);
    float mean = __shfl_sync(0xffffffff, sum, 0) / 32.0f;

    // Calculate Variance
    float diff = val - mean;
    float sq_diff = diff * diff;
    float sum_sq = warpReduceSum(sq_diff);
    float var = __shfl_sync(0xffffffff, sum_sq, 0) / 32.0f;

    // --- Step 2: Normalize & Apply Affine ---
    float inv_std = rsqrtf(var + eps);
    float gamma = gn_gamma[c];
    float beta = gn_beta[c];

    val = (val - mean) * inv_std * gamma + beta;

    // --- Step 3: Swish ---
    val = swish_f(val);

    // --- Step 4: Multiply Weight ---
    float mw = mul_weight[c];
    val = val * mw;

    // --- Step 5: Swish ---
    val = swish_f(val);

    // Write back result (in-place)
    x[idx] = val;
}

