#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_post_gn_kernel(
    const float* __restrict__ x_conv,
    const float* __restrict__ x_norm,
    float* out,
    int N, int C, int S) {

