    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_spatial = N * S;

    if (idx < total_spatial) {
        // Decompose index to find batch index 'n' and spatial offset 's'
        int n = idx / S;
        int s = idx % S;

        // Calculate base pointer offset for this spatial location
        // Input layout is NCHW.
        // memory_idx = n * (C * S) + c * S + s
        int base_offset = n * C * S + s;
        int stride = S; // Stride to jump between channels for the same pixel

        // Online LogSumExp accumulation variables
        // Formula: log(sum(exp(x_i)))
        // Stable update: new_max = max(old_max, x); sum = sum * exp(old_max - new_max) + exp(x - new_max)
        float max_val = -1e37f; // effectively -infinity
        float sum_exp = 0.0f;

        // Iterate over channels for this pixel
        for (int c = 0; c < C; ++c) {
            int ptr_idx = base_offset + c * stride;

            float v_conv = x_conv[ptr_idx];
            float v_norm = x_norm[ptr_idx];

            // 1. Tanh
            float v_tanh = tanhf(v_norm);

            // 2. HardSwish: x * ReLU6(x+3) / 6
            // Equivalent to:
            // if x <= -3: 0
            // if x >= 3: x
            // else: x * (x + 3) / 6
            float v_hs = 0.0f;
            if (v_tanh <= -3.0f) {
                v_hs = 0.0f;
            } else if (v_tanh >= 3.0f) {
                v_hs = v_tanh;
            } else {
                v_hs = v_tanh * (v_tanh + 3.0f) / 6.0f;
            }

            // 3. Residual Addition
            float v_res = v_conv + v_hs;

            // 4. LogSumExp Accumulation
            if (v_res > max_val) {
                sum_exp = sum_exp * expf(max_val - v_res) + 1.0f;
                max_val = v_res;
            } else {
                sum_exp += expf(v_res - max_val);
