#include <cuda_runtime.h>
#include <cmath>

// Scalar kernel for general cases
__global__ void fused_ops_kernel(const float* __restrict__ input, float* __restrict__ output, float add_val, float mul_val, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
