import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# -----------------------------------------------------------------------------------------
# Custom CUDA Kernel Definition
# -----------------------------------------------------------------------------------------
# This kernel fuses:
# 1. Element-wise Bias Add (explicit bias)
# 2. Hardtanh Activation
# 3. Mish Activation
# 4. GroupNorm (Mean/Var calculation + Normalization + Affine)
#
# Optimization Strategy:
# - Each warp (32 threads) processes exactly one Group of one Sample.
# - This is possible because channels_per_group = 8192 / 256 = 32.
# - Allows using __shfl_down_sync for extremely fast reductions without shared memory.
# - Avoids multiple read/write passes to global memory.

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__device__ __forceinline__ float mish_device(float x) {
    // Mish: x * tanh(softplus(x))
    // Softplus: log(1 + exp(x)). Threshold of 20.0 used to avoid overflow.
    float sp = (x > 20.0f) ? x : log1pf(expf(x));
    return x * tanhf(sp);
}

__device__ __forceinline__ float hardtanh_device(float x) {
    // Hardtanh: clamp(x, -1, 1)
    return fmaxf(-1.0f, fminf(1.0f, x));
}

// Warp-level reduction sum
__inline__ __device__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__global__ void fused_post_gemm_kernel(
    float* __restrict__ x, 
    const float* __restrict__ bias, 
    const float* __restrict__ gn_weight, 
    const float* __restrict__ gn_bias, 
    int N, int C, int G, float eps) {

    // Each warp handles one group of one sample.
    // Total groups to process = N * G

    int global_warp_idx = blockIdx.x * (blockDim.x / 32) + (threadIdx.x / 32);
    if (global_warp_idx >= N * G) return;

    int lane_idx = threadIdx.x % 32; // 0..31, corresponds to channel index within group

    int sample_idx = global_warp_idx / G;
    int group_idx = global_warp_idx % G;

    // Map to global data index
    // channels_per_group is assumed to be 32 based on architecture
    int channel_offset = group_idx * 32 + lane_idx;
    int data_idx = sample_idx * C + channel_offset;

    // -------------------------------------------------------
    // 1. Load Data
    // -------------------------------------------------------
    float val = x[data_idx];

    // -------------------------------------------------------
    // 2. Add Explicit Bias
    // -------------------------------------------------------
    float b = bias[channel_offset];
    val += b;

    // -------------------------------------------------------
    // 3. Hardtanh Activation
    // -------------------------------------------------------
    val = hardtanh_device(val);

    // -------------------------------------------------------
    // 4. Mish Activation
    // -------------------------------------------------------
    val = mish_device(val);

    // -------------------------------------------------------
    // 5. GroupNorm
    // -------------------------------------------------------

    // Calculate Mean
    float mean = warpReduceSum(val) / 32.0f;
    mean = __shfl_sync(0xffffffff, mean, 0); // Broadcast mean to all lanes

    // Calculate Variance
    float diff = val - mean;
    float var = warpReduceSum(diff * diff) / 32.0f;
    var = __shfl_sync(0xffffffff, var, 0);   // Broadcast var to all lanes

    // Normalize
    float inv_std = rsqrtf(var + eps);
    val = (val - mean) * inv_std;

    // Affine Transform (Gamma/Beta)
    float gamma = gn_weight[channel_offset];
    float beta = gn_bias[channel_offset];
    val = val * gamma + beta;

    // -------------------------------------------------------
    // 6. Store Result
    // -------------------------------------------------------
    x[data_idx] = val;
}

torch::Tensor fused_forward_cuda(
    torch::Tensor x, 
    torch::Tensor bias, 
    torch::Tensor gn_weight, 
    torch::Tensor gn_bias, 
    int num_groups, 
    float eps) {

    int N = x.size(0);
    int C = x.size(1);

    // Sanity checks
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(gn_weight.is_cuda(), "gn_weight must be a CUDA tensor");
    TORCH_CHECK(C % num_groups == 0, "C must be divisible by num_groups");
    TORCH_CHECK(C / num_groups == 32, "This optimized kernel requires 32 channels per group (Warp Size).");

    int total_tasks = N * num_groups;
    int threads_per_block = 256;
    int warps_per_block = threads_per_block / 32;
    int num_blocks = (total_tasks + warps_per_block - 1) / warps_per_block;

    fused_post_gemm_kernel<<<num_blocks, threads_per_block>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        gn_weight.data_ptr<float>(),
        gn_bias.data_ptr<float>(),
        N, C, num_groups, eps
    );

    return x;
}
"""

