cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32

__global__ void linear_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ b,
    float* __restrict__ Y,
    int M, int N, int K,
    bool use_relu) 
{
    // X: M x K
    // W: N x K (transposed in computation conceptually to match X*W^T)
    // Y: M x N

    int bx = blockIdx.x;
    int by = blockIdx.y;

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Output coordinates
    int row = by * TILE_SIZE + ty; // Global row index for Y and X
    int col = bx * TILE_SIZE + tx; // Global col index for Y and W (row index)

    // Shared memory for tiles
    // s_W is padded to avoid bank conflicts
    __shared__ float s_X[TILE_SIZE][TILE_SIZE];
    __shared__ float s_W[TILE_SIZE][TILE_SIZE + 1];

    float val = 0.0f;

    // Loop over tiles across the K dimension
    int num_tiles = (K + TILE_SIZE - 1) / TILE_SIZE;

    for (int t = 0; t < num_tiles; ++t) {
        int k_start = t * TILE_SIZE;

        // Load tile from X
        if (row < M && (k_start + tx) < K) {
            s_X[ty][tx] = X[row * K + k_start + tx];
        } else {
            s_X[ty][tx] = 0.0f;
        }

        // Load tile from W
        // We load the block of W corresponding to the output features (Y cols) handled by this block.
        // W is N x K. Y col 'col' corresponds to W row 'col'.
        // We map threads to load coalesced.
        int w_row = bx * TILE_SIZE + ty;
        int w_col = k_start + tx;

        if (w_row < N && w_col < K) {
            s_W[ty][tx] = W[w_row * K + w_col];
        } else {
            s_W[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product for this tile
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            // Dot product: row of X * row of W (which is col of W^T)
            // s_X[ty][k] gives element from current X row
            // s_W[tx][k] gives element from current W row (because we loaded W rows into s_W)
            // Note: s_W[tx] accesses the row in shared mem corresponding to global W row (bx*32 + tx)
            val += s_X[ty][k] * s_W[tx][k];
        }

        __syncthreads();
    }

    // Write result
    if (row < M && col < N) {
        // Add bias if present
        if (b != nullptr) {
            val += b[col];
        }

        // Fused ReLU
        if (use_relu) {
            val = fmaxf(val, 0.0f);
        }

        Y[row * N + col] = val;
    }
}

torch::Tensor linear_forward_cuda(torch::Tensor x, torch::Tensor w, torch::Tensor b, bool relu) {
    // Check inputs are on CUDA
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(w.is_cuda(), "w must be a CUDA tensor");
    if (b.defined()) {
        TORCH_CHECK(b.is_cuda(), "b must be a CUDA tensor");
    }

    int m = x.size(0);
    int k = x.size(1);
    int n = w.size(0); // W is (out_features, in_features)

    auto y = torch::empty({m, n}, x.options());

    // Block size 32x32 is standard for SGEMM
    const dim3 block_size(32, 32);
    const dim3 num_blocks((n + 31) / 32, (m + 31) / 32);

    linear_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        b.defined() ? b.data_ptr<float>() : nullptr,
        y.data_ptr<float>(),
        m, n, k,
        relu
    );

    return y;
}
