import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused Linear + ReLU
# This kernel implements a Tiled Matrix Multiplication (GEMM) optimized for 
# the dimensions provided (multiples of 32). It fuses the bias addition 
# and the ReLU activation into the GEMM kernel to reduce memory bandwidth.

cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_linear_relu_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int M, int N, int K,
    bool use_relu) {

    // Tile size
    const int BLOCK_SIZE = 32;

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Identify the row and column of the output matrix C to compute
    // Row corresponds to batch index
    // Col corresponds to output feature index
    int row = by * BLOCK_SIZE + ty;
    int col = bx * BLOCK_SIZE + tx;

    float val = 0.0f;

    // Shared memory for tiles
    // As stores a tile of Input (M x K)
    // Bs stores a tile of Weight (N x K)
    // We pad Bs column dimension to avoid bank conflicts during the dot product accumulation
    __shared__ float As[32][32];
    __shared__ float Bs[32][33];

    // Loop over the K dimension in chunks of BLOCK_SIZE
    for (int k = 0; k < K; k += BLOCK_SIZE) {

        // Load Input tile into shared memory
        // Each thread loads one element: Input[row, k + tx]
        // Boundary checks are good practice, though dimensions here are aligned
        if (row < M && (k + tx) < K) {
            As[ty][tx] = input[row * K + (k + tx)];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load Weight tile into shared memory
        // PyTorch Linear weights are stored as (OutFeatures, InFeatures) -> (N, K)
        // We compute C = X * W^T + b. 
        // We need the sub-block of W corresponding to output rows [col_start .. col_end]
        // Thread (ty, tx) helps load the tile.
        // We map shared memory rows to global W rows (output features).
        if ((bx * BLOCK_SIZE + ty) < N && (k + tx) < K) {
            Bs[ty][tx] = weight[(bx * BLOCK_SIZE + ty) * K + (k + tx)];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product for this tile
        // C[row, col] = Dot(Input[row, :], Weight[col, :])
        // Input row data is in As[ty, :]
        // Weight row data (for global col) is in Bs[tx, :] 
        // (Note: `col` depends on `tx`, and we loaded W rows into Bs rows, so we access Bs[tx])

        #pragma unroll
        for (int i = 0; i < BLOCK_SIZE; ++i) {
            val += As[ty][i] * Bs[tx][i];
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < M && col < N) {
        // Add bias
        if (bias != nullptr) {
            val += bias[col];
        }

        // Apply ReLU
        if (use_relu) {
            val = fmaxf(0.0f, val);
        }

        output[row * N + col] = val;
    }
}

torch::Tensor fused_linear_cuda(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, bool use_relu) {
    // Input: (M, K)
    // Weight: (N, K)
    // Bias: (N)

    int M = input.size(0);
    int K = input.size(1);
    int N = weight.size(0);

    auto output = torch::empty({M, N}, input.options());

    const int BLOCK_SIZE = 32;
    dim3 threads(BLOCK_SIZE, BLOCK_SIZE);
    dim3 blocks((N + BLOCK_SIZE - 1) / BLOCK_SIZE, (M + BLOCK_SIZE - 1) / BLOCK_SIZE);

    const float* bias_ptr = (bias.defined()) ? bias.data_ptr<float>() : nullptr;

    fused_linear_relu_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        M, N, K,
        use_relu
    );

    return output;
}
"""

cpp_source = """
