    // Process 4 floats at a time per thread
    int idx = (blockIdx.x * blockDim.x + threadIdx.x) * 4;
    if (idx < total_elements) {
        int col_idx = idx % cols;

        // Load data and bias as float4 for vectorized memory transactions
        float4 d = *reinterpret_cast<float4*>(&data[idx]);
        float4 b = *reinterpret_cast<const float4*>(&bias[col_idx]);

        // Perform fused Bias-Add and ReLU activation
        d.x = fmaxf(0.0f, d.x + b.x);
        d.y = fmaxf(0.0f, d.y + b.y);
        d.z = fmaxf(0.0f, d.z + b.z);
        d.w = fmaxf(0.0f, d.w + b.w);

        // Store the result back to memory
        *reinterpret_cast<float4*>(&data[idx]) = d;
    }
}

