    int idx = (blockIdx.x * blockDim.x + threadIdx.x) * 4;
    if (idx < total_elements) {
        int col_idx = idx % cols;

        float4 d = *reinterpret_cast<float4*>(&data[idx]);
        float4 b = *reinterpret_cast<const float4*>(&bias[col_idx]);

