# Define Custom CUDA Kernel for Fused Linear + ReLU
# This kernel implements a Tiled Matrix Multiplication (GEMM) fused with Bias addition and ReLU activation.
# It uses shared memory tiling to reduce global memory bandwidth usage.
# Padding in shared memory is used to avoid bank conflicts.

cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32

__global__ void linear_relu_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Out,
    int M, int K, int N,
    bool use_relu
) {
    // X: Shape (M, K)
    // W: Shape (N, K) - Standard PyTorch Linear layout
    // B: Shape (N)
    // Out: Shape (M, N)

    // Block indices
    int bx = blockIdx.x; // Corresponds to N dimension (Output Features)
    int by = blockIdx.y; // Corresponds to M dimension (Batch Size)

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global Row (M) and Col (N) indices
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    // Shared Memory with padding to avoid bank conflicts
    __shared__ float s_X[TILE_SIZE][TILE_SIZE + 1];
    __shared__ float s_W[TILE_SIZE][TILE_SIZE + 1];

    float val = 0.0f;

    // Loop over tiles along the K dimension
    int num_tiles = (K + TILE_SIZE - 1) / TILE_SIZE;

    for (int t = 0; t < num_tiles; ++t) {

        // 1. Load Tile from X into Shared Memory
        // We need X[row, current_k]. 
        // Coalesced load: threads with adjacent tx load adjacent columns.
        int k_col = t * TILE_SIZE + tx;
        if (row < M && k_col < K) {
            s_X[ty][tx] = X[row * K + k_col];
        } else {
            s_X[ty][tx] = 0.0f;
        }

        // 2. Load Tile from W into Shared Memory
        // W is stored as (N, K). We perform C = X * W^T.
        // We load a tile of W corresponding to rows (global output cols) and cols (global K).
        // Coalesced load: threads with adjacent tx load adjacent columns of W (K dimension).
        int w_row = bx * TILE_SIZE + ty;
        int w_col = t * TILE_SIZE + tx;

        if (w_row < N && w_col < K) {
            s_W[ty][tx] = W[w_row * K + w_col];
        } else {
            s_W[ty][tx] = 0.0f;
        }

        __syncthreads();

        // 3. Compute Partial Dot Product
        // We compute dot product of Row 'row' from X and Row 'col' from W.
        // Inside the tile:
        //   X element comes from s_X[ty][k]
        //   W element comes from s_W[tx][k] (because we loaded W rows into s_W rows, 
        //   and the thread 'tx' corresponds to the output column 'col' which is a row in W)

        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            val += s_X[ty][k] * s_W[tx][k];
