    int N = input_c.size(0);
    int C = input_c.size(1);
    int H = input_c.size(2);
    int W = input_c.size(3);
    int H_out = (H - 3) / 2 + 1;
    int W_out = (W - 3) / 2 + 1;

    auto output = torch::empty({N, C, H_out, W_out}, input_c.options());

    int total = N * C * H_out * W_out;
    const int block_size = 256;
    const int num_blocks = (total + block_size - 1) / block_size;

    relu_maxpool_3x3_s2_kernel<<<num_blocks, block_size>>>(
        input_c.data_ptr<float>(), output.data_ptr<float>(), N, C, H, W, H_out, W_out);

    return output;
}

torch::Tensor relu_inplace_cuda(torch::Tensor data) {
    if (!data.is_contiguous()) data = data.contiguous();
    int size = data.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
