__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch, int in_channels, int out_channels,
    int in_h, int in_w, int out_h, int out_w,
    int k_h, int k_w, int pad_h, int pad_w,
    int stride_h, int stride_w) {

    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch * out_channels * out_h * out_w;

    if (index < total_elements) {
        // Decode index to (n, c_out, h_out, w_out)
        int w_out_idx = index % out_w;
        int h_out_idx = (index / out_w) % out_h;
        int c_out_idx = (index / (out_w * out_h)) % out_channels;
        int n_idx = index / (out_w * out_h * out_channels);

        float sum = 0.0f;
        if (bias != nullptr) {
            sum = bias[c_out_idx];
        }

        for (int c_in = 0; c_in < in_channels; ++c_in) {
            for (int kh = 0; kh < k_h; ++kh) {
                for (int kw = 0; kw < k_w; ++kw) {
                    int h_in = h_out_idx * stride_h - pad_h + kh;
                    int w_in = w_out_idx * stride_w - pad_w + kw;

                    if (h_in >= 0 && h_in < in_h && w_in >= 0 && w_in < in_w) {
                        int input_offset = ((n_idx * in_channels + c_in) * in_h + h_in) * in_w + w_in;
                        int weight_offset = ((c_out_idx * in_channels + c_in) * k_h + kh) * k_w + kw;
                        sum += input[input_offset] * weight[weight_offset];
