    int n = blockIdx.x;
    int c = blockIdx.y;

    if (n >= N || c >= C) return;

    // Load channel-specific parameters once per block/channel
    float m = mean[c];
    float v = var[c];
    float w = weight[c];
    float b = bias[c];

    // Pre-calculate combined affine scale and shift
    // y = (x - mean) / sqrt(var + eps) * weight + bias
    // y = x * (weight * rsqrt(var + eps)) + (bias - mean * weight * rsqrt(var + eps))
