fused_relu_gap_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_relu_gap_kernel(const float* __restrict__ input, float* __restrict__ output, int total_channels, int hw) {
    // Each block calculates one channel for one sample.
    // blockIdx.x maps to linear index (n * C + c)
    int idx = blockIdx.x;
    if (idx >= total_channels) return;

    // Offset in the input tensor for this channel
    int offset = idx * hw;
    float sum = 0.0f;

    // Grid-stride loop over spatial dimensions (H * W)
    for (int i = threadIdx.x; i < hw; i += blockDim.x) {
        float val = input[offset + i];
        // Fused ReLU: only accumulate positive values
        if (val > 0.0f) {
            sum += val;
        }
    }

    // Block reduction using shared memory
    extern __shared__ float sdata[];
    int tid = threadIdx.x;
    sdata[tid] = sum;
    __syncthreads();

    // Standard reduction in shared memory (assumes blockDim.x is power of 2)
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    // Write average to output
    if (tid == 0) {
        output[idx] = sdata[0] / static_cast<float>(hw);
