bn_relu_cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_bn_relu_kernel(
    const float* __restrict__ input,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int numel,
    int C,
    int H,
    int W,
    float epsilon) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= numel) return;

    // Calculate indices
    // idx = n * (C * H * W) + c * (H * W) + (h * W + w)
    // We need 'c' to access the channel-specific parameters.

    int stride_hw = H * W;
    int stride_chw = C * stride_hw;

    // The channel index is derived from the offset within the current sample
    int c = (idx % stride_chw) / stride_hw;

    float val = input[idx];
    float m = mean[c];
    float v = var[c];
    float w = weight[c];
    float b = bias[c];

    // BatchNorm logic: y = (x - mean) / sqrt(var + eps) * weight + bias
    float inv_std = rsqrtf(v + epsilon);
    float norm = (val - m) * inv_std;
    float res = norm * w + b;

    // ReLU logic: y = max(0, y)
    output[idx] = res > 0.0f ? res : 0.0f;
}

