fused_relu_cat_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void relu_cat_kernel(const float* __restrict__ input1,
                                const float* __restrict__ input2,
                                float* __restrict__ output,
                                int N, int C1, int C2, int HW) {
    long long total_elements = (long long)N * (C1 + C2) * HW;
    long long idx = (long long)blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        long long hw_ll = (long long)HW;
        long long total_c_ll = (long long)(C1 + C2);

        int hw_idx = idx % hw_ll;
        int c_idx = (idx / hw_ll) % total_c_ll;
        int n_idx = idx / (hw_ll * total_c_ll);

        float val;
        if (c_idx < C1) {
            val = input1[((long long)n_idx * C1 + c_idx) * hw_ll + hw_idx];
        } else {
            val = input2[((long long)n_idx * C2 + (c_idx - C1)) * hw_ll + hw_idx];
        }
        output[idx] = val > 0.0f ? val : 0.0f;
    }
}

torch::Tensor fused_relu_cat_cuda(torch::Tensor input1, torch::Tensor input2) {
    auto in1 = input1.contiguous();
    auto in2 = input2.contiguous();

    int N = in1.size(0);
    int C1 = in1.size(1);
    int H = in1.size(2);
    int W = in1.size(3);
    int C2 = in2.size(1);
    int HW = H * W;

    auto options = torch::TensorOptions().device(in1.device()).dtype(in1.dtype());
    auto output = torch::empty({N, C1 + C2, H, W}, options);

    long long total_elements = (long long)N * (C1 + C2) * HW;

    const int block_size = 256;
    const long long num_blocks = (total_elements + block_size - 1) / block_size;

    relu_cat_kernel<<<num_blocks, block_size>>>(
        in1.data_ptr<float>(),
        in2.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C1, C2, HW
    );

    return output;
}
"""

fused_relu_cat_cpp_source = (
    "torch::Tensor fused_relu_cat_cuda(torch::Tensor input1, torch::Tensor input2);"
)

# Compile the inline CUDA code
fused_relu_cat_extension = load_inline(
    name="fused_relu_cat",
    cpp_sources=fused_relu_cat_cpp_source,
    cuda_sources=fused_relu_cat_cuda_source,
    functions=["fused_relu_cat_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, squeeze_channels, expand1x1_channels, expand3x3_channels):
        """
        :param in_channels: Number of input channels
        :param squeeze_channels: Number of output channels for the squeeze layer
        :param expand1x1_channels: Number of output channels for the 1x1 expand layer
        :param expand3x3_channels: Number of output channels for the 3x3 expand layer
        """
        super(ModelNew, self).__init__()

        self.squeeze = nn.Conv2d(in_channels, squeeze_channels, kernel_size=1)
        # Using functional ReLU in forward pass for simplicity and potentially in-place efficiency

        self.expand1x1 = nn.Conv2d(squeeze_channels, expand1x1_channels, kernel_size=1)
        self.expand3x3 = nn.Conv2d(squeeze_channels, expand3x3_channels, kernel_size=3, padding=1)

        # Access the custom fused operation
        self.fused_op = fused_relu_cat_extension

    def forward(self, x):
        """
        :param x: Input tensor, shape (batch_size, in_channels, height, width)
        :return: Output tensor, shape (batch_size, expand1x1_channels + expand3x3_channels, height, width)
        """
        # Squeeze branch with in-place ReLU
        x = F.relu(self.squeeze(x), inplace=True)

        # Expand branches (convolutions)
        e1 = self.expand1x1(x)
        e3 = self.expand3x3(x)

        # Fused ReLU and Concatenation
        # The custom kernel handles: output = cat([ReLU(e1), ReLU(e3)], dim=1)
        return self.fused_op.fused_relu_cat_cuda(e1, e3)

