#include <torch/extension.h>
#include <cuda_runtime.h>

// Kernel 1: Fused ReLU + Concatenation
// Takes two inputs (from expand1x1 and expand3x3), applies ReLU, 
// and writes them into a pre-allocated output tensor in the correct positions.
__global__ void fused_relu_concat_kernel(
    const float* __restrict__ input1,
    const float* __restrict__ input2,
    float* __restrict__ output,
    int total_elements,
    int stride_out,   // (C1 + C2) * H * W
    int stride_1,     // C1 * H * W
    int stride_2      // C2 * H * W
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        // Determine which sample (n) and which offset within the sample we are at
        int sample_idx = idx / stride_out;
        int offset = idx % stride_out;

        float val;
        // The output layout for one sample is [Channel1_Data | Channel2_Data]
        if (offset < stride_1) {
            // We are in the section corresponding to Input 1
            // idx in input1 = sample_idx * stride_1 + offset
            val = input1[sample_idx * stride_1 + offset];
        } else {
            // We are in the section corresponding to Input 2
            // idx in input2 = sample_idx * stride_2 + (offset - stride_1)
            val = input2[sample_idx * stride_2 + (offset - stride_1)];
        }

        // Fused ReLU
        val = (val > 0.0f) ? val : 0.0f;

        output[idx] = val;
    }
}

torch::Tensor fused_relu_concat_cuda(torch::Tensor input1, torch::Tensor input2) {
    // Ensure inputs are contiguous
    input1 = input1.contiguous();
    input2 = input2.contiguous();

    int N = input1.size(0);
    int C1 = input1.size(1);
    int H = input1.size(2);
    int W = input1.size(3);
    int C2 = input2.size(1);

    // Output shape
    auto output = torch::empty({N, C1 + C2, H, W}, input1.options());

    int stride_1 = C1 * H * W;
    int stride_2 = C2 * H * W;
    int stride_out = (C1 + C2) * H * W;
    int total_elements = N * stride_out;

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

