        input1.data_ptr<float>(),
        input2.data_ptr<float>(),
        output.data_ptr<float>(),
        total_elements,
        stride_out,
        stride_1,
        stride_2
    );

    return output;
}

// Kernel 2: Global Average Pooling
// Reduces (N, C, H, W) -> (N, C) directly
__global__ void global_avg_pool_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int n_channels_total, // N * C
    int spatial_size      // H * W
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n_channels_total) {
        const float* in_ptr = input + idx * spatial_size;
        float sum = 0.0f;
        for (int i = 0; i < spatial_size; ++i) {
            sum += in_ptr[i];
        }
        output[idx] = sum / float(spatial_size);
    }
}

torch::Tensor global_avg_pool_cuda(torch::Tensor input) {
    input = input.contiguous();
    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int spatial_size = H * W;

    auto output = torch::empty({N, C}, input.options());

    int total_threads = N * C;
    const int block_size = 256;
    const int num_blocks = (total_threads + block_size - 1) / block_size;

    global_avg_pool_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        total_threads,
