import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Helper for finding max
__device__ __forceinline__ float relu(float x) {
    return x > 0.0f ? x : 0.0f;
}

__global__ void fused_bn_relu_kernel(
    const float* __restrict__ x,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ y,
    int N, int C, int H, int W) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int numel = N * C * H * W;

    if (idx < numel) {
        int hw_size = H * W;
        int c = (idx / hw_size) % C;

        float val = x[idx];
        float m = mean[c];
        float v = var[c];
        float w = weight[c];
        float b = bias[c];

        // BN: (x - mean) / sqrt(var + eps) * weight + bias
        float inv_std = rsqrtf(v + 1e-5f);
        float norm = (val - m) * inv_std;
        float bn_out = norm * w + b;

        // ReLU
        y[idx] = relu(bn_out);
    }
}

__global__ void fused_dw_conv_bn_relu_kernel(
    const float* __restrict__ input,
    const float* __restrict__ conv_weights, // [C, 1, 3, 3]
    const float* __restrict__ bn_mean,
    const float* __restrict__ bn_var,
    const float* __restrict__ bn_weight,
    const float* __restrict__ bn_bias,
    float* __restrict__ output,
    int N, int C, int H_in, int W_in,
    int H_out, int W_out,
    int stride, int padding) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int numel = N * C * H_out * W_out;

    if (idx < numel) {
        int w_out = idx % W_out;
        int h_out = (idx / W_out) % H_out;
        int c = (idx / (W_out * H_out)) % C;
        int n = idx / (W_out * H_out * C);

        float sum = 0.0f;
        int h_in_start = h_out * stride - padding;
        int w_in_start = w_out * stride - padding;

        // Depthwise convolution 3x3
        // Weight shape [C, 1, 3, 3] -> Flattened logic.
        // Since groups=C, each channel c convolving with its own 3x3 filter.
        int weight_offset = c * 9;

        #pragma unroll
        for (int i = 0; i < 3; ++i) {
            #pragma unroll
            for (int j = 0; j < 3; ++j) {
                int h_in = h_in_start + i;
                int w_in = w_in_start + j;

                if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                    // Input index: n, c, h_in, w_in
                    int input_idx = ((n * C + c) * H_in + h_in) * W_in + w_in;
                    float val = input[input_idx];
                    float w = conv_weights[weight_offset + i * 3 + j];
                    sum += val * w;
                }
            }
        }

        // BN + ReLU
        float m = bn_mean[c];
        float v = bn_var[c];
        float bw = bn_weight[c]; // gamma
        float bb = bn_bias[c];   // beta

        float inv_std = rsqrtf(v + 1e-5f);
        float norm = (sum - m) * inv_std;
        float bn_res = norm * bw + bb;

        output[idx] = relu(bn_res);
    }
}

torch::Tensor fused_bn_relu_cuda(torch::Tensor x, torch::Tensor mean, torch::Tensor var, torch::Tensor weight, torch::Tensor bias) {
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    auto y = torch::empty_like(x);
    int numel = N * C * H * W;

    const int block_size = 256;
    const int num_blocks = (numel + block_size - 1) / block_size;

    fused_bn_relu_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        y.data_ptr<float>(),
        N, C, H, W
    );

    return y;
}

torch::Tensor fused_dw_conv_bn_relu_cuda(
    torch::Tensor input, 
    torch::Tensor conv_weights, 
    torch::Tensor bn_mean, 
    torch::Tensor bn_var, 
    torch::Tensor bn_weight, 
    torch::Tensor bn_bias, 
    int stride, int padding) {

    int N = input.size(0);
    int C = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    int H_out = (H_in + 2 * padding - 3) / stride + 1;
    int W_out = (W_in + 2 * padding - 3) / stride + 1;

    auto output = torch::empty({N, C, H_out, W_out}, input.options());

    int numel = N * C * H_out * W_out;
    const int block_size = 256;
    const int num_blocks = (numel + block_size - 1) / block_size;

    fused_dw_conv_bn_relu_kernel<<<num_blocks, block_size>>>(
