        output.data_ptr<float>(),
        N, C, H_in, W_in, H_out, W_out, stride, padding
    );

    return output;
}
"""

cpp_source = """
torch::Tensor fused_bn_relu_cuda(torch::Tensor x, torch::Tensor mean, torch::Tensor var, torch::Tensor weight, torch::Tensor bias);
torch::Tensor fused_dw_conv_bn_relu_cuda(torch::Tensor input, torch::Tensor conv_weights, torch::Tensor bn_mean, torch::Tensor bn_var, torch::Tensor bn_weight, torch::Tensor bn_bias, int stride, int padding);
"""

cuda_ops = load_inline(
    name="cuda_ops",
    cpp_sources=cpp_source,
