class FusedBnReLU(nn.Module):
    def __init__(self, num_features):
        super(FusedBnReLU, self).__init__()
        self.num_features = num_features
        self.weight = nn.Parameter(torch.Tensor(num_features))
        self.bias = nn.Parameter(torch.Tensor(num_features))
        self.register_buffer('running_mean', torch.zeros(num_features))
        self.register_buffer('running_var', torch.ones(num_features))
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.ones_(self.weight)
        nn.init.zeros_(self.bias)

    def forward(self, x):
        return cuda_ops.fused_bn_relu_cuda(x, self.running_mean, self.running_var, self.weight, self.bias)

class FusedDepthwiseConvBnReLU(nn.Module):
    def __init__(self, channels, stride):
        super(FusedDepthwiseConvBnReLU, self).__init__()
        self.channels = channels
        self.stride = stride
        self.padding = 1

        # Depthwise weights: [C, 1, 3, 3]
        self.conv_weight = nn.Parameter(torch.Tensor(channels, 1, 3, 3))

        # BN params
        self.bn_weight = nn.Parameter(torch.Tensor(channels))
        self.bn_bias = nn.Parameter(torch.Tensor(channels))
        self.register_buffer('bn_running_mean', torch.zeros(channels))
        self.register_buffer('bn_running_var', torch.ones(channels))

