# 2. fused_bn_relu: Element-wise BatchNorm + ReLU fusion for other convolutions
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void dw_3x3_bn_relu_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ output,
    int batch, int channels, int in_h, int in_w,
    int out_h, int out_w, int stride, float eps) {

    int out_hw = out_h * out_w;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int b_c = blockIdx.z;
    int b = b_c / channels;
    int c = b_c % channels;

    if (idx < out_hw) {
        int oh = idx / out_w;
        int ow = idx % out_w;

        float sum = 0.0f;
        int ih_start = oh * stride - 1;
        int iw_start = ow * stride - 1;

        for (int kh = 0; kh < 3; kh++) {
            int ih = ih_start + kh;
            if (ih >= 0 && ih < in_h) {
                for (int kw = 0; kw < 3; kw++) {
                    int iw = iw_start + kw;
                    if (iw >= 0 && iw < in_w) {
                        sum += input[((b * channels + c) * in_h + ih) * in_w + iw] * weight[c * 9 + kh * 3 + kw];
                    }
                }
            }
        }

        float m = mean[c];
        float v = var[c];
        float g = gamma[c];
        float be = beta[c];
        float res = (sum - m) * rsqrtf(v + eps) * g + be;
        output[((b * channels + c) * out_h + oh) * out_w + ow] = res > 0.0f ? res : 0.0f;
    }
}

__global__ void bn_relu_kernel(
    const float* __restrict__ input,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ output,
    int batch, int channels, int hw, float eps) {

    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int b_c = blockIdx.z;
    int b = b_c / channels;
    int c = b_c % channels;

    if (i < hw) {
        int idx = (b * channels + c) * hw + i;
        float val = input[idx];
        float res = (val - mean[c]) * rsqrtf(var[c] + eps) * gamma[c] + beta[c];
        output[idx] = res > 0.0f ? res : 0.0f;
    }
}

torch::Tensor dw_3x3_bn_relu_cuda(
