// ReLU6 Kernel: y = min(max(x, 0), 6)
__global__ void relu6_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        output[idx] = fminf(fmaxf(x, 0.0f), 6.0f);
    }
}

torch::Tensor relu6_cuda(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int size = input.numel();
    const int block_size = 512;
    const int num_blocks = (size + block_size - 1) / block_size;

    relu6_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), size);

    return output;
}

// Global Average Pooling Kernel: reduces (N, C, H, W) -> (N, C, 1, 1)
__global__ void global_avg_pool_kernel(const float* __restrict__ input, float* __restrict__ output, 
                                       int n, int c, int h, int w) {
    // Each thread calculates the average for one channel of one image (one (n, c) pair)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_channels = n * c;

    if (idx < total_channels) {
        int img_idx = idx / c;
        int channel_idx = idx % c;

        // Calculate pointer offset: n * (C*H*W) + c * (H*W)
        int offset = (img_idx * c * h * w) + (channel_idx * h * w);
        const float* in_ptr = input + offset;

        float sum = 0.0f;
        int num_pixels = h * w;

        // Sum all pixels in the feature map
        for (int i = 0; i < num_pixels; ++i) {
            sum += in_ptr[i];
        }

        output[idx] = sum / (float)num_pixels;
    }
}

torch::Tensor gap_cuda(torch::Tensor input) {
    // Input shape: (N, C, H, W)
    int n = input.size(0);
    int c = input.size(1);
    int h = input.size(2);
    int w = input.size(3);

    // Output shape: (N, C, 1, 1)
    auto output = torch::empty({n, c, 1, 1}, input.options());

    int total_tasks = n * c;
    const int block_size = 256;
    const int num_blocks = (total_tasks + block_size - 1) / block_size;

    global_avg_pool_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        n, c, h, w
    );

