import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

#define CEIL_DIV(x, y) (((x) + (y) - 1) / (y))

// ----------------------------------------------------------------------------
// 1. Fused BatchNorm + Activation Kernel
//    Performs: x = (x - mean) / sqrt(var + eps) * gamma + beta
//    Optional: x = clamp(x, 0, 6) if use_relu6 is true
//    Operates in-place on x
// ----------------------------------------------------------------------------
__global__ void fused_bn_kernel(
    float* __restrict__ x,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    int N, int C, int H, int W,
    float eps,
    int use_relu6) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride_hw = H * W;
    int stride_chw = C * stride_hw;
    int total_elements = N * stride_chw;

    if (idx < total_elements) {
        // Calculate channel index from linear index
        // idx = n * (C*H*W) + c * (H*W) + hw
        int rem = idx % stride_chw;
        int c = rem / stride_hw;

        float val = x[idx];
        float m = mean[c];
        float v = var[c];
        float g = gamma[c];
        float b = beta[c];

        // Batch Norm
        float inv_std = rsqrtf(v + eps);
        val = (val - m) * inv_std * g + b;

        // ReLU6
        if (use_relu6) {
            val = fmaxf(0.0f, fminf(val, 6.0f));
        }

        x[idx] = val;
    }
}

void fused_bn_cuda(
    torch::Tensor x,
    torch::Tensor mean,
    torch::Tensor var,
    torch::Tensor gamma,
    torch::Tensor beta,
    float eps,
    bool use_relu6) {

    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int total_elements = x.numel();

    const int block_size = 256;
    const int num_blocks = CEIL_DIV(total_elements, block_size);

    fused_bn_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        N, C, H, W, eps,
        use_relu6 ? 1 : 0
    );
}

// ----------------------------------------------------------------------------
// 2. Depthwise Convolution Kernel
//    Naive implementation for arbitrary kernel/stride/padding.
//    Assumes groups == in_channels == out_channels.
// ----------------------------------------------------------------------------
__global__ void depthwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int N, int C, int H_in, int W_in,
    int H_out, int W_out,
    int K, int stride, int padding) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H_out * W_out;

    if (idx < total_elements) {
        int w_out_idx = idx % W_out;
        int tmp = idx / W_out;
        int h_out_idx = tmp % H_out;
        tmp = tmp / H_out;
        int c = tmp % C;
        int n = tmp / C;

        // Base offsets
        int input_offset_base = n * C * H_in * W_in + c * H_in * W_in;
        int weight_offset_base = c * K * K;

        float sum = 0.0f;

        for (int kh = 0; kh < K; ++kh) {
            for (int kw = 0; kw < K; ++kw) {
                int h_in = h_out_idx * stride - padding + kh;
                int w_in = w_out_idx * stride - padding + kw;

                if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                    float val = input[input_offset_base + h_in * W_in + w_in];
                    float w = weight[weight_offset_base + kh * K + kw];
                    sum += val * w;
                }
            }
        }
        output[idx] = sum;
    }
}

torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int kernel_size,
    int stride,
    int padding) {

    int N = input.size(0);
    int C = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    int H_out = (H_in + 2 * padding - kernel_size) / stride + 1;
    int W_out = (W_in + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::zeros({N, C, H_out, W_out}, input.options());

    int total_elements = N * C * H_out * W_out;
    const int block_size = 256;
    const int num_blocks = CEIL_DIV(total_elements, block_size);

    depthwise_conv2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H_in, W_in,
        H_out, W_out,
        kernel_size, stride, padding
    );

    return output;
}

// ----------------------------------------------------------------------------
// 3. Elementwise Add Kernel (Residual)
// ----------------------------------------------------------------------------
__global__ void add_kernel(const float* a, const float* b, float* out, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto out = torch::empty_like(a);
    int n = a.numel();
    const int block_size = 256;
    const int num_blocks = CEIL_DIV(n, block_size);
    add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), n);
    return out;
}
"""

cpp_source = """
void fused_bn_cuda(torch::Tensor x, torch::Tensor mean, torch::Tensor var, torch::Tensor gamma, torch::Tensor beta, float eps, bool use_relu6);
torch::Tensor depthwise_conv2d_cuda(torch::Tensor input, torch::Tensor weight, int kernel_size, int stride, int padding);
torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);
"""

# Compile the inline CUDA code
mbconv_ops = load_inline(
    name='mbconv_ops',
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=['fused_bn_cuda', 'depthwise_conv2d_cuda', 'elementwise_add_cuda'],
    verbose=True,
    extra_cflags=['-O3'],
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, expand_ratio):
        super(ModelNew, self).__init__()

        self.use_residual = (stride == 1 and in_channels == out_channels)
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = (kernel_size - 1) // 2
        hidden_dim = in_channels * expand_ratio

        # Expand Phase
        if expand_ratio != 1:
            self.expand_conv_c = nn.Conv2d(in_channels, hidden_dim, kernel_size=1, stride=1, padding=0, bias=False)
            self.expand_bn = nn.BatchNorm2d(hidden_dim)
            # ReLU6 is fused

        # Depthwise Phase
        # We keep the Conv2d to hold weights, but use custom op
        self.depthwise_conv_c = nn.Conv2d(hidden_dim, hidden_dim, kernel_size=kernel_size, stride=stride, padding=self.padding, groups=hidden_dim, bias=False)
        self.depthwise_bn = nn.BatchNorm2d(hidden_dim)
        # ReLU6 is fused

        # Project Phase
        self.project_conv_c = nn.Conv2d(hidden_dim, out_channels, kernel_size=1, stride=1, padding=0, bias=False)
        self.project_bn = nn.BatchNorm2d(out_channels)
        # No ReLU here

        self.ops = mbconv_ops

    def forward(self, x):
        identity = x

        # 1. Expand Phase (if needed)
        if hasattr(self, 'expand_conv_c'):
            # Standard 1x1 Conv (cuBLAS is fast)
            x = self.expand_conv_c(x)

            # Custom Fused BN + ReLU6
            # Note: fused_bn_cuda operates in-place
            self.ops.fused_bn_cuda(
                x, 
                self.expand_bn.running_mean, 
                self.expand_bn.running_var, 
                self.expand_bn.weight, 
                self.expand_bn.bias, 
                self.expand_bn.eps, 
                True # use_relu6
            )

        # 2. Depthwise Phase
        # Custom Depthwise Conv
        x = x.contiguous()
        x = self.ops.depthwise_conv2d_cuda(
            x, 
            self.depthwise_conv_c.weight, 
            self.kernel_size, 
            self.stride, 
            self.padding
        )

        # Custom Fused BN + ReLU6
        self.ops.fused_bn_cuda(
            x, 
            self.depthwise_bn.running_mean, 
            self.depthwise_bn.running_var, 
            self.depthwise_bn.weight, 
            self.depthwise_bn.bias, 
            self.depthwise_bn.eps, 
            True # use_relu6
        )

        # 3. Project Phase
        # Standard 1x1 Conv
        x = self.project_conv_c(x)

        # Custom Fused BN (No ReLU)
        self.ops.fused_bn_cuda(
            x, 
            self.project_bn.running_mean, 
            self.project_bn.running_var, 
            self.project_bn.weight, 
            self.project_bn.bias, 
            self.project_bn.eps, 
            False # use_relu6
        )

        # 4. Residual
        if self.use_residual:
            x = self.ops.elementwise_add_cuda(x, identity)

        return x

