    const int blocks = (total + threads - 1) / threads;

    bn_relu6_kernel<<<blocks, threads>>>(
        input.contiguous().data_ptr<float>(), 
        scale.contiguous().data_ptr<float>(), 
        bias.contiguous().data_ptr<float>(), 
        output.data_ptr<float>(), 
        n, c, h, w
    );
    return output;
}

torch::Tensor fused_bn_add_cuda(torch::Tensor input, torch::Tensor scale, torch::Tensor bias, torch::Tensor identity, bool use_res) {
    auto output = torch::empty_like(input);
    int n = input.size(0);
    int c = input.size(1);
