class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, expand_ratio):
        super(ModelNew, self).__init__()

        self.use_residual = (stride == 1 and in_channels == out_channels)
        hidden_dim = in_channels * expand_ratio

        if expand_ratio != 1:
            self.expand_conv = nn.Sequential(
                nn.Conv2d(in_channels, hidden_dim, kernel_size=1, stride=1, padding=0, bias=False),
                nn.BatchNorm2d(hidden_dim),
                nn.ReLU6(inplace=True)
            )

        self.depthwise_conv = nn.Sequential(
            nn.Conv2d(hidden_dim, hidden_dim, kernel_size=kernel_size, stride=stride, padding=(kernel_size-1)//2, groups=hidden_dim, bias=False),
            nn.BatchNorm2d(hidden_dim),
            nn.ReLU6(inplace=True)
        )

        self.project_conv = nn.Sequential(
            nn.Conv2d(hidden_dim, out_channels, kernel_size=1, stride=1, padding=0, bias=False),
            nn.BatchNorm2d(out_channels)
        )

        self.fused_ops = fused_ops

    def fused_bn_apply(self, x, bn, relu6=False, identity=None):
        # Fallback to standard PyTorch if on CPU or training
        if not x.is_cuda or bn.training:
            x = bn(x)
            if relu6:
                x = F.relu6(x)
            if identity is not None:
                x = x + identity
            return x

        # Optimized fused CUDA path for inference
        scale = bn.weight / torch.sqrt(bn.running_var + bn.eps)
        bias = bn.bias - bn.running_mean * scale

        if relu6:
            return self.fused_ops.fused_bn_relu6_cuda(x, scale, bias)
        else:
            use_res = identity is not None
            return self.fused_ops.fused_bn_add_cuda(x, scale, bias, identity if use_res else x, use_res)

    def forward(self, x):
        identity = x

        if hasattr(self, 'expand_conv'):
            # Expand stage: Conv2d + Fused(BN + ReLU6)
            x = self.expand_conv[0](x)
            x = self.fused_bn_apply(x, self.expand_conv[1], relu6=True)

        # Depthwise stage: Conv2d + Fused(BN + ReLU6)
        x = self.depthwise_conv[0](x)
        x = self.fused_bn_apply(x, self.depthwise_conv[1], relu6=True)

        # Project stage: Conv2d + Fused(BN [+ Residual Add])
        x = self.project_conv[0](x)
        x = self.fused_bn_apply(x, self.project_conv[1], relu6=False, identity=identity if self.use_residual else None)

        return x

