import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# -----------------------------------------------------------------------------
# Custom CUDA Kernels
# -----------------------------------------------------------------------------

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// CUDA kernel for ReLU6: fminf(fmaxf(x, 0), 6)
__global__ void relu6_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        output[idx] = fminf(fmaxf(val, 0.0f), 6.0f);
    }
}

// CUDA kernel for standard ReLU: fmaxf(x, 0)
__global__ void relu_kernel(const float* __restrict__ input, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        output[idx] = fmaxf(val, 0.0f);
    }
}

// CUDA kernel for element-wise addition (Residual connection)
__global__ void add_kernel(const float* __restrict__ a, const float* __restrict__ b, float* __restrict__ output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        output[idx] = a[idx] + b[idx];
    }
}

torch::Tensor cuda_relu6(torch::Tensor input) {
    // Ensure input is contiguous
    auto input_contig = input.contiguous();
    auto output = torch::empty_like(input_contig);
    int size = input_contig.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    relu6_kernel<<<num_blocks, block_size>>>(
        input_contig.data_ptr<float>(), 
        output.data_ptr<float>(), 
        size
    );

    return output;
}

torch::Tensor cuda_relu(torch::Tensor input) {
    auto input_contig = input.contiguous();
    auto output = torch::empty_like(input_contig);
    int size = input_contig.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    relu_kernel<<<num_blocks, block_size>>>(
        input_contig.data_ptr<float>(), 
        output.data_ptr<float>(), 
        size
    );

    return output;
}

torch::Tensor cuda_add(torch::Tensor a, torch::Tensor b) {
    auto a_contig = a.contiguous();
    auto b_contig = b.contiguous();
    auto output = torch::empty_like(a_contig);
    int size = a_contig.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    add_kernel<<<num_blocks, block_size>>>(
        a_contig.data_ptr<float>(), 
        b_contig.data_ptr<float>(), 
        output.data_ptr<float>(), 
        size
    );

    return output;
}
"""

cpp_source = """
torch::Tensor cuda_relu6(torch::Tensor input);
torch::Tensor cuda_relu(torch::Tensor input);
torch::Tensor cuda_add(torch::Tensor a, torch::Tensor b);
"""

# Compile and load the custom kernels
cuda_ops = load_inline(
    name="efficientnet_cuda_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["cuda_relu6", "cuda_relu", "cuda_add"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)

# -----------------------------------------------------------------------------
# Custom Modules
# -----------------------------------------------------------------------------

class CustomReLU6(nn.Module):
    def __init__(self, inplace=False):
        super(CustomReLU6, self).__init__()
        # inplace is typically used to save memory, but for this demonstration
        # we focus on the custom kernel execution which returns a new tensor.

    def forward(self, x):
        return cuda_ops.cuda_relu6(x)

class CustomReLU(nn.Module):
    def __init__(self):
        super(CustomReLU, self).__init__()

    def forward(self, x):
        return cuda_ops.cuda_relu(x)

# -----------------------------------------------------------------------------
# Optimized Architecture
# -----------------------------------------------------------------------------

class MBConvNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, expand_ratio):
        """
        MBConv block implementation with custom CUDA operators.
        """
        super(MBConvNew, self).__init__()

        self.use_residual = (stride == 1 and in_channels == out_channels)
        hidden_dim = in_channels * expand_ratio

        if expand_ratio != 1:
            self.expand_conv = nn.Sequential(
                nn.Conv2d(in_channels, hidden_dim, kernel_size=1, stride=1, padding=0, bias=False),
                nn.BatchNorm2d(hidden_dim),
                CustomReLU6(inplace=True)  # Replaced nn.ReLU6
            )

        self.depthwise_conv = nn.Sequential(
            nn.Conv2d(hidden_dim, hidden_dim, kernel_size=kernel_size, stride=stride, padding=(kernel_size-1)//2, groups=hidden_dim, bias=False),
            nn.BatchNorm2d(hidden_dim),
            CustomReLU6(inplace=True)  # Replaced nn.ReLU6
        )

        self.project_conv = nn.Sequential(
            nn.Conv2d(hidden_dim, out_channels, kernel_size=1, stride=1, padding=0, bias=False),
            nn.BatchNorm2d(out_channels)
        )

    def forward(self, x):
        identity = x

        if hasattr(self, 'expand_conv'):
            x = self.expand_conv(x)

        x = self.depthwise_conv(x)
        x = self.project_conv(x)

        if self.use_residual:
            # Replaced Python/Torch addition with Custom CUDA Kernel
            x = cuda_ops.cuda_add(x, identity)

        return x

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        """
        Optimized EfficientNetB0 architecture implementation using Custom CUDA operators.
        """
        super(ModelNew, self).__init__()

        # Initial convolutional layer
        self.conv1 = nn.Conv2d(3, 32, kernel_size=3, stride=2, padding=1, bias=False)
        self.bn1 = nn.BatchNorm2d(32)

        # Instance of custom ReLU for the main model body
        self.relu = CustomReLU()

        # MBConv blocks
        self.blocks = nn.Sequential(
            MBConvNew(32, 16, kernel_size=3, stride=1, expand_ratio=1),
            MBConvNew(16, 24, kernel_size=3, stride=2, expand_ratio=6),
            MBConvNew(24, 24, kernel_size=3, stride=1, expand_ratio=6),
            MBConvNew(24, 40, kernel_size=5, stride=2, expand_ratio=6),
            MBConvNew(40, 40, kernel_size=5, stride=1, expand_ratio=6),
            MBConvNew(40, 80, kernel_size=3, stride=2, expand_ratio=6),
            MBConvNew(80, 80, kernel_size=3, stride=1, expand_ratio=6),
            MBConvNew(80, 112, kernel_size=5, stride=1, expand_ratio=6),
            MBConvNew(112, 112, kernel_size=5, stride=1, expand_ratio=6),
            MBConvNew(112, 192, kernel_size=5, stride=2, expand_ratio=6),
            MBConvNew(192, 192, kernel_size=5, stride=1, expand_ratio=6),
            MBConvNew(192, 192, kernel_size=5, stride=1, expand_ratio=6),
            MBConvNew(192, 320, kernel_size=3, stride=1, expand_ratio=6)
        )

        # Final convolutional layer
        self.conv2 = nn.Conv2d(320, 1280, kernel_size=1, stride=1, padding=0, bias=False)
        self.bn2 = nn.BatchNorm2d(1280)

        # Fully connected layer
        self.fc = nn.Linear(1280, num_classes)

    def forward(self, x):
        """
        Forward pass of the Optimized EfficientNetB0 model.
        """
        # Using CustomReLU
        x = self.relu(self.bn1(self.conv1(x)))
        x = self.blocks(x)
        # Using CustomReLU
        x = self.relu(self.bn2(self.conv2(x)))
        x = F.adaptive_avg_pool2d(x, (1, 1))
        x = x.view(x.size(0), -1)
        x = self.fc(x)
        return x

