// CUDA Kernel for Global Average Pooling: (N, C, H, W) -> (N, C, 1, 1)
// Optimized for cases where H*W is small enough to loop efficiently within a single thread (common in late CNN layers)
__global__ void global_avg_pool_kernel(const float* __restrict__ input, float* __restrict__ output, int N, int C, int H, int W) {
