        // Output layout after transpose is (N, C_prime, G, H, W)
        // Linear index in output: idx = n*(C_prime*G*HW) + cp*(G*HW) + g*HW + hw
        int hw = idx % HW;
        int rem = idx / HW;
        int g = rem % G;
        int cp = (rem / G) % C_prime;
        int n = rem / (G * C_prime);

        // Original layout was (N, G, C_prime, H, W)
        // Corresponding input index: src_idx = n*(G*C_prime*HW) + g*(C_prime*HW) + cp*HW + hw
