// Performs ReLU activation followed by MaxPool2d (kernel_size=2, stride=2)
// Input shape: (N, C, H, W)
// Output shape: (N, C, H/2, W/2)
__global__ void fused_relu_maxpool_kernel(
    const float* __restrict__ input, 
    float* __restrict__ output,
    int n, int c, int h, int w,
    int out_h, int out_w) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = n * c * out_h * out_w;

    if (idx < total_elements) {
        // Calculate output coordinates from linear index
        int ow = idx % out_w;
