        int input_offset = (in * c + ic) * h * w;

        // Starting coordinates of the 2x2 pooling window
        int h_start = oh * 2;
        int w_start = ow * 2;

        // Initialize max value. Since we apply ReLU first, the minimum possible value is 0.0.
        float max_val = 0.0f; 

        // Iterate over the 2x2 window
        #pragma unroll
        for (int i = 0; i < 2; ++i) {
            #pragma unroll
            for (int j = 0; j < 2; ++j) {
                int cur_h = h_start + i;
                int cur_w = w_start + j;

