// Kernel to extract patches from the image and flatten them directly
// Replaces img.unfold(...).unfold(...).reshape(...)
__global__ void patchify_kernel(const float* __restrict__ img, float* __restrict__ out,
                                int batch_size, int channels, int height, int width, int patch_size,
                                int num_patches_h, int num_patches_w) {
    int patch_dim = channels * patch_size * patch_size;
    int num_patches = num_patches_h * num_patches_w;
    int total_elements = batch_size * num_patches * patch_dim;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_elements) return;

    // Map linear index to output tensor coordinates: (b, p_idx, val_idx)
    // Output shape: (Batch, NumPatches, PatchDim)
    int val_idx = idx % patch_dim;
    int tmp = idx / patch_dim;
    int p_idx = tmp % num_patches;
    int b = tmp / num_patches;

    // Map patch index to spatial grid coordinates (pr, pc)
    int pr = p_idx / num_patches_w;
    int pc = p_idx % num_patches_w;

    // Map value index to (c, dy, dx) within the patch
    // Layout: Channel-major inside patch (C, P, P)
    int area = patch_size * patch_size;
    int c = val_idx / area;
    int rem = val_idx % area;
    int dy = rem / patch_size;
    int dx = rem % patch_size;

