    int in_y = pr * patch_size + dy;
    int in_x = pc * patch_size + dx;

    // Calculate flat input index for (B, C, H, W)
    int hw = height * width;
    int in_idx = b * (channels * hw) + c * hw + in_y * width + in_x;

