    const int num_blocks = (total_elements + block_size - 1) / block_size;

    patchify_kernel<<<num_blocks, block_size>>>(img.data_ptr<float>(), out.data_ptr<float>(),
                                                B, C, H, W, patch_size, n_ph, n_pw);
    return out;
}

// Kernel for broadcasting addition of positional embeddings
// Replaces x += self.pos_embedding
__global__ void add_pos_kernel(float* __restrict__ x, const float* __restrict__ pos, int size, int pos_len) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        x[idx] += pos[idx % pos_len];
    }
}

void add_pos_embed_cuda(torch::Tensor x, torch::Tensor pos) {
    int size = x.numel();
    int pos_len = pos.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    add_pos_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), pos.data_ptr<float>(), size, pos_len);
}

// Kernel for GELU activation approximation
// Replaces nn.GELU()
__global__ void gelu_kernel(const float* __restrict__ x, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        float cube = val * val * val;
        // Approximation: 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
        // sqrt(2/pi) approx 0.7978845608
        float inner = 0.7978845608f * (val + 0.044715f * cube);
        out[idx] = 0.5f * val * (1.0f + tanhf(inner));
    }
}

torch::Tensor gelu_cuda(torch::Tensor x) {
    auto out = torch::empty_like(x);
    int size = x.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    gelu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}
