import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernels for LayerNorm and GELU
custom_ops_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void gelu_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        // 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
        output[idx] = 0.5f * x * (1.0f + tanhf(0.79788456f * (x + 0.044715f * x * x * x)));
    }
}

__global__ void layernorm_kernel(const float* __restrict__ input, const float* __restrict__ gamma, const float* __restrict__ beta, float* __restrict__ output, int N, int D, float eps) {
    int row = blockIdx.x;
    if (row >= N) return;

    extern __shared__ float s_mem[];
    float* shared_data = s_mem;

    float row_sum = 0;
    for (int i = threadIdx.x; i < D; i += blockDim.x) {
        row_sum += input[row * D + i];
    }

    shared_data[threadIdx.x] = row_sum;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) shared_data[threadIdx.x] += shared_data[threadIdx.x + s];
        __syncthreads();
    }
    float mean = shared_data[0] / D;
    __syncthreads();

    float row_sq_sum = 0;
    for (int i = threadIdx.x; i < D; i += blockDim.x) {
        float diff = input[row * D + i] - mean;
        row_sq_sum += diff * diff;
    }
    shared_data[threadIdx.x] = row_sq_sum;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) shared_data[threadIdx.x] += shared_data[threadIdx.x + s];
        __syncthreads();
    }
    float var = shared_data[0] / D;
    float inv_std = rsqrtf(var + eps);

    for (int i = threadIdx.x; i < D; i += blockDim.x) {
        output[row * D + i] = (input[row * D + i] - mean) * inv_std * gamma[i] + beta[i];
    }
}

torch::Tensor gelu_cuda(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int size = input.numel();
    int threads = 256;
    int blocks = (size + threads - 1) / threads;
    gelu_kernel<<<blocks, threads>>>(input.data_ptr<float>(), output.data_ptr<float>(), size);
    return output;
}

torch::Tensor layernorm_cuda(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta, float eps) {
    auto output = torch::empty_like(input);
    int D = input.size(-1);
    int N = input.numel() / D;
    int threads = 256;
    layernorm_kernel<<<N, threads, threads * sizeof(float)>>>(input.data_ptr<float>(), gamma.data_ptr<float>(), beta.data_ptr<float>(), output.data_ptr<float>(), N, D, eps);
    return output;
}
"""

