custom_ops = load_inline(
    name="custom_ops",
    cpp_sources=custom_ops_cpp_source,
    cuda_sources=custom_ops_source,
    functions=["gelu_cuda", "layernorm_cuda"],
    verbose=False
)

class FastGELU(nn.Module):
    def forward(self, x):
        return custom_ops.gelu_cuda(x.contiguous())

class FastLayerNorm(nn.Module):
    def __init__(self, dim, eps=1e-5):
        super().__init__()
        self.gamma = nn.Parameter(torch.ones(dim))
        self.beta = nn.Parameter(torch.zeros(dim))
        self.eps = eps

    def forward(self, x):
        return custom_ops.layernorm_cuda(x.contiguous(), self.gamma, self.beta, self.eps)

class CustomTransformerEncoderLayer(nn.Module):
    def __init__(self, d_model, nhead, dim_feedforward, dropout):
        super().__init__()
        self.self_attn = nn.MultiheadAttention(d_model, nhead, dropout=dropout)
        self.linear1 = nn.Linear(d_model, dim_feedforward)
        self.linear2 = nn.Linear(dim_feedforward, d_model)
        self.norm1 = FastLayerNorm(d_model)
        self.norm2 = FastLayerNorm(d_model)
        self.dropout = nn.Dropout(dropout)
        self.dropout1 = nn.Dropout(dropout)
        self.dropout2 = nn.Dropout(dropout)

    def forward(self, src):
        # Multi-head attention (standard)
        src2, _ = self.self_attn(src, src, src)
        # Post-LN structure to match standard TransformerEncoderLayer
        src = self.norm1(src + self.dropout1(src2))

        # MLP part
        src2 = self.linear1(src)
        src2 = F.relu(src2) # Original used ReLU
        src2 = self.dropout(src2)
        src2 = self.linear2(src2)
        src = self.norm2(src + self.dropout2(src2))
        return src

class CustomTransformerEncoder(nn.Module):
    def __init__(self, dim, depth, heads, mlp_dim, dropout):
        super().__init__()
        self.layers = nn.ModuleList([
            CustomTransformerEncoderLayer(dim, heads, mlp_dim, dropout)
            for _ in range(depth)
        ])

    def forward(self, x):
        for layer in self.layers:
            x = layer(x)
        return x

class ModelNew(nn.Module):
    def __init__(self, image_size, patch_size, num_classes, dim, depth, heads, mlp_dim, channels=3, dropout=0.1, emb_dropout=0.1):
        super(ModelNew, self).__init__()

        assert image_size % patch_size == 0, "Image dimensions must be divisible by the patch size."
        num_patches = (image_size // patch_size) ** 2
        patch_dim = channels * patch_size ** 2

        self.patch_size = patch_size
        self.pos_embedding = nn.Parameter(torch.randn(1, num_patches + 1, dim))
        self.patch_to_embedding = nn.Linear(patch_dim, dim)
        self.cls_token = nn.Parameter(torch.randn(1, 1, dim))
        self.dropout = nn.Dropout(emb_dropout)

        self.transformer = CustomTransformerEncoder(dim, depth, heads, mlp_dim, dropout)

        self.to_cls_token = nn.Identity()
        self.mlp_head = nn.Sequential(
            nn.Linear(dim, mlp_dim),
            FastGELU(),
            nn.Dropout(dropout),
            nn.Linear(mlp_dim, num_classes)
        )

    def forward(self, img):
        p = self.patch_size

        # Patch partitioning and embedding
        x = img.unfold(2, p, p).unfold(3, p, p).reshape(img.shape[0], -1, p*p*img.shape[1])
        x = self.patch_to_embedding(x)

        # Prepend CLS token and add Positional Embedding
        cls_tokens = self.cls_token.expand(img.shape[0], -1, -1)
        x = torch.cat((cls_tokens, x), dim=1)
        x += self.pos_embedding
        x = self.dropout(x)

        # Transformer blocks with custom LayerNorm
        x = self.transformer(x)

        # Classification head with custom GELU
        x = self.to_cls_token(x[:, 0])
        return self.mlp_head(x)

