swin_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

typedef long long ll;

__global__ void window_partition_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int B, int H, int W, int C,
    int window_size,
    int H_blk, int W_blk,
    int total_elements) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_elements) return;

    // Output layout: (B, H_blk, W_blk, ws, ws, C)
    // We map output linear index back to logical indices

    int c = idx % C;
    int tmp = idx / C;
    int w_in = tmp % window_size;
    tmp /= window_size;
    int h_in = tmp % window_size;
    tmp /= window_size;
    int w_blk = tmp % W_blk;
    tmp /= W_blk;
    int h_blk = tmp % H_blk;
    int b = tmp / H_blk;

    // Map to Input layout (B, H, W, C)
    // H = H_blk * ws, W = W_blk * ws
    int h = h_blk * window_size + h_in;
    int w = w_blk * window_size + w_in;

    ll in_idx = ((ll)b * H * W + (ll)h * W + w) * C + c;
    output[idx] = input[in_idx];
}

torch::Tensor window_partition(torch::Tensor x, int window_size) {
    int B = x.size(0);
    int H = x.size(1);
    int W = x.size(2);
    int C = x.size(3);

    int H_blk = H / window_size;
    int W_blk = W / window_size;

    // Output shape: (B * H_blk * W_blk, window_size, window_size, C)
    auto output = torch::empty({B * H_blk * W_blk, window_size, window_size, C}, x.options());

    int total_elements = output.numel();
    const int threads = 256;
    const int blocks = (total_elements + threads - 1) / threads;

    window_partition_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        B, H, W, C,
        window_size, H_blk, W_blk,
        total_elements
    );
    return output;
}

__global__ void window_reverse_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int B, int H, int W, int C,
    int window_size,
    int H_blk, int W_blk,
    int total_elements) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_elements) return;

    // Output layout: (B, H, W, C)
    // We iterate output for coalesced writes
    int c = idx % C;
    int tmp = idx / C;
    int w = tmp % W;
    tmp /= W;
    int h = tmp % H;
    int b = tmp / H;

    // Map to Input layout (B, H_blk, W_blk, ws, ws, C)
    int h_blk = h / window_size;
    int h_in = h % window_size;
    int w_blk = w / window_size;
    int w_in = w % window_size;

    ll in_idx = (ll)b * (H_blk * W_blk * window_size * window_size * C) + 
                (ll)h_blk * (W_blk * window_size * window_size * C) + 
                (ll)w_blk * (window_size * window_size * C) + 
                (ll)h_in * (window_size * C) + 
                (ll)w_in * C + 
                c;

    output[idx] = input[in_idx];
}

torch::Tensor window_reverse(torch::Tensor windows, int window_size, int H, int W) {
    // windows: (N, ws, ws, C)
    int C = windows.size(3);
    int H_blk = H / window_size;
    int W_blk = W / window_size;
    int N = windows.size(0);
    int B = N / (H_blk * W_blk);

    auto output = torch::empty({B, H, W, C}, windows.options());

    int total_elements = output.numel();
    const int threads = 256;
    const int blocks = (total_elements + threads - 1) / threads;

    window_reverse_kernel<<<blocks, threads>>>(
        windows.data_ptr<float>(),
        output.data_ptr<float>(),
        B, H, W, C,
        window_size, H_blk, W_blk,
        total_elements
    );
    return output;
}

__global__ void patch_merging_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int B, int H, int W, int C,
    int H_out, int W_out, int C_out,
    int total_elements) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_elements) return;

    // Output: (B, H/2, W/2, 4C)
    int c_out_idx = idx % C_out;
    int tmp = idx / C_out;
    int w_out_idx = tmp % W_out;
    tmp /= W_out;
    int h_out_idx = tmp % H_out;
    int b = tmp / H_out;

    // Determine channel and patch quadrant
    int c_in = c_out_idx % C;
    int patch_idx = c_out_idx / C; // 0, 1, 2, 3

    // Mapping:
    // 0: x0 (0::2, 0::2) -> dy=0, dx=0
    // 1: x1 (1::2, 0::2) -> dy=1, dx=0
    // 2: x2 (0::2, 1::2) -> dy=0, dx=1
    // 3: x3 (1::2, 1::2) -> dy=1, dx=1

    int dy = (patch_idx == 1 || patch_idx == 3) ? 1 : 0;
    int dx = (patch_idx == 2 || patch_idx == 3) ? 1 : 0;

    int h_in = h_out_idx * 2 + dy;
    int w_in = w_out_idx * 2 + dx;

    ll in_idx = ((ll)b * H + h_in) * W * C + w_in * C + c_in;

    output[idx] = input[in_idx];
}

torch::Tensor patch_merging(torch::Tensor x, int H, int W) {
    // x: (B, L, C)
    int B = x.size(0);
    int C = x.size(2);

    int H_out = H / 2;
    int W_out = W / 2;
    int C_out = C * 4;

    auto output = torch::empty({B, H_out * W_out, C_out}, x.options());

    int total_elements = output.numel();
    const int threads = 256;
    const int blocks = (total_elements + threads - 1) / threads;

    patch_merging_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        B, H, W, C,
        H_out, W_out, C_out,
        total_elements
    );
    return output;
