import torch
import torch.nn as nn
import torch.nn.functional as F
import numpy as np
import collections
from itertools import repeat
from torch.utils.cpp_extension import load_inline

# --------------------------------------------------------------------------------
# Custom CUDA Kernels for Swin Transformer Operations
# 1. Roll (Cyclic Shift)
# 2. Window Partition
# 3. Window Reverse
# --------------------------------------------------------------------------------

swin_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// -------------------------------------------------------------------------
// Roll Kernel
// -------------------------------------------------------------------------
__global__ void roll_kernel(const float* __restrict__ src, float* __restrict__ dst,
                            int B, int H, int W, int C,
                            int shift_h, int shift_w, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        int c = idx % C;
        int tmp = idx / C;
        int w = tmp % W;
        tmp = tmp / W;
        int h = tmp % H; 
        int b = tmp / H;

        // Calculate source indices with modulo arithmetic
        int src_h = (h - shift_h) % H;
        if (src_h < 0) src_h += H;

        int src_w = (w - shift_w) % W;
        if (src_w < 0) src_w += W;

        long long src_idx = (long long)b * H * W * C + (long long)src_h * W * C + (long long)src_w * C + c;

        dst[idx] = src[src_idx];
    }
}

torch::Tensor roll_cuda(torch::Tensor input, int shift_h, int shift_w) {
    auto B = input.size(0);
    auto H = input.size(1);
    auto W = input.size(2);
    auto C = input.size(3);
    auto output = torch::empty_like(input);
    auto total_elements = input.numel();

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    roll_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(), output.data_ptr<float>(),
        B, H, W, C, shift_h, shift_w, total_elements);

    return output;
}

// -------------------------------------------------------------------------
// Window Partition Kernel
// -------------------------------------------------------------------------
__global__ void window_partition_kernel(const float* __restrict__ src, float* __restrict__ dst,
                                        int B, int H, int W, int C, int ws,
                                        int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        int H_div = H / ws;
        int W_div = W / ws;

        // Unravel output index: (B * H_div * W_div, ws, ws, C)
        // Logically: (B, H_div, W_div, ws, ws, C)
        int c = idx % C;
        int tmp = idx / C;
        int wx = tmp % ws; tmp /= ws;
        int wy = tmp % ws; tmp /= ws;
        int w_div = tmp % W_div; tmp /= W_div;
        int h_div = tmp % H_div; 
        int b = tmp / H_div;

        // Reconstruct Source (b, h, w, c)
        int h = h_div * ws + wy;
        int w = w_div * ws + wx;

        long long src_idx = (long long)b * H * W * C + (long long)h * W * C + (long long)w * C + c;
        dst[idx] = src[src_idx];
    }
}

torch::Tensor window_partition_cuda(torch::Tensor input, int window_size) {
    auto B = input.size(0);
    auto H = input.size(1);
    auto W = input.size(2);
    auto C = input.size(3);
    int H_div = H / window_size;
    int W_div = W / window_size;

    // Output shape: (num_windows * B, window_size, window_size, C)
    auto output = torch::empty({B * H_div * W_div, window_size, window_size, C}, input.options());
    auto total_elements = output.numel();

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    window_partition_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(), output.data_ptr<float>(),
        B, H, W, C, window_size, total_elements);

    return output;
}

// -------------------------------------------------------------------------
// Window Reverse Kernel
// -------------------------------------------------------------------------
__global__ void window_reverse_kernel(const float* __restrict__ src, float* __restrict__ dst,
                                      int B, int H, int W, int C, int ws,
                                      int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        // Unravel Output index: (B, H, W, C)
        int c = idx % C;
        int tmp = idx / C;
        int w = tmp % W; tmp /= W;
        int h = tmp % H; 
        int b = tmp / H;

        // Calculate Input indices for layout: (B, H_div, W_div, ws, ws, C)
        int h_div = h / ws;
        int wy = h % ws;
        int w_div = w / ws;
        int wx = w % ws;

        int H_div = H / ws;
        int W_div = W / ws;

        long long src_idx = (long long)c + 
                            (long long)wx * C + 
                            (long long)wy * C * ws + 
                            (long long)w_div * C * ws * ws + 
                            (long long)h_div * C * ws * ws * W_div + 
                            (long long)b * C * ws * ws * W_div * H_div;

        dst[idx] = src[src_idx];
    }
}

torch::Tensor window_reverse_cuda(torch::Tensor windows, int window_size, int H, int W) {
    auto total_windows_B = windows.size(0);
    auto C = windows.size(3);
    int H_div = H / window_size;
    int W_div = W / window_size;
    int B = total_windows_B / (H_div * W_div);

    auto output = torch::empty({B, H, W, C}, windows.options());
    auto total_elements = output.numel();

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    window_reverse_kernel<<<num_blocks, block_size>>>(
        windows.data_ptr<float>(), output.data_ptr<float>(),
        B, H, W, C, window_size, total_elements);

    return output;
}
