import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for fused element-wise addition and LayerNorm
fused_add_norm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_add_norm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ attn_out,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int rows,
    int cols,
    float eps) {

    int row = blockIdx.x;
    if (row >= rows) return;

    float thread_sum = 0.0f;
    float thread_sq_sum = 0.0f;

    // Use loop to calculate sum and squared sum for normalization
    for (int col = threadIdx.x; col < cols; col += blockDim.x) {
        float val = x[row * cols + col] + attn_out[row * cols + col];
        thread_sum += val;
        thread_sq_sum += val * val;
    }

    // Warp reduction
    for (int offset = 16; offset > 0; offset /= 2) {
        thread_sum += __shfl_down_sync(0xFFFFFFFF, thread_sum, offset);
        thread_sq_sum += __shfl_down_sync(0xFFFFFFFF, thread_sq_sum, offset);
    }

    __shared__ float s_sum[32];
    __shared__ float s_sq_sum[32];
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

