            s_sum[0] = val_sum;
            s_sq_sum[0] = val_sq_sum;
        }
    }
    __syncthreads();

    float mean = s_sum[0] / cols;
    float var = (s_sq_sum[0] / cols) - (mean * mean);
    if (var < 0.0f) var = 0.0f;
    float rstd = rsqrtf(var + eps);

    // Apply normalization and weights/biases
