fused_ops_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// CUDA Kernel for Fused Add + LayerNorm
// Computes: Output = LayerNorm(Input + Residual)
// Optimized for row-wise operations.
__global__ void fused_add_layernorm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ residual,
    const float* __restrict__ gamma,
    const float* __restrict__ beta,
    float* __restrict__ output,
    int batch_size,
    int hidden_dim,
    float epsilon) {

    // Identify the row this block is processing
    int bid = blockIdx.x;
    if (bid >= batch_size) return;

    // Use shared memory for reduction
    extern __shared__ float sdata[];
    // Memory layout: [0..blockDim.x-1]: sum, [blockDim.x..2*blockDim.x-1]: sum_sq

    int tid = threadIdx.x;
    int offset = bid * hidden_dim;

    // 1. Load data, compute Element-wise Add, and accumulate stats
    float local_sum = 0.0f;
    float local_sum_sq = 0.0f;

    // Each thread processes multiple elements if hidden_dim > blockDim.x
    for (int i = tid; i < hidden_dim; i += blockDim.x) {
        float val = input[offset + i] + residual[offset + i];
        // We could store 'val' in shared memory to avoid re-computation/re-read, 
        // but for small dims, re-computation from global might be acceptable or we rely on L1.
        // Let's just accumulate first.
        local_sum += val;
        local_sum_sq += val * val;
    }

    // Store in shared memory for reduction
    sdata[tid] = local_sum;
    sdata[tid + blockDim.x] = local_sum_sq;
    __syncthreads();

    // 2. Block Reduction (Tree style)
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
            sdata[tid + blockDim.x] += sdata[tid + s + blockDim.x];
        }
        __syncthreads();
    }

    // 3. Compute Mean and Variance
    float mean = sdata[0] / hidden_dim;
    float var = sdata[blockDim.x] / hidden_dim - mean * mean;
    float inv_std = rsqrtf(var + epsilon);

    // 4. Normalize and Store
    // Re-read/compute val to avoid excessive shared memory usage for large hidden_dim
    for (int i = tid; i < hidden_dim; i += blockDim.x) {
        float val = input[offset + i] + residual[offset + i];
        output[offset + i] = (val - mean) * inv_std * gamma[i] + beta[i];
    }
}

torch::Tensor fused_add_layernorm_cuda(
    torch::Tensor input, 
    torch::Tensor residual, 
    torch::Tensor gamma, 
    torch::Tensor beta, 
