    // Launch one block per token (row)
    dim3 grid(batch_size);
    dim3 block(block_size);

    // Shared memory: 2 * block_size * sizeof(float)
    int shared_mem_size = 2 * block_size * sizeof(float);

    fused_add_layernorm_kernel<<<grid, block, shared_mem_size>>>(
        input.data_ptr<float>(), 
        residual.data_ptr<float>(), 
        gamma.data_ptr<float>(), 
        beta.data_ptr<float>(), 
        output.data_ptr<float>(), 
        batch_size, 
        hidden_dim, 
        epsilon
    );

    return output;
}
"""

