class OptimizedTransformerEncoderLayer(nn.Module):
    def __init__(self, d_model, nhead, dim_feedforward, dropout=0.0):
        super().__init__()
        self.self_attn = nn.MultiheadAttention(d_model, nhead, dropout=dropout, batch_first=True)
        # Feed Forward Network
        self.linear1 = nn.Linear(d_model, dim_feedforward)
        self.dropout = nn.Dropout(dropout)
        self.linear2 = nn.Linear(dim_feedforward, d_model)

        # LayerNorm parameters (Gamma and Beta)
        self.norm1_gamma = nn.Parameter(torch.ones(d_model))
        self.norm1_beta = nn.Parameter(torch.zeros(d_model))
        self.norm2_gamma = nn.Parameter(torch.ones(d_model))
        self.norm2_beta = nn.Parameter(torch.zeros(d_model))

        self.activation = F.relu # Standard Transformer default

    def forward(self, src):
        # src shape: (B, SeqLen, EmbedDim)

        # 1. Self-Attention Block
        # Original: x = norm(x + attn(x))
        # We compute attn(src) then use fused kernel for Add+Norm
        attn_out, _ = self.self_attn(src, src, src, need_weights=False)

        # Fused Operation: src = LayerNorm(src + attn_out)
        src = fused_ops.fused_add_layernorm_cuda(attn_out, src, self.norm1_gamma, self.norm1_beta, 1e-5)

        # 2. Feed Forward Block
        # Original: x = norm(x + linear2(act(linear1(x))))
        ffn_out = self.linear2(self.dropout(self.activation(self.linear1(src))))

        # Fused Operation: src = LayerNorm(src + ffn_out)
        src = fused_ops.fused_add_layernorm_cuda(ffn_out, src, self.norm2_gamma, self.norm2_beta, 1e-5)

        return src

class ModelNew(nn.Module):
    def __init__(self, num_classes, embed_dim=512, num_heads=8, num_layers=6, 
                 mlp_ratio=4.0, patch_size=4, in_channels=3, image_size=32):
        super(ModelNew, self).__init__()

        self.embed_dim = embed_dim

        # Algorithmic Optimization:
        # The original sequence: Conv2d(k=p, s=p) -> Flatten -> Linear
        # is mathematically equivalent to a single Linear projection of the flattened image
        # provided the image size divides perfectly by the patch size (standard ViT behavior).
        # This reduces FLOPs and memory overhead significantly.
        # Input: (B, C, H, W) -> Flatten -> (B, C*H*W) -> Linear -> (B, embed_dim)

        self.flat_input_dim = in_channels * image_size * image_size
        self.input_proj = nn.Linear(self.flat_input_dim, embed_dim)

        # Optimized Transformer Layers utilizing Custom CUDA Kernels
        self.transformer_layers = nn.ModuleList([
            OptimizedTransformerEncoderLayer(
                d_model=embed_dim,
                nhead=num_heads,
                dim_feedforward=int(embed_dim * mlp_ratio),
                dropout=0.0
            ) for _ in range(num_layers)
        ])

        self.cls_token = nn.Parameter(torch.zeros(1, 1, embed_dim))
        self.fc_out = nn.Linear(embed_dim, num_classes)

    def forward(self, x):
        B = x.size(0)

        # Optimized Input Processing
        # Flatten image: (B, C, H, W) -> (B, C*H*W)
        x = x.flatten(start_dim=1)
        # Single Linear Projection -> (B, embed_dim)
        x = self.input_proj(x)

        # Add CLS token
        cls_tokens = self.cls_token.expand(B, -1, -1)  # (B, 1, embed_dim)
        # Note: Original code used x.unsqueeze(1) to make x (B, 1, embed_dim)
        x = torch.cat((cls_tokens, x.unsqueeze(1)), dim=1)  # (B, 2, embed_dim)

        # Pass through Optimized Transformer
        for layer in self.transformer_layers:
            x = layer(x)

        return self.fc_out(x[:, 0])

