#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_add2_bias_tanh_kernel_vec(float4* A, const float4* B, const float4* bias, int total_v4, int cols_v4) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_v4) {
