import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the RNN recurrence scan
# This kernel fuses the sequential dependency loop (h_t depends on h_{t-1})
# allowing us to avoid kernel launch overheads for every time step.
# It also allows us to keep the hidden state in shared memory.

rnn_scan_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void rnn_scan_kernel(
    const float* __restrict__ gates,   // Precomputed inputs (Seq, Batch, Hidden)
    const float* __restrict__ h0,      // Initial hidden state (Batch, Hidden)
    const float* __restrict__ W_hh_t,  // Transposed Recurrent Weights (Hidden, Hidden)
    float* __restrict__ h_out,         // Output hidden states (Seq, Batch, Hidden)
    int seq_len,
    int batch_size,
    int hidden_size) {

    // Each block handles one sequence in the batch
    int b = blockIdx.x;

    // Each thread handles one neuron in the hidden state
    int tid = threadIdx.x;

    if (b >= batch_size || tid >= hidden_size) return;

    // Allocate shared memory for the current hidden state
    extern __shared__ float s_h[];

    // Initialize hidden state
    s_h[tid] = h0[b * hidden_size + tid];

    // Barrier to ensure initialization is visible
    __syncthreads();

    for (int t = 0; t < seq_len; ++t) {
        // Load the precomputed input part (x * W_ih + b) for this timestep
        float val = gates[(t * batch_size + b) * hidden_size + tid];

        // Compute the recurrent part: dot(h_prev, W_hh_row)
        // Mathematically: h_new[j] = tanh( gate[j] + sum_k( h_prev[k] * W_hh[j, k] ) )
        // We pass W_hh transposed and contiguous, so we access it as W_hh_t.
        // The access pattern W_hh_t[k * hidden_size + tid] corresponds to W_hh[tid, k].
        // As 'tid' varies (across threads), the memory access is contiguous (coalesced).

        float dot = 0.0f;
        for (int k = 0; k < hidden_size; ++k) {
            dot += s_h[k] * W_hh_t[k * hidden_size + tid];
        }

        val += dot;
        val = tanhf(val);

        // Store result to global memory
        h_out[(t * batch_size + b) * hidden_size + tid] = val;

        // Update shared memory for the next timestep
        // 1. Wait for all threads to finish reading s_h in the dot product loop
        __syncthreads();

        // 2. Update s_h with the new value
        s_h[tid] = val;

        // 3. Wait for all threads to finish writing s_h before next iteration reads it
        __syncthreads();
    }
}

torch::Tensor rnn_scan_cuda(torch::Tensor gates, torch::Tensor h0, torch::Tensor W_hh_t) {
    auto seq_len = gates.size(0);
    auto batch_size = gates.size(1);
    auto hidden_size = gates.size(2);

    auto h_out = torch::zeros_like(gates);

    // Launch one block per batch sample, one thread per hidden unit
    const int block_size = hidden_size; 
    const int grid_size = batch_size;
    const int shared_mem_size = hidden_size * sizeof(float);

    rnn_scan_kernel<<<grid_size, block_size, shared_mem_size>>>(
        gates.data_ptr<float>(),
        h0.data_ptr<float>(),
        W_hh_t.data_ptr<float>(),
        h_out.data_ptr<float>(),
        seq_len,
        batch_size,
        hidden_size
    );

    return h_out;
}
"""

rnn_scan_cpp_source = "torch::Tensor rnn_scan_cuda(torch::Tensor gates, torch::Tensor h0, torch::Tensor W_hh_t);"

# Compile the inline CUDA code
rnn_scan = load_inline(
    name="rnn_scan",
    cpp_sources=rnn_scan_cpp_source,
    cuda_sources=rnn_scan_source,
    functions=["rnn_scan_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, input_size: int, hidden_size: int, output_size: int):
        """
        Initialize the Optimized RNN model.
        """
        super(ModelNew, self).__init__()
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.output_size = output_size

        # We maintain the same parameter structure as the original model
        # to ensure compatibility, but we will access weights differently in forward.
        self.i2h = nn.Linear(input_size + hidden_size, hidden_size)
        self.h2o = nn.Linear(hidden_size, output_size)
        self.tanh = nn.Tanh() # Not used explicitly in forward, fused in kernel

        self.rnn_scan = rnn_scan

    def forward(self, x: torch.Tensor, h0: torch.Tensor) -> torch.Tensor:
        """
        Optimized Forward pass.
        """
        seq_len, batch_size, _ = x.size()

        # Decompose the i2h weights into Input-Hidden and Hidden-Hidden parts
        w_i2h = self.i2h.weight
        b_i2h = self.i2h.bias

        w_ih = w_i2h[:, :self.input_size]
        w_hh = w_i2h[:, self.input_size:]

        # Optimization 1: Precompute Input Projections (Batch Matrix Multiplication)
        # Instead of doing small MMs inside the loop, we do one large MM.
        # x shape: (seq, batch, input) -> Flatten to (seq*batch, input)
        x_flat = x.view(-1, self.input_size)

        # Compute x @ W_ih.T + bias
        gates = F.linear(x_flat, w_ih, b_i2h)
        gates = gates.view(seq_len, batch_size, self.hidden_size)

        # Optimization 2: Custom CUDA Kernel for Recurrence
        # Prepare W_hh for the kernel. The kernel uses a coalesced access pattern
        # that requires the transpose of W_hh stored contiguously.
        w_hh_cuda = w_hh.t().contiguous()

        # Ensure memory layout is contiguous for CUDA access
        gates = gates.contiguous()
        h0 = h0.contiguous()

        # Execute the recurrent scan kernel
        # Computes: h_t = tanh(gates_t + h_{t-1} @ w_hh.T)
        h_all = self.rnn_scan.rnn_scan_cuda(gates, h0, w_hh_cuda)

        # Optimization 3: Batch Output Projection
        # Apply h2o to all timesteps at once
        outputs = self.h2o(h_all)  # (seq, batch, output_size)

        return outputs

