fused_head_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_lstm_head_kernel(
    const float* __restrict__ input,      // (Batch, Seq, Hidden)
    const float* __restrict__ weight,     // (Output, Hidden)
    const float* __restrict__ bias,       // (Output)
    float* __restrict__ output,           // (Batch, Output)
    int batch_size,
    int seq_len,
    int hidden_size,
    int output_size)
{
    // We parallelize over the output elements (Batch * Output_Size)
    // idx corresponds to a unique (batch_idx, output_idx) pair
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * output_size;

    if (idx < total_elements) {
        // Map linear index to (b, o)
        int o = idx % output_size;
        int b = idx / output_size;

        // Calculate offset for the input tensor to get the vector at the last timestep
        // Input layout is (Batch, Seq, Hidden)
        // We want input[b, seq_len-1, :]
        // Offset = b * (seq_len * hidden_size) + (seq_len - 1) * hidden_size
        int input_offset = b * (seq_len * hidden_size) + (seq_len - 1) * hidden_size;

        // Calculate offset for the weight matrix
        // Weight layout is (Output, Hidden)
        // Offset = o * hidden_size
        int weight_offset = o * hidden_size;

        const float* input_vec = input + input_offset;
        const float* weight_vec = weight + weight_offset;

        // Perform dot product
        float sum = 0.0f;
        for (int h = 0; h < hidden_size; ++h) {
            sum += input_vec[h] * weight_vec[h];
        }

        // Add bias if present
        if (bias != nullptr) {
            sum += bias[o];
        }

        // Write to output
