// Fused CUDA kernel for LSTM element-wise operations
// Computes: i, f, g, o gates, updates c and h
__global__ void lstm_cell_fused_kernel(
    const float* __restrict__ gates, 
    const float* __restrict__ c_prev, 
    float* __restrict__ h_next, 
    float* __restrict__ c_next, 
    int batch_size, 
    int hidden_size) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * hidden_size;

    if (idx < total_elements) {
        int n = idx / hidden_size; 
        int h = idx % hidden_size; 

        // gates tensor has shape (N, 4*H)
        // Layout: input (i), forget (f), cell (g), output (o)
        int row_start = n * (4 * hidden_size);

        float in_gate_val = gates[row_start + h];
        float forget_gate_val = gates[row_start + hidden_size + h];
        float cell_gate_val = gates[row_start + 2 * hidden_size + h];
        float out_gate_val = gates[row_start + 3 * hidden_size + h];

        // Apply activations
        float i = 1.0f / (1.0f + expf(-in_gate_val));
        float f = 1.0f / (1.0f + expf(-forget_gate_val));
        float g = tanhf(cell_gate_val);
        float o = 1.0f / (1.0f + expf(-out_gate_val));

        // Update cell state and hidden state
        float c_old = c_prev[idx];
        float c_new = f * c_old + i * g;
        float h_new = o * tanhf(c_new);

        c_next[idx] = c_new;
        h_next[idx] = h_new;
