    auto gates_x = torch::addmm(b_ih, input_t.view({-1, input_size}), w_ih.t());
    gates_x = gates_x.view({seq_len, batch_size, 4 * hidden_size});

    auto h_current = hx;
    auto c_current = cx;

    std::vector<torch::Tensor> outputs;
    outputs.reserve(seq_len);

