        auto gates = gates_x[t] + gates_h;

        auto h_next = torch::empty_like(h_current);
        auto c_next = torch::empty_like(c_current);

        // Launch fused kernel
        lstm_cell_fused_kernel<<<num_blocks, block_size>>>(
            gates.data_ptr<float>(),
            c_current.data_ptr<float>(),
            h_next.data_ptr<float>(),
            c_next.data_ptr<float>(),
            batch_size,
            hidden_size
        );

        h_current = h_next;
        c_current = c_next;
        outputs.push_back(h_current);
    }

    // Stack outputs to form (L, N, H)
    auto output_seq = torch::stack(outputs, 0);

