        int gate_idx = b * 4 * hidden_size + h;

        // Fused addition of precomputed input part and current hidden part
        float in_gate_val = gates_x[gate_idx] + gates_h[gate_idx];
        float forget_gate_val = gates_x[gate_idx + hidden_size] + gates_h[gate_idx + hidden_size];
        float cell_gate_val = gates_x[gate_idx + 2 * hidden_size] + gates_h[gate_idx + 2 * hidden_size];
        float out_gate_val = gates_x[gate_idx + 3 * hidden_size] + gates_h[gate_idx + 3 * hidden_size];

