    auto T = input.size(1);
    auto H = h0.size(1);
    auto options = input.options();

    // 1. Precompute X @ W_ih^T + b_ih for all timesteps simultaneously
    // Reshape input to [B*T, I] for efficient matmul
    auto gates_x = torch::addmm(b_ih, input.reshape({-1, input.size(2)}), w_ih.t());
