fused_slice_linear_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_slice_linear_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int seq_len,
    int input_dim,
    int output_dim) {

    // Map threads to output element (batch_index, output_feature_index)
    // Grid Y -> Batch
    // Grid X -> Output Features
    int row = blockIdx.y * blockDim.y + threadIdx.y; 
    int col = blockIdx.x * blockDim.x + threadIdx.x; 

    if (row < batch_size && col < output_dim) {
        float sum = 0.0f;

        // Calculate the starting offset for the specific batch element in Input
        // Input shape: (Batch, Seq, InputDim)
        // We want the vector at the LAST time step: index = (row, seq_len - 1, :)
        // Flat index start = row * (seq_len * input_dim) + (seq_len - 1) * input_dim
        int input_offset = row * (seq_len * input_dim) + (seq_len - 1) * input_dim;

        // Calculate the starting offset for the weight row
        // Weight shape: (OutputDim, InputDim)
        // We want the dot product with the row 'col'
        // Flat index start = col * input_dim
        int weight_offset = col * input_dim;

        // Compute dot product
