import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# CUDA source for the fused slice and linear operation.
# This kernel replaces the operation out[:, -1, :] followed by self.fc(out).
# It performs the slicing and the linear projection (GEMV) in a single step,
# using a parallel reduction for each output element to maximize performance.
fused_linear_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_slice_linear_kernel(
    const float* __restrict__ lstm_out,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int B, int S, int K, int O
) {
    // Each block calculates one element of the output matrix [B, O].
    int b = blockIdx.x / O;
    int o = blockIdx.x % O;

    if (b >= B || o >= O) return;

    int tid = threadIdx.x;
    float sum = 0.0f;

    // The slice 'out[:, -1, :]' is implemented by offsetting the input pointer
    // to the last sequence step (S-1) for the current batch (b).
    const float* in_ptr = lstm_out + (b * S + (S - 1)) * K;
    // Each thread in the block computes a partial dot product between the 
    // input hidden state and the weight row for output index 'o'.
    const float* w_ptr = weight + o * K;

    for (int k = tid; k < K; k += blockDim.x) {
        sum += in_ptr[k] * w_ptr[k];
    }

    // Parallel reduction using warp shuffles to sum partial results.
    for (int offset = 16; offset > 0; offset /= 2) {
        sum += __shfl_down_sync(0xFFFFFFFF, sum, offset);
    }

    // Shared memory for final reduction across warps in the block.
    __shared__ float s_sums[32];
    int warp_id = tid / 32;
    int lane_id = tid % 32;

    if (lane_id == 0) s_sums[warp_id] = sum;
    __syncthreads();

    if (tid < 32) {
        float warp_sum = (tid < (blockDim.x + 31) / 32) ? s_sums[tid] : 0.0f;
        for (int offset = 16; offset > 0; offset /= 2) {
            warp_sum += __shfl_down_sync(0xFFFFFFFF, warp_sum, offset);
        }
        // The first thread of the block writes the final result with the bias.
        if (tid == 0) {
            output[b * O + o] = warp_sum + bias[o];
        }
    }
}

torch::Tensor fused_slice_linear_cuda(torch::Tensor lstm_out, torch::Tensor weight, torch::Tensor bias) {
    int B = lstm_out.size(0);
    int S = lstm_out.size(1);
    int K = lstm_out.size(2);
    int O = weight.size(0);

    auto output = torch::empty({B, O}, lstm_out.options());

    // Use 256 threads per block and one block per output element.
    int threads = 256;
    int blocks = B * O;

    fused_slice_linear_kernel<<<blocks, threads>>>(
        lstm_out.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        B, S, K, O
    );

    return output;
}
"""

fused_linear_cpp_source = (
    "torch::Tensor fused_slice_linear_cuda(torch::Tensor lstm_out, torch::Tensor weight, torch::Tensor bias);"
)

# Compile the inline CUDA code
fused_op = load_inline(
    name="fused_op",
    cpp_sources=fused_linear_cpp_source,
    cuda_sources=fused_linear_source,
    functions=["fused_slice_linear_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers, output_size, dropout=0.0):
        """
        Initialize the optimized LSTM model.
        """
        super(ModelNew, self).__init__()
        # Use the standard nn.LSTM, but we will optimize the downstream processing.
        self.lstm = nn.LSTM(input_size, hidden_size, num_layers, batch_first=True, 
                            dropout=dropout, bidirectional=True)
        # Ensure LSTM parameters are in a single contiguous block for efficiency.
        self.lstm.flatten_parameters()

        self.fc = nn.Linear(hidden_size * 2, output_size)
        self.fused_op = fused_op

    def forward(self, x, h0, c0):
        """
        Forward pass through the optimized model.
        """
        # Run the bidirectional LSTM. While CuDNN is hard to beat for the LSTM cell,
        # we can optimize the output processing.
        out, _ = self.lstm(x, (h0, c0))

        # Replace the slicing and linear layer with a custom fused CUDA operator.
        # Original: out = self.fc(out[:, -1, :])
        # This custom kernel avoids intermediate allocation for the slice and 
        # uses a highly parallelized reduction for the final projection.
        out = self.fused_op.fused_slice_linear_cuda(out, self.fc.weight, self.fc.bias)

        return out

