import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the GRU Recurrence
gru_cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__device__ __forceinline__ float sigmoid(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__device__ __forceinline__ float tanh_act(float x) {
    return tanhf(x);
}

__global__ void gru_fused_kernel(
    const float* __restrict__ input_gates, 
    const float* __restrict__ h_prev,
    const float* __restrict__ w_hh_t, 
    const float* __restrict__ b_hh,
    float* __restrict__ output,
    int seq_len,
    int batch_size,
    int hidden_size) 
{
    // BlockIdx.x corresponds to the batch element
    // ThreadIdx.x corresponds to the hidden unit
    int bid = blockIdx.x; 
    int tid = threadIdx.x; 

    // Shared memory to hold the current hidden state h_t for the batch item
    extern __shared__ float smem_h[];

    if (bid >= batch_size) return;

    // Load initial hidden state into shared memory and register
    float h_curr = 0.0f;
    if (tid < hidden_size) {
        h_curr = h_prev[bid * hidden_size + tid];
        smem_h[tid] = h_curr;
    }
    __syncthreads();

    // Loop through the sequence time steps
    for (int t = 0; t < seq_len; ++t) {
        if (tid < hidden_size) {
            float acc_r = 0.0f;
            float acc_z = 0.0f;
            float acc_n = 0.0f;

            // Offsets for r, z, n components in the 3*H dimension
            int idx_r = tid;
            int idx_z = tid + hidden_size;
            int idx_n = tid + 2 * hidden_size;

            // Compute W_hh * h_{t-1}
            // w_hh_t is transposed to shape (Hidden, 3*Hidden) for coalesced memory access.
            // Row k of w_hh_t corresponds to the k-th element of h_{t-1}.
            // Thread tid reads column tid (and tid+H, tid+2H) of w_hh_t.
            // Because w_hh_t is row-major (H rows, 3H cols), accessing [k * 3H + tid] 
            // ensures that adjacent threads read adjacent memory addresses.

            for (int k = 0; k < hidden_size; ++k) {
                float val = smem_h[k];
                int base_k = k * 3 * hidden_size;
                acc_r += val * w_hh_t[base_k + idx_r];
                acc_z += val * w_hh_t[base_k + idx_z];
                acc_n += val * w_hh_t[base_k + idx_n];
            }

            // Add Recurrent Bias
            acc_r += b_hh[idx_r];
            acc_z += b_hh[idx_z];
            acc_n += b_hh[idx_n];

            // Fetch Input Gates (pre-computed: x @ W_ih.T + b_ih)
            // input_gates shape: (seq_len, batch_size, 3 * hidden_size)
            int in_base = t * batch_size * 3 * hidden_size + bid * 3 * hidden_size;
            float in_r = input_gates[in_base + idx_r];
            float in_z = input_gates[in_base + idx_z];
            float in_n = input_gates[in_base + idx_n];

            // Compute Gates
            float r = sigmoid(in_r + acc_r);
            float z = sigmoid(in_z + acc_z);
            float n = tanh_act(in_n + r * acc_n);

            // Update Hidden State
            h_curr = (1.0f - z) * n + z * h_curr;

            // Store output to global memory
            output[t * batch_size * hidden_size + bid * hidden_size + tid] = h_curr;
        }

        // Synchronize before updating shared memory for the next step
        __syncthreads();
        if (tid < hidden_size) {
            smem_h[tid] = h_curr;
        }
        __syncthreads();
    }
}

torch::Tensor gru_cuda_forward(
    torch::Tensor input_gates, 
    torch::Tensor h0, 
    torch::Tensor w_hh_t, 
    torch::Tensor b_hh) 
{
    auto seq_len = input_gates.size(0);
    auto batch_size = input_gates.size(1);
    auto hidden_size = h0.size(1);

    auto output = torch::empty({seq_len, batch_size, hidden_size}, h0.options());

    // Configure kernel launch
    // Assuming hidden_size fits in a block (<= 1024). 
    // For larger hidden sizes, a loop over tiles would be needed.
    int threads = hidden_size; 
    int smem_size = hidden_size * sizeof(float);

    gru_fused_kernel<<<batch_size, threads, smem_size>>>(
        input_gates.data_ptr<float>(),
        h0.data_ptr<float>(),
        w_hh_t.data_ptr<float>(),
        b_hh.data_ptr<float>(),
        output.data_ptr<float>(),
        seq_len,
        batch_size,
        hidden_size
    );

    return output;
}
"""

gru_cpp_source = (
    "torch::Tensor gru_cuda_forward(torch::Tensor input_gates, torch::Tensor h0, torch::Tensor w_hh_t, torch::Tensor b_hh);"
)

# Compile the inline CUDA code
gru_ops = load_inline(
    name="gru_ops",
    cpp_sources=gru_cpp_source,
    cuda_sources=gru_cuda_source,
    functions=["gru_cuda_forward"],
    verbose=False,
    extra_cuda_cflags=["-O3"]
)

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers=3, bias=True, batch_first=False):
        super(ModelNew, self).__init__()
        self.num_layers = num_layers
        self.hidden_size = hidden_size
        self.batch_first = batch_first
        self.gru_ops = gru_ops

        self.w_ih = nn.ParameterList()
        self.w_hh = nn.ParameterList()
        self.b_ih = nn.ParameterList()
        self.b_hh = nn.ParameterList()

        for i in range(num_layers):
            ins = input_size if i == 0 else hidden_size

            # W_ih: (3 * hidden, input)
            w_ih = torch.randn(3 * hidden_size, ins) / (ins ** 0.5)
            self.w_ih.append(nn.Parameter(w_ih))

            # W_hh: stored normally as (3 * hidden, hidden) in PyTorch
            # But we transpose it to (hidden, 3 * hidden) for our custom kernel optimization (coalescing)
            w_hh_init = torch.randn(3 * hidden_size, hidden_size) / (hidden_size ** 0.5)
            # Transpose and make contiguous
            self.w_hh.append(nn.Parameter(w_hh_init.t().contiguous()))

            # Biases
            if bias:
                b_ih = torch.zeros(3 * hidden_size)
                b_hh = torch.zeros(3 * hidden_size)
                self.b_ih.append(nn.Parameter(b_ih))
                self.b_hh.append(nn.Parameter(b_hh))
            else:
                # Handle bias=False by using zero tensors (not parameters)
                self.b_ih.append(torch.zeros(3 * hidden_size))
                self.b_hh.append(torch.zeros(3 * hidden_size))

