        # x: (seq_len, batch, input_size) if batch_first=False
        if self.batch_first:
            x = x.transpose(0, 1)

        seq_len, batch_size, _ = x.shape
        current_input = x

        # h0 is (num_layers, batch, hidden)

        for i in range(self.num_layers):
            h_prev = h0[i]

            # 1. Pre-compute Input Gates for the entire sequence (MatMul)
            # input shape: (seq, batch, ins) -> (seq*batch, ins)
            # w_ih shape: (3H, ins)
            # Result: (seq*batch, 3H) -> (seq, batch, 3H)
            # We use PyTorch's optimized F.linear (calls cuBLAS)
            input_flat = current_input.view(seq_len * batch_size, -1)
            input_gates = F.linear(input_flat, self.w_ih[i], self.b_ih[i])
            input_gates = input_gates.view(seq_len, batch_size, 3 * self.hidden_size)

            # 2. Run Custom Fused GRU Kernel
            # Passes input_gates, h_prev, w_hh (transposed), b_hh
            # Returns output sequence for this layer
            current_input = self.gru_ops.gru_cuda_forward(
                input_gates, 
                h_prev, 
                self.w_hh[i], 
                self.b_ih[i] if isinstance(self.b_hh[i], torch.Tensor) and self.b_hh[i].device.type != 'cuda' else self.b_hh[i] 
            )

        output = current_input

        if self.batch_first:
            output = output.transpose(0, 1)

        return output

