#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void gru_cell_fused_kernel(
    const float* __restrict__ x_gates, // [batch, 3*hidden]
    const float* __restrict__ h_gates, // [batch, 3*hidden]
    const float* __restrict__ h_prev,  // [batch, hidden]
    float* __restrict__ h_out,         // [batch, hidden]
    int batch_size,
    int hidden_size) {

    int b = blockIdx.x * blockDim.x + threadIdx.x;
    int h = blockIdx.y * blockDim.y + threadIdx.y;

    if (b < batch_size && h < hidden_size) {
        int base_idx = b * 3 * hidden_size;
        int h_idx = b * hidden_size + h;

        // PyTorch GRU gate order: reset (r), update (z), new (n)
        float xr = x_gates[base_idx + h];
        float xz = x_gates[base_idx + hidden_size + h];
        float xn = x_gates[base_idx + 2 * hidden_size + h];

        float hr = h_gates[base_idx + h];
        float hz = h_gates[base_idx + hidden_size + h];
