import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for the fused GRU cell operations
# This kernel fuses the element-wise operations (sigmoid, tanh, addition, multiplication)
# to reduce memory bandwidth usage, which is the primary bottleneck in RNNs after matrix multiplication.
gru_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void gru_cell_fused_kernel(
    const float* __restrict__ wx, 
    const float* __restrict__ wh, 
    const float* __restrict__ h_prev, 
    float* __restrict__ h_curr,
    int hidden_size, 
    int total_elements) {

    // Calculate global thread index
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < total_elements) {
        int row = idx / hidden_size; // batch index
        int col = idx % hidden_size; // hidden unit index

        // Calculate offset for the current batch in the linearized 3*hidden_size vectors
        int offset = row * 3 * hidden_size + col;

        // wx and wh contain the linear projections for [Reset, Update, New] gates

        // --- Reset Gate (r) ---
        float wx_r = wx[offset];
        float wh_r = wh[offset];
        float r = 1.0f / (1.0f + expf(-(wx_r + wh_r)));

        // --- Update Gate (z) ---
        // Offset by hidden_size to get to the z-gate part
        float wx_z = wx[offset + hidden_size];
        float wh_z = wh[offset + hidden_size];
        float z = 1.0f / (1.0f + expf(-(wx_z + wh_z)));

        // --- New Gate (n) ---
        // Offset by 2*hidden_size
        float wx_n = wx[offset + 2 * hidden_size];
        float wh_n = wh[offset + 2 * hidden_size];

        // Standard GRU formulation for n: tanh(Wx + r * (Wh + b_hn))
        // Here wh includes the bias b_hn, so we multiply wh_n by r
        float n_val = tanhf(wx_n + r * wh_n);

        // --- Hidden State Update ---
        // h_t = (1 - z) * n + z * h_{t-1}
        float hp = h_prev[idx];
        h_curr[idx] = (1.0f - z) * n_val + z * hp;
    }
}

torch::Tensor gru_cell_cuda(torch::Tensor wx, torch::Tensor wh, torch::Tensor h_prev) {
    // wx: [batch_size, 3 * hidden_size]
    // wh: [batch_size, 3 * hidden_size]
    // h_prev: [batch_size, hidden_size]

    auto batch_size = h_prev.size(0);
    auto hidden_size = h_prev.size(1);

    auto h_curr = torch::empty_like(h_prev);

    int total_elements = batch_size * hidden_size;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    gru_cell_fused_kernel<<<num_blocks, block_size>>>(
        wx.data_ptr<float>(),
        wh.data_ptr<float>(),
        h_prev.data_ptr<float>(),
        h_curr.data_ptr<float>(),
        hidden_size,
        total_elements
    );

    return h_curr;
}
"""

