import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Define the CUDA kernel and C++ wrapper
gru_cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

// Device functions for activation
__forceinline__ __device__ float sigmoid(float x) {
    return 1.0f / (1.0f + expf(-x));
}

__forceinline__ __device__ float _tanh(float x) {
    return tanhf(x);
}

// Fused GRU Cell Kernel
// gates_i: Input projections (Batch, 3*Hidden) [r_i, z_i, n_i] - includes bias_ih
// gates_h: Hidden projections (Batch, 3*Hidden) [r_h, z_h, n_h] - includes bias_hh
// h_prev: Previous hidden state (Batch, Hidden)
// h_curr: Output hidden state (Batch, Hidden)
__global__ void gru_cell_fused_kernel(
    const float* __restrict__ gates_i,
    const float* __restrict__ gates_h,
    const float* __restrict__ h_prev,
    float* __restrict__ h_curr,
    int batch_size,
    int hidden_size) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * hidden_size;

    if (idx < total_elements) {
        int b = idx / hidden_size;
        int h = idx % hidden_size;

        // Calculate offsets for the 3 gates (Reset, Update, New)
        // Stride is 3 * hidden_size for the gate tensors
        int stride = 3 * hidden_size;
        int row_offset = b * stride;

        int r_idx = row_offset + h;
        int z_idx = row_offset + hidden_size + h;
        int n_idx = row_offset + 2 * hidden_size + h;

        float gi_r = gates_i[r_idx];
        float gh_r = gates_h[r_idx];

        float gi_z = gates_i[z_idx];
        float gh_z = gates_h[z_idx];

        float gi_n = gates_i[n_idx];
        float gh_n = gates_h[n_idx];

        float h_prev_val = h_prev[idx];

        // Reset Gate: r = sigmoid(W_ir*x + b_ir + W_hr*h + b_hr)
        float r = sigmoid(gi_r + gh_r);

        // Update Gate: z = sigmoid(W_iz*x + b_iz + W_hz*h + b_hz)
        float z = sigmoid(gi_z + gh_z);

        // New Gate: n = tanh(W_in*x + b_in + r * (W_hn*h + b_hn))
        float n = _tanh(gi_n + r * gh_n);

        // Output State: h_t = (1 - z) * n + z * h_{t-1}
        float h_new = (1.0f - z) * n + z * h_prev_val;

        h_curr[idx] = h_new;
    }
}

// C++ Function to iterate over sequence
// Returns {output_sequence, last_hidden_state}
std::vector<torch::Tensor> gru_scan_cuda(
    torch::Tensor input_proj, // (Seq, Batch, 3*Hidden) - Precomputed input projections
    torch::Tensor h0,         // (Batch, Hidden)
    torch::Tensor w_hh,       // (3*Hidden, Hidden) - Recurrent weights
    torch::Tensor b_hh        // (3*Hidden) - Recurrent bias
) {
    auto seq_len = input_proj.size(0);
    auto batch_size = input_proj.size(1);
    auto hidden_size = h0.size(1);

    auto h_curr = h0.clone();
    auto output = torch::zeros({seq_len, batch_size, hidden_size}, h0.options());

    // Transpose w_hh for matrix multiplication: (3H, H) -> (H, 3H)
    // We want h_curr (B, H) @ w_hh.T (H, 3H) -> (B, 3H)
    auto w_hh_t = w_hh.t().contiguous();

    const int block_size = 256;
    const int num_blocks = (batch_size * hidden_size + block_size - 1) / block_size;

    for (int t = 0; t < seq_len; ++t) {
        // 1. Recurrent Projection: gates_h = h_curr @ w_hh.T + b_hh
        auto gates_h = torch::addmm(b_hh, h_curr, w_hh_t);

        // 2. Fused Element-wise Ops
        auto gates_i_t = input_proj[t];
        auto h_next = torch::empty_like(h_curr);

        gru_cell_fused_kernel<<<num_blocks, block_size>>>(
            gates_i_t.data_ptr<float>(),
            gates_h.data_ptr<float>(),
            h_curr.data_ptr<float>(),
            h_next.data_ptr<float>(),
            batch_size,
            hidden_size
        );

        h_curr = h_next;
        output[t] = h_curr;
    }

    return {output, h_curr};
}
"""

gru_cpp_source = """
std::vector<torch::Tensor> gru_scan_cuda(
    torch::Tensor input_proj,
    torch::Tensor h0,
    torch::Tensor w_hh,
    torch::Tensor b_hh);
"""

# Compile the inline extension
custom_gru = load_inline(
    name="custom_gru_ops",
    cpp_sources=gru_cpp_source,
    cuda_sources=gru_cuda_source,
    functions=["gru_scan_cuda"],
    verbose=False,
    extra_cuda_cflags=["-O3"]
