class FusedGRULayer(nn.Module):
    def __init__(self, input_size, hidden_size):
        super(FusedGRULayer, self).__init__()
        self.input_size = input_size
        self.hidden_size = hidden_size

        # Parameters for Forward direction
        self.w_ih_f = nn.Parameter(torch.empty(3 * hidden_size, input_size))
        self.w_hh_f = nn.Parameter(torch.empty(3 * hidden_size, hidden_size))
        self.b_ih_f = nn.Parameter(torch.empty(3 * hidden_size))
        self.b_hh_f = nn.Parameter(torch.empty(3 * hidden_size))

        # Parameters for Reverse direction
        self.w_ih_r = nn.Parameter(torch.empty(3 * hidden_size, input_size))
        self.w_hh_r = nn.Parameter(torch.empty(3 * hidden_size, hidden_size))
        self.b_ih_r = nn.Parameter(torch.empty(3 * hidden_size))
        self.b_hh_r = nn.Parameter(torch.empty(3 * hidden_size))

        self.reset_parameters()

    def reset_parameters(self):
        stdv = 1.0 / (self.hidden_size ** 0.5)
        for p in self.parameters():
            nn.init.uniform_(p, -stdv, stdv)

    def forward(self, x, h_prev):
        # x: (Seq, Batch, Input)
        # h_prev: (2, Batch, Hidden) -> [h_fwd, h_rev]

        # --- Forward Direction ---
        # Pre-compute input projection for all timesteps: x @ W_ih.T + b_ih
        # Collapsing Seq and Batch for one large matmul
        S, B, I = x.shape
        x_flat = x.view(-1, I)

        gates_i_f = torch.addmm(self.b_ih_f, x_flat, self.w_ih_f.t())
        gates_i_f = gates_i_f.view(S, B, -1)

        # Run fused GRU scan
        out_f, h_last_f = custom_gru.gru_scan_cuda(gates_i_f, h_prev[0], self.w_hh_f, self.b_hh_f)

        # --- Reverse Direction ---
        # Flip input sequence
        x_rev = x.flip(0)
        x_rev_flat = x_rev.view(-1, I)

        gates_i_r = torch.addmm(self.b_ih_r, x_rev_flat, self.w_ih_r.t())
        gates_i_r = gates_i_r.view(S, B, -1)

        # Run fused GRU scan
        out_r, h_last_r = custom_gru.gru_scan_cuda(gates_i_r, h_prev[1], self.w_hh_r, self.b_hh_r)

        # Flip output back
        out_r = out_r.flip(0)

        # Concatenate forward and reverse outputs
        output = torch.cat([out_f, out_r], dim=-1)

        # Stack hidden states
        h_next = torch.stack([h_last_f, h_last_r], dim=0)

        return output, h_next

class ModelNew(nn.Module):
    def __init__(self, input_size, hidden_size, num_layers=3, bias=True, batch_first=False):
        super(ModelNew, self).__init__()
        self.num_layers = num_layers
        self.hidden_size = hidden_size
        self.batch_first = batch_first

        self.layers = nn.ModuleList()
        for i in range(num_layers):
            # Input size for layer 0 is input_size, for others it is 2 * hidden_size (bidirectional output)
            layer_input_size = input_size if i == 0 else hidden_size * 2
            self.layers.append(FusedGRULayer(layer_input_size, hidden_size))

    def forward(self, x, h0):
        # x: (Seq, Batch, Input)
        # h0: (NumLayers * 2, Batch, Hidden)

        current_input = x

        # No h_n required to be returned based on prompt logic (only output), 
        # but we need to track h across layers if h0 is provided.

        for i, layer in enumerate(self.layers):
            # Extract initial hidden states for this layer (Forward and Reverse)
            h_layer_init = h0[2*i : 2*i+2]

            output, _ = layer(current_input, h_layer_init)
            current_input = output

        return current_input

