#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Fused GRU Cell Kernel
// Computes:
// r = sigmoid(gx_r + gh_r)
// z = sigmoid(gx_z + gh_z)
// n = tanh(gx_n + r * gh_n)
// h_new = (1 - z) * n + z * h_prev
__global__ void gru_cell_fused_kernel(
    const float* __restrict__ gx, 
    const float* __restrict__ gh, 
    const float* __restrict__ h_prev, 
    float* __restrict__ h_out, 
    int batch_size,
    int hidden_size) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * hidden_size;

    if (idx < total_elements) {
        int batch_idx = idx / hidden_size;
        int feat_idx = idx % hidden_size;

        // The input tensors are shape [Batch, 3 * Hidden]
        // Stride is 3 * hidden_size
        int stride = 3 * hidden_size;

        // Offsets for r, z, n gates within the 3*Hidden dimension
        // PyTorch GRU layout is usually r, z, n (reset, input, new)
        int r_idx = batch_idx * stride + feat_idx;
        int z_idx = batch_idx * stride + hidden_size + feat_idx;
        int n_idx = batch_idx * stride + 2 * hidden_size + feat_idx;

        float gx_r = gx[r_idx];
        float gx_z = gx[z_idx];
        float gx_n = gx[n_idx];

        float gh_r = gh[r_idx];
        float gh_z = gh[z_idx];
        float gh_n = gh[n_idx];

        // Sigmoid r
        float r = 1.0f / (1.0f + expf(-(gx_r + gh_r)));

        // Sigmoid z
        float z = 1.0f / (1.0f + expf(-(gx_z + gh_z)));

        // Tanh n
        // n = tanh(Win x + bin + r * (Whn h + bhn))
        // Note that gx includes bias, gh includes bias.
        // We sum them. For n, r gates the hidden part.
        float n = tanhf(gx_n + r * gh_n);

        float h_prev_val = h_prev[idx];
        float h_new = (1.0f - z) * n + z * h_prev_val;

        h_out[idx] = h_new;
    }
}

