# Define the custom CUDA kernel for Fused Scale-Mask-Softmax
# This kernel replaces:
# 1. Scaling by 1/sqrt(d_k)
# 2. Causal masking (masked_fill) - done implicitly via index comparison to save memory bandwidth
# 3. Softmax (max, exp, sum, div) - done in a single pass (fused) for speed and numerical stability
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_causal_softmax_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const int batch_dim,
    const int T,
    const float scale) {

    // Helper for warp reduction
    int lane = threadIdx.x % 32;
    int warp = threadIdx.x / 32;

    int row = blockIdx.x; // Which row in the matrix (0 to T-1)
    int b = blockIdx.y;   // Which head in the batch (0 to B*NH-1)

    // Global offset to the start of the row
    // Input is flattened (B*NH, T, T)
    // Offset = Batch_idx * T^2 + Row_idx * T
    int row_offset = b * T * T + row * T;

    // Each thread loads one element from the row (assuming T <= blockDim.x)
    // Initialize with -infinity for max reduction
    float val = -INFINITY;
    if (threadIdx.x < T) {
        // Causal Masking: only allow attention to past positions (col <= row)
        // This avoids reading a large bias matrix from memory
        if (threadIdx.x <= row) {
            val = input[row_offset + threadIdx.x] * scale;
        }
    }

    // 1. Find Max for numerical stability (Online Softmax / Safe Softmax)
    float max_val = val;

    // Warp reduce max
    for (int offset = 16; offset > 0; offset /= 2) {
        max_val = max(max_val, __shfl_down_sync(0xffffffff, max_val, offset));
    }

    // Shared memory for warp results (max 32 warps for 1024 threads)
    __shared__ float shared_max[32]; 
    if (lane == 0) shared_max[warp] = max_val;
    __syncthreads();

    // Block reduce max (performed by first thread)
    if (threadIdx.x == 0) {
        float block_max = -INFINITY;
        int num_warps = (blockDim.x + 31) / 32;
        for (int i = 0; i < num_warps; ++i) {
            block_max = max(block_max, shared_max[i]);
        }
        shared_max[0] = block_max; // Broadcast back via shared mem
    }
    __syncthreads();
    float global_max = shared_max[0];

    // 2. Compute Exponentials and Sum
    float exp_val = 0.0f;
    if (threadIdx.x < T) {
        // If masked (-inf), exp is 0.
        exp_val = expf(val - global_max);
    }

    float sum_val = exp_val;
    // Warp reduce sum
    for (int offset = 16; offset > 0; offset /= 2) {
        sum_val += __shfl_down_sync(0xffffffff, sum_val, offset);
    }

    __shared__ float shared_sum[32];
    if (lane == 0) shared_sum[warp] = sum_val;
    __syncthreads();

    // Block reduce sum
    if (threadIdx.x == 0) {
        float block_sum = 0.0f;
        int num_warps = (blockDim.x + 31) / 32;
        for (int i = 0; i < num_warps; ++i) {
            block_sum += shared_sum[i];
        }
        shared_sum[0] = block_sum;
    }
    __syncthreads();
    float global_sum = shared_sum[0];

    // 3. Normalize and Store
    if (threadIdx.x < T) {
        output[row_offset + threadIdx.x] = exp_val / (global_sum + 1e-6f);
    }
}

torch::Tensor causal_softmax_cuda(torch::Tensor input, float scale) {
