    // We interpret it as a grid of (B*NH) matrices of size (T, T)
    int B = input.size(0);
    int NH = input.size(1);
    int T = input.size(2);
    int batch_dim = B * NH;

    auto output = torch::empty_like(input);

    // Block size: T rounded up to nearest 32, max 1024.
    // This assumes T <= 1024. 
    int threads = (T < 1024) ? ((T + 31) / 32) * 32 : 1024;

    dim3 block(threads);
    // Grid: x = rows, y = batch elements
    dim3 grid(T, batch_dim);

    fused_causal_softmax_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_dim,
        T,
        scale
    );

    return output;
