            s_data[tid] = fmaxf(s_data[tid], s_data[tid + stride]);
        }
        __syncthreads();
    }
    float max_val = s_data[0];
    __syncthreads();

    // ------------------------------------------------------------------
    // 3. Compute Exp and Sum
    // ------------------------------------------------------------------
    float exp_val = 0.0f;
