        // Re-calculate val from BN parameters is not needed, we lost it in s_data
        // But we can re-compute or we could have stored it in registers? 
        // To save register pressure, let's just re-read x or recompute. 
        // Actually, better: separate arrays? Shared mem is small.
        // Let's re-read x from global. It's cached in L1/L2 likely.

        float in_val = x[row_offset + tid];
        float bn_val = (in_val - mu) * inv_std * gamma + beta;

        // Online Softmax trick: exp(x - max)
        exp_val = expf(bn_val - max_val);
    }

    s_data[tid] = exp_val;
    __syncthreads();

    // Reduce Sum
    for (int stride = 256; stride > 0; stride >>= 1) {
        if (tid < stride) {
            s_data[tid] += s_data[tid + stride];
        }
        __syncthreads();
    }
    float sum_val = s_data[0];
    // __syncthreads(); // Not strictly needed as we only read s_data[0] now

    // ------------------------------------------------------------------
    // 4. Normalize and Store
    // ------------------------------------------------------------------
    if (tid < W) {
        y[row_offset + tid] = exp_val / (sum_val + 1e-12f); // avoid div 0
    }
}

