cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Kernel 1: Fused Softmax, Slice (remove ghosts), and Sum
// Computes soft assignments and their sum over the sequence dimension N.
// Input: logits (B, N, K + G)
// Output: assignment (B, N, K), assign_sum (B, K)
__global__ void softmax_slice_sum_kernel(
    const float* __restrict__ logits,
    float* __restrict__ assignment,
    float* __restrict__ assign_sum,
    int N,
    int clusters,
    int ghost) {

    // Helper vars
    int total_clusters = clusters + ghost;
    int b = blockIdx.x;
    int n = threadIdx.x;

    // Shared memory to store probabilities for reduction across N
    // Size required: N * clusters.
    // Dynamically allocated.
    extern __shared__ float smem[];

    // 1. Compute Softmax for the n-th sample in batch b
    if (n < N) {
        int row_offset = b * N * total_clusters + n * total_clusters;
        const float* row_logits = logits + row_offset;

        // Compute Max for numerical stability
        float max_val = -1e30f;
        for (int k = 0; k < total_clusters; ++k) {
            float val = row_logits[k];
            if (val > max_val) max_val = val;
        }

        // Compute Sum of Exponentials
        float sum_exp = 0.0f;
        for (int k = 0; k < total_clusters; ++k) {
            sum_exp += expf(row_logits[k] - max_val);
        }
        float inv_sum = 1.0f / (sum_exp + 1e-8f); // Add epsilon just in case

        // Compute Softmax and store only the first 'clusters' (slice)
        int assign_row_offset = b * N * clusters + n * clusters;
        float* row_assign = assignment + assign_row_offset;

        for (int k = 0; k < clusters; ++k) {
            float prob = expf(row_logits[k] - max_val) * inv_sum;
            row_assign[k] = prob;
            smem[n * clusters + k] = prob; // Store to shared mem for reduction
        }
    }

    __syncthreads();

    // 2. Reduce sum over N for each cluster k
    // We use the first 'clusters' threads to perform the column-wise sum from shared memory.
    // Assuming blockDim.x >= clusters (32 is small, usually block is 128+)
    if (threadIdx.x < clusters) {
        int k = threadIdx.x;
        float sum_k = 0.0f;
        for (int i = 0; i < N; ++i) {
            sum_k += smem[i * clusters + k];
        }
        assign_sum[b * clusters + k] = sum_k;
    }
}

// Kernel 2: Residual Accumulation and Intra-Normalization
// Fuses the subtraction of cluster centers (weighted by assignment sums) and L2 normalization over D.
// Input: 
//   vlad (B, K, D) - result of assignment^T @ x
//   a_sum (B, K)   - sum of assignments
//   centroids (D, K) - cluster centers (transposed/viewed from (1, D, K))
// Output:
//   vlad (B, K, D) - modified in-place
__global__ void residual_intra_norm_kernel(
    float* __restrict__ vlad,
    const float* __restrict__ a_sum,
    const float* __restrict__ centroids,
    int K,
    int D) {

    // Grid: (B, K)
    // Block: (D) (assuming D <= 1024)

    int b = blockIdx.x;
    int k = blockIdx.y;
    int d = threadIdx.x;

    if (d < D) {
        // Calculate indices
        int vlad_idx = b * K * D + k * D + d;
        int a_idx = b * K + k;
        // centroids is (1, D, K), contiguous memory. C[0, d, k] is at index d*K + k.
        int c_idx = d * K + k; 

        // 1. Subtract weighted centroid: vlad = vlad - a_sum * c
        float val = vlad[vlad_idx];
        float w = a_sum[a_idx];
        float c = centroids[c_idx];
        val = val - w * c;

        // 2. Intra-normalization (L2 norm over D dimension)
        // We need the sum of squares of 'val' across the block (d=0..D-1)

        // Shared memory for block reduction
        // Declare static size sufficient for common feature sizes (512, 1024)
        __shared__ float s_sq[1024]; 

        s_sq[d] = val * val;
        __syncthreads();

        // Parallel reduction
        for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
            if (d < stride) {
                s_sq[d] += s_sq[d + stride];
            }
            __syncthreads();
        }

        float norm = sqrtf(s_sq[0] + 1e-12f);
        val = val / norm;

        // Write back
        vlad[vlad_idx] = val;
    }
}

