        # Reshape: BN x D
        x_flat = x.view(-1, D)

        if x.device != self.clusters.device:
             raise ValueError(f"x.device {x.device} != cluster.device {self.clusters.device}")

        # BN x (K+G)
        assignment = torch.matmul(x_flat, self.clusters)

        # BatchNorm
        assignment = self.batch_norm(assignment)

        # 2. Fused Softmax + Slice + Sum (Custom CUDA)
        # Input: (BN, K+G)
        # Output: assign (B, N, K), assign_sum (B, K)
        # This replaces Softmax, Slice, Reshape, Sum
        assign, assign_sum = netvlad_cuda.netvlad_preprocess(
            assignment, N, self.cluster_size, self.ghost_clusters
        )

        # 3. VLAD Accumulation (Matrix Multiplication)
        # Formula part 1: sum(a_i * x_i) = A^T @ X
        # assign: (B, N, K) -> permute to (B, K, N)
        # x: (B, N, D)
        # vlad: (B, K, D)
        vlad = torch.bmm(assign.transpose(1, 2), x)

        # 4. Residual Subtraction + Intra Normalization (Custom CUDA)
        # Input: vlad (B, K, D), assign_sum (B, K), centroids (1, D, K)
        # Operations:
        #   vlad -= assign_sum * centroids
        #   vlad = normalize(vlad, dim=-1) [dim corresponding to D]
        # In-place modification of 'vlad'
        netvlad_cuda.netvlad_postprocess(vlad, assign_sum, self.clusters2)

        # 5. Global Normalization & Formatting
        # Current vlad shape: (B, K, D)
        # Original logic requires: (B, D, K) then reshape (-1, D*K)
        # The reshape order matters. Flattening (D, K) vs (K, D) is different.
        # We transpose to match the original layout before flattening.
        vlad = vlad.transpose(1, 2) # -> B x D x K

        # Flatten + L2 Norm
        vlad = vlad.reshape(-1, self.out_dim) # -> B x DK
        vlad = F.normalize(vlad)

        return vlad

