import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

# Define custom CUDA kernel for NetVLAD aggregation and intra-normalization
# This kernel fuses:
# 1. Weighted aggregation of residuals: V_dk = sum_n(a_nk * (x_nd - c_dk))
# 2. L2 Intra-normalization along dimension D
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__inline__ __device__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__inline__ __device__ float blockReduceSum(float val) {
    static __shared__ float shared[32]; 
    int lane = threadIdx.x % 32;
    int wid = threadIdx.x / 32;

    val = warpReduceSum(val);

    if (lane == 0) shared[wid] = val;
    __syncthreads();

    // Assuming blockDim.x is 512 or similar (multiple of 32).
    // Load partial sums from shared memory. 
    // We only need the first warp to reduce the partial sums.
    float val_block = (threadIdx.x < (blockDim.x / 32)) ? shared[threadIdx.x] : 0.0f;

    if (wid == 0) {
        val_block = warpReduceSum(val_block);
        if (threadIdx.x == 0) shared[0] = val_block;
    }
    __syncthreads();

    return shared[0];
}

__global__ void netvlad_aggregate_kernel(
    const float* __restrict__ x,         // [B, N, D]
    const float* __restrict__ assign,    // [B, N, K]
    const float* __restrict__ clusters,  // [D, K]
    float* __restrict__ out,             // [B, D, K]
    int B, int N, int D, int K) {

    // Grid: (B, K)
    // Block: (D) -- Optimized for D=512.

    int b = blockIdx.x;
    int k = blockIdx.y;
    int d = threadIdx.x;

    if (d >= D) return;

    // Offsets
    // x: [b, n, d] -> b*(N*D) + n*D + d
    // Stride to next n is D.
    const float* x_ptr = x + b * (N * D) + d;

    // assign: [b, n, k] -> b*(N*K) + n*K + k
    // Stride to next n is K.
    const float* assign_ptr = assign + b * (N * K) + k;

    float sum_ax = 0.0f;
    float sum_a = 0.0f;

    // Accumulate weighted sums over N
    // This loop is coalesced for x read (adjacent threads read adjacent d)
    // assign read is broadcast (adjacent threads read same assign value)
    for (int n = 0; n < N; ++n) {
        float val = *x_ptr;
        float w = *assign_ptr;

        sum_ax += w * val;
        sum_a += w;

        x_ptr += D;
        assign_ptr += K;
    }

    // clusters: [d, k]. Stride for d is K.
    float c = clusters[d * K + k];

    // Compute residual: sum(a*x) - sum(a)*c
    float res = sum_ax - sum_a * c;

    // Intra-normalization (L2 norm along D)
    float sq = res * res;
    float sum_sq = blockReduceSum(sq);
    float inv_norm = rsqrtf(sum_sq + 1e-12f);

    // Output: [b, d, k]
    out[b * (D * K) + d * K + k] = res * inv_norm;
}

torch::Tensor netvlad_cuda(torch::Tensor x, torch::Tensor assign, torch::Tensor clusters) {
    int B = x.size(0);
    int N = x.size(1);
    int D = x.size(2);
    int K = assign.size(2);

    auto out = torch::empty({B, D, K}, x.options());

    // Launch configuration
    // We map dimension D to threads in the block.
    // This assumes D fits in a block (D <= 1024). 
    // For NetVLAD with D=512, this is efficient.
    dim3 block(D);
    dim3 grid(B, K);

    netvlad_aggregate_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        assign.data_ptr<float>(),
        clusters.data_ptr<float>(),
        out.data_ptr<float>(),
        B, N, D, K
    );

    return out;
}
