# Custom CUDA Kernel for SSM Intra-Chunk Computation
# Fuses the O(L^2) diagonal computation and state recurrence into a single O(L) kernel.
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void ssm_intra_kernel(
    const float* __restrict__ X,
    const float* __restrict__ A,
    const float* __restrict__ B,
    const float* __restrict__ C,
    float* __restrict__ Y,
    float* __restrict__ FinalState,
    int batch_size,
    int n_chunks,
    int seq_len,
    int n_heads,
    int d_head,
    int d_state
) {
    // Grid: (batch * chunks * heads)
    // Block: d_head (mapping one thread per head dimension)

    int idx = blockIdx.x;
    int h = idx % n_heads;
    int temp = idx / n_heads;
    int c = temp % n_chunks;
    int b = temp / n_chunks;

    int tid = threadIdx.x; 
    if (tid >= d_head) return;

    // Strides for input tensors (assuming specific layout after rearrange)
    // X, Y: (B, C, L, H, P)
    int stride_X_b = n_chunks * seq_len * n_heads * d_head;
    int stride_X_c = seq_len * n_heads * d_head;
    int stride_X_l = n_heads * d_head;
    int stride_X_h = d_head;

    // A: (B, H, C, L)
    int stride_A_b = n_heads * n_chunks * seq_len;
    int stride_A_h = n_chunks * seq_len;
    int stride_A_c = seq_len;

    // B, C: (B, C, L, H, N)
    int stride_B_b = n_chunks * seq_len * n_heads * d_state;
    int stride_B_c = seq_len * n_heads * d_state;
    int stride_B_l = n_heads * d_state;
    int stride_B_h = d_state;

    // FinalState: (B, C, H, P, N)
    int stride_S_b = n_chunks * n_heads * d_head * d_state;
    int stride_S_c = n_heads * d_head * d_state;
    int stride_S_h = d_head * d_state;
    int stride_S_p = d_state;

    // Base Pointers
    const float* x_ptr = X + b*stride_X_b + c*stride_X_c + h*stride_X_h + tid; // Points to X[b,c,0,h,tid]
    const float* a_ptr = A + b*stride_A_b + h*stride_A_h + c*stride_A_c;       // Points to A[b,h,c,0]
    const float* b_base = B + b*stride_B_b + c*stride_B_c + h*stride_B_h;      // Points to B[b,c,0,h,0]
    const float* c_base = C + b*stride_B_b + c*stride_B_c + h*stride_B_h;      // Same shape as B

    float* y_ptr = Y + b*stride_X_b + c*stride_X_c + h*stride_X_h + tid;
    float* s_ptr = FinalState + b*stride_S_b + c*stride_S_c + h*stride_S_h + tid * stride_S_p;

    // Local State Accumulator (d_state is typically small, e.g., 16)
    // We keep state in registers. 
    // Max d_state 16 supported by this unroll, can be increased.
    float state[16];
