        float exp_a = expf(cum_a);
        float exp_neg_a = expf(-cum_a);

        float x_val = x_ptr[t * stride_X_l];
        const float* b_t = b_base + t * stride_B_l;
        const float* c_t = c_base + t * stride_B_l;

