import torch
import torch.nn as nn
import torch.nn.functional as F
from einops import rearrange
from torch.utils.cpp_extension import load_inline

# -----------------------------------------------------------------------------
# CUDA Kernel: Causal Exponential Segment Sum
# -----------------------------------------------------------------------------
# This kernel fuses the computation of segment sums, masking, and exponentiation.
# It replaces the naive PyTorch implementation:
# L = exp(cumsum(x)[:, None] - cumsum(x)[None, :]) * Mask
# Input: A tensor of shape (batch_dims..., L)
# Output: A tensor of shape (batch_dims..., L, L)
# -----------------------------------------------------------------------------

cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void causal_exp_segsum_kernel(
    const float* __restrict__ A, 
    float* __restrict__ Out, 
    int L, 
    int num_batches) {

    // Shared memory for the cumulative sum of a single row/block.
    // L corresponds to block_len (e.g., 64).
    extern __shared__ float shm_cumsum[];

    int b = blockIdx.x;
    if (b >= num_batches) return;

    // Pointers for this batch
    const float* A_ptr = A + b * L;
    float* Out_ptr = Out + b * L * L;

    // Thread 0 computes the cumulative sum for the block.
    // Since L is small (block_len=64), serial computation in shared memory is efficient
    // and avoids complex parallel reduction overhead.
    if (threadIdx.x == 0) {
        float current_sum = 0.0f;
        for (int i = 0; i < L; ++i) {
            current_sum += A_ptr[i];
            shm_cumsum[i] = current_sum;
        }
    }
    __syncthreads();

    // Parallelize the output matrix generation (L x L elements)
    int total_elements = L * L;
    for (int idx = threadIdx.x; idx < total_elements; idx += blockDim.x) {
        int row = idx / L;
        int col = idx % L;

        if (row >= col) {
            // L[i, j] = exp(cumsum[i] - cumsum[j])
            // Note: This logic matches the provided segsum implementation
            // where x_segsum = x_cumsum[..., :, None] - x_cumsum[..., None, :]
            float val = shm_cumsum[row] - shm_cumsum[col];
            Out_ptr[idx] = expf(val);
        } else {
            // Masked out (causal)
            Out_ptr[idx] = 0.0f;
        }
    }
}

torch::Tensor causal_exp_segsum_cuda(torch::Tensor A) {
    TORCH_CHECK(A.is_cuda(), "Input tensor A must be on CUDA");
    TORCH_CHECK(A.is_contiguous(), "Input tensor A must be contiguous");

    int L = A.size(-1);
    // Flatten all batch dimensions
    int num_batches = A.numel() / L;

    // Output shape: (Batch..., L, L) -> Flattened to (num_batches, L, L)
    auto out = torch::empty({num_batches, L, L}, A.options());

    const int threads = 256;
    const int blocks = num_batches;
    // Allocate shared memory for the cumulative sum vector
    int shm_size = L * sizeof(float);

    causal_exp_segsum_kernel<<<blocks, threads, shm_size>>>(
        A.data_ptr<float>(), 
        out.data_ptr<float>(), 
        L, 
        num_batches
    );

    return out;
}
"""

