        C_p = C_blocks.permute(0, 1, 3, 2, 4) # b c h l n
        B_p = B_blocks.permute(0, 1, 3, 2, 4) # b c h s n (s=l)
        X_p = X_blocks.permute(0, 1, 3, 2, 4) # b c h s p
        L_p = L.permute(0, 2, 1, 3, 4)        # b c h l s

        # K = C @ B.T -> (b c h l s)
