        # (b, h, z, c) @ (b, h, c, pn) -> (b, h, z, pn)
        new_states = torch.matmul(decay_chunk, states_flat)

        # Reshape back and permute
        new_states = new_states.reshape(b, h, num_chunks, p, n).permute(0, 2, 1, 3, 4)

        return new_states[:, -1]

