    // Each block handles one (batch, head) pair.
    int bh = blockIdx.x;
    if (bh >= B_sz * H_sz) return;
    int b = bh / H_sz;
    int h = bh % H_sz;

    // Parallelize over d_head (P) and d_state (N) dimensions.
    for (int p = threadIdx.x; p < P_sz; p += blockDim.x) {
        for (int n = threadIdx.y; n < N_sz; n += blockDim.y) {
            float state = 0.0f;
            if (initial_states != nullptr) {
                // Initial state shape is (B, 1, H, P, N)
                state = initial_states[((b * H_sz + h) * P_sz + p) * N_sz + n];
            }

            // Linear recurrence over the sequence length L.
            for (int t = 0; t < L_sz; ++t) {
                // Flattened index for A(b, t, h)
                int base_idx = (b * L_sz + t) * H_sz + h;
                float a_val = A[base_idx];
                // Flattened index for X(b, t, h, p) and B(b, t, h, n)
                float x_val = X[base_idx * P_sz + p];
                float b_val = B[base_idx * N_sz + n];

                state = expf(a_val) * state + x_val * b_val;
            }
            // Final output shape: (B, H, P, N)
            out[((b * H_sz + h) * P_sz + p) * N_sz + n] = state;
        }
    }
}

torch::Tensor ssd_final_state_cuda(torch::Tensor X, torch::Tensor A, torch::Tensor B, torch::Tensor initial_states) {
    int B_sz = X.size(0);
    int L_sz = X.size(1);
    int H_sz = X.size(2);
    int P_sz = X.size(3);
    int N_sz = B.size(3);

    auto out = torch::empty({B_sz, H_sz, P_sz, N_sz}, X.options());

    dim3 grid(B_sz * H_sz);
    dim3 block(32, 32); // 1024 threads

    const float* initial_states_ptr = initial_states.defined() && initial_states.numel() > 0 ? initial_states.data_ptr<float>() : nullptr;

    ssd_final_state_kernel<<<grid, block>>>(
        X.data_ptr<float>(),
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        initial_states_ptr,
        out.data_ptr<float>(),
        B_sz, L_sz, H_sz, P_sz, N_sz
    );

    return out;
}
"""

ssd_kernel_cpp_source = (
    "torch::Tensor ssd_final_state_cuda(torch::Tensor X, torch::Tensor A, torch::Tensor B, torch::Tensor initial_states);"
)

# Compile the custom CUDA kernel
ssd_kernel = load_inline(
    name="ssd_kernel",
    cpp_sources=ssd_kernel_cpp_source,
    cuda_sources=ssd_kernel_source,
    functions=["ssd_final_state_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, batch_size, seq_length, n_heads, d_head, d_state, block_len=64):
        """
        Optimized Mamba Structured State Space model implementation using custom CUDA kernels.
        The implementation replaces the high-memory O(L^2) chunked calculation with an O(L) 
        linear recurrence kernel to compute the final state.
        """
        super(ModelNew, self).__init__()

        self.batch_size = batch_size
        self.seq_length = seq_length
        self.n_heads = n_heads
        self.d_head = d_head
        self.d_state = d_state
        self.block_len = block_len

        # Initialize parameters exactly like the original Model
        self.A = nn.Parameter(torch.randn(batch_size, seq_length, n_heads))
        self.B = nn.Parameter(torch.randn(batch_size, seq_length, n_heads, d_state))
        self.C = nn.Parameter(torch.randn(batch_size, seq_length, n_heads, d_state))

        self.ssd_kernel = ssd_kernel

    def forward(self, X, initial_states=None):
        """
        Optimized forward pass using the custom CUDA recurrence kernel.
        :param X: Input tensor of shape (batch, length, n_heads, d_head)
        :param initial_states: Optional initial states of shape (batch, 1, n_heads, d_head, d_state)
        :return: Final state tensor of shape (batch, n_heads, d_head, d_state)
        """
        if initial_states is None:
            # Create an undefined tensor to signal the kernel to start from zero state
            initial_states = torch.empty(0, device=X.device, dtype=X.dtype)
        else:
            # If initial_states are provided, we ensure it's on the correct device/dtype
            # and potentially slice it if it contains multiple chunk states.
            if initial_states.dim() == 5:
                # Shape is (B, C, H, P, N), original cat logic suggests using the first chunk as init
                initial_states = initial_states[:, 0].contiguous()

        # The CUDA kernel performs the scan/recurrence across the whole sequence in a single pass.
        return self.ssd_kernel.ssd_final_state_cuda(X, self.A, self.B, initial_states)

