import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

# Define custom CUDA kernels for the attention mechanism
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

// Kernel 1: Rearrange QKV
// Efficiently splits the output of the first linear layer into Q, K, V
// and performs the necessary transpose/view operations to shape them as (B, NH, T, HS).
// Replaces: split -> view -> transpose
__global__ void rearrange_qkv_kernel(
    const float* __restrict__ x,
    float* __restrict__ q,
    float* __restrict__ k,
    float* __restrict__ v,
    int B, int T, int NH, int HS
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * NH * T * HS;

    if (idx < total) {
        // Map linear index to (b, nh, t, hs)
        int hs = idx % HS;
        int temp = idx / HS;
        int t = temp % T;
        temp = temp / T;
        int nh = temp % NH;
        int b = temp / NH;

        // Input strides
        int C = NH * HS;
        int stride_b = T * 3 * C;
        int stride_t = 3 * C;

        // Calculate offset in source tensor x (B, T, 3*C)
        // x layout at last dim is [Q_chunk, K_chunk, V_chunk] where each chunk is (NH, HS) flattened
        // But the split was on dim=2 (embedding dim), so linearly it's [q_0..q_n, k_0..k_n, v_0..v_n] for each (b,t)
        int base_offset = b * stride_b + t * stride_t + nh * HS + hs;

        q[idx] = x[base_offset];
        k[idx] = x[base_offset + C];
        v[idx] = x[base_offset + 2 * C];
    }
}

// Kernel 2: Masked Scaled ReLU
// Fuses scaling, causal masking, and ReLU activation into a single element-wise kernel.
// Replaces: * scale -> masked_fill -> relu
__global__ void masked_scaled_relu_kernel(
    float* __restrict__ att,
    float scale,
    int T,
    int total
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total) {
        // Need row and col indices within the TxT attention matrix
        // Shape is (B, NH, T, T)
        int col = idx % T;
        int row = (idx / T) % T;

        // Causal mask: only attend to past (col <= row)
        if (col > row) {
            att[idx] = 0.0f;
        } else {
            float val = att[idx] * scale;
            // ReLU activation
            att[idx] = (val > 0.0f) ? val : 0.0f;
        }
    }
}

// Kernel 3: Rearrange Output
// Efficiently reshapes the output of attention back to (B, T, C).
// Replaces: transpose -> contiguous -> view
__global__ void rearrange_output_kernel(
    const float* __restrict__ y,
    float* __restrict__ out,
    int B, int T, int NH, int HS
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * T * NH * HS;

    if (idx < total) {
        // idx iterates over output (B, T, C) which is contiguous
        int hs = idx % HS;
        int temp = idx / HS;
        int nh = temp % NH;
        int temp2 = temp / NH;
        int t = temp2 % T;
        int b = temp2 / T;

        // Input y is (B, NH, T, HS)
        // We map (b, t, nh, hs) from output to (b, nh, t, hs) in input
        int input_idx = b * (NH * T * HS) + nh * (T * HS) + t * HS + hs;

        out[idx] = y[input_idx];
    }
}

// C++ Helper functions to launch kernels
std::vector<torch::Tensor> rearrange_qkv_cuda(torch::Tensor x, int n_head) {
    auto B = x.size(0);
    auto T = x.size(1);
    auto C3 = x.size(2);
    auto C = C3 / 3;
    auto HS = C / n_head;

    auto opts = x.options();
    auto q = torch::empty({B, n_head, T, HS}, opts);
    auto k = torch::empty({B, n_head, T, HS}, opts);
    auto v = torch::empty({B, n_head, T, HS}, opts);

    int total = B * n_head * T * HS;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    rearrange_qkv_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        B, T, n_head, HS
    );

    return {q, k, v};
}

torch::Tensor masked_scaled_relu_cuda(torch::Tensor att, float scale) {
    int T = att.size(-1);
    int total = att.numel();
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    // In-place modification
    masked_scaled_relu_kernel<<<blocks, threads>>>(
        att.data_ptr<float>(),
        scale,
        T,
        total
    );
    return att;
}

torch::Tensor rearrange_output_cuda(torch::Tensor y) {
    auto B = y.size(0);
    auto NH = y.size(1);
    auto T = y.size(2);
    auto HS = y.size(3);

    auto out = torch::empty({B, T, NH * HS}, y.options());

    int total = out.numel();
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    rearrange_output_kernel<<<blocks, threads>>>(
        y.data_ptr<float>(),
        out.data_ptr<float>(),
        B, T, NH, HS
    );

    return out;
}
"""

cpp_source = """
std::vector<torch::Tensor> rearrange_qkv_cuda(torch::Tensor x, int n_head);
torch::Tensor masked_scaled_relu_cuda(torch::Tensor att, float scale);
torch::Tensor rearrange_output_cuda(torch::Tensor y);
"""

# Compile the inline CUDA code
custom_ops = load_inline(
    name="custom_attention_ops",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["rearrange_qkv_cuda", "masked_scaled_relu_cuda", "rearrange_output_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized multi-head masked self-attention layer using custom CUDA kernels.
    """

    def __init__(self, n_embd, n_head, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.n_head = n_head
        self.n_embd = n_embd
        # We no longer need the 'bias' buffer as the causal masking is fused into the CUDA kernel.

    def forward(self, x):
        B, T, C = x.size()

        # 1. Linear Projection
        # (B, T, C) -> (B, T, 3C)
        qkv_combined = self.c_attn(x)

        # 2. Custom Kernel: Split and Rearrange Q, K, V
        # Fuses split, view, and transpose operations.
        # Outputs are contiguous (B, NH, T, HS), ready for batch matmul.
        q, k, v = custom_ops.rearrange_qkv_cuda(qkv_combined, self.n_head)

        # 3. Batch Matrix Multiplication for Attention Scores
        # (B, NH, T, HS) @ (B, NH, HS, T) -> (B, NH, T, T)
        # We rely on PyTorch's optimized cuBLAS wrapper for the heavy GEMM.
        # k.transpose(-2, -1) is handled efficiently by strided matmul or we can physically transpose if needed,
        # but PyTorch handles (A @ B.mT) well.
        att = torch.matmul(q, k.transpose(-2, -1))

        # 4. Custom Kernel: Scale, Mask, and ReLU
        # Fuses scaling, causal masking (tril), and ReLU activation.
        hs = C // self.n_head
        scale = 1.0 / math.sqrt(hs)
        att = custom_ops.masked_scaled_relu_cuda(att, scale)

        # 5. Weighted Sum
        # (B, NH, T, T) @ (B, NH, T, HS) -> (B, NH, T, HS)
        y = torch.matmul(att, v)

        # 6. Custom Kernel: Rearrange Output
        # Fuses transpose, contiguous, and view.
        # (B, NH, T, HS) -> (B, T, C)
        y = custom_ops.rearrange_output_cuda(y)

        # 7. Output Projection
        y = self.c_proj(y)

        return y

