__global__ void split_transpose_kernel(const float* input, float* q, float* k, float* v, int B, int T, int nh, int hs) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int C = nh * hs;
    int total = B * T * 3 * C;
    if (idx < total) {
        int i_c = idx % (3 * C);
        int i_t = (idx / (3 * C)) % T;
        int i_b = idx / (3 * C * T);

        int qkv_idx = i_c / C;
        int c_idx = i_c % C;
        int h_idx = c_idx / hs;
        int d_idx = c_idx % hs;

        // target is (B, nh, T, hs)
        int target_idx = i_b * (nh * T * hs) + h_idx * (T * hs) + i_t * hs + d_idx;

        if (qkv_idx == 0) q[target_idx] = input[idx];
        else if (qkv_idx == 1) k[target_idx] = input[idx];
        else v[target_idx] = input[idx];
    }
}

__global__ void scale_mask_relu_kernel(float* att, float scale, int T, int total_size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_size) {
        int row = (idx / T) % T;
        int col = idx % T;

        // Causal mask: only apply where col <= row
        if (col > row) {
            att[idx] = 0.0f;
        } else {
            float val = att[idx] * scale;
            att[idx] = (val > 0.0f) ? val : 0.0f;
        }
    }
