__global__ void merge_heads_kernel(const float* y, float* out, int B, int nh, int T, int hs) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int C = nh * hs;
    int total = B * nh * T * hs;
    if (idx < total) {
        // y is (B, nh, T, hs)
        int d_idx = idx % hs;
        int t_idx = (idx / hs) % T;
        int h_idx = (idx / (hs * T)) % nh;
        int b_idx = idx / (hs * T * nh);

        // target is (B, T, C)
        int target_idx = b_idx * (T * C) + t_idx * C + h_idx * hs + d_idx;
        out[target_idx] = y[idx];
    }
